INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12395, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "档案", "is_correct": true, "explanation": "正确：档案指机关或单位分类保存的文件材料，员工档案存放在人事部，符合句意。"}, {"text": "水果", "is_correct": false, "explanation": "语义：水果是食物，不是员工的文件材料，不会存放在人事部。"}, {"text": "外貌", "is_correct": false, "explanation": "体貌：外貌指人的外表，无法存放在人事部，与句中的存放义不符。"}, {"text": "菜谱", "is_correct": false, "explanation": "语义：菜谱是烹饪用的记录，与员工无关，句中指人事部保存的材料。"}], "explanations": {"档案": "正确：档案指机关或单位分类保存的文件材料，员工档案存放在人事部，符合句意。", "水果": "语义：水果是食物，不是员工的文件材料，不会存放在人事部。", "外貌": "体貌：外貌指人的外表，无法存放在人事部，与句中的存放义不符。", "菜谱": "语义：菜谱是烹饪用的记录，与员工无关，句中指人事部保存的材料。"}, "sentence_index": 0, "correct_answer": "档案"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "天冷了，他穿上了一件厚档案。", "explanation": "这里应该用〈外套〉。天冷穿的是外套，档案是机关或单位保存的文件材料，不能穿在身上。"}, {"text": "他在超市里买了一些档案，准备做晚饭。", "explanation": "这里应该用〈食材〉。超市买来做晚饭的是食材，档案是机关或单位保存的材料，不能拿来做饭。"}, {"text": "他买完东西，店员给了他一份档案。", "explanation": "这里应该用〈收据〉。购物凭证叫收据，档案是机关或单位保存的材料，店员不会开给顾客。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '54ba7f5d-a0b0-46b1-8110-2a1fda43a544') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12395, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "档案", "is_correct": true, "explanation": "正确：档案是学校或机关保存的个人记录，老师想看的是这个孩子的档案，符合句意。"}, {"text": "声音", "is_correct": false, "explanation": "搭配：“看看”一般用于看得见的东西，“声音”要用“听”，不能说“看看声音”。"}, {"text": "月亮", "is_correct": false, "explanation": "语义：月亮是天体，不属于孩子的物品，句中要看的是档案。"}, {"text": "空气", "is_correct": false, "explanation": "语义：空气是无形的气体，不能作为“孩子的”东西去检查。"}], "explanations": {"档案": "正确：档案是学校或机关保存的个人记录，老师想看的是这个孩子的档案，符合句意。", "声音": "搭配：“看看”一般用于看得见的东西，“声音”要用“听”，不能说“看看声音”。", "月亮": "语义：月亮是天体，不属于孩子的物品，句中要看的是档案。", "空气": "语义：空气是无形的气体，不能作为“孩子的”东西去检查。"}, "sentence_index": 6, "correct_answer": "档案"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我的数学档案提高了很多。", "explanation": "这里应该用〈成绩〉。档案是保存的文件，不能说“提高”；学习的进步才用“提高”，说成绩提高。"}, {"text": "他用档案修理了桌子。", "explanation": "这里应该用〈工具〉。修理桌子要用工具，档案是机关或单位保存的文件，不能用来修东西。"}, {"text": "她每天在厨房里炒档案。", "explanation": "这里应该用〈菜〉。炒的是食材，档案是机关或单位保存的文件，不能拿来炒。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '54ba7f5d-a0b0-46b1-8110-2a1fda43a544') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12395, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "人事部已经把新员工的一只档案整理好了。", "corrected_sentence": "人事部已经把新员工的一份档案整理好了。", "error_description": "量词错误：档案应用“份”计量，“只”多用于动物或成对的东西，应说“一份档案”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '54ba7f5d-a0b0-46b1-8110-2a1fda43a544') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12395, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她的桌上放着一份的档案。", "corrected_sentence": "她的桌上放着一份档案。", "error_description": "结构助词错误：数量短语“一份”后不能直接加“的”，应说“一份档案”，“的”不能插在“一份”与名词之间。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '54ba7f5d-a0b0-46b1-8110-2a1fda43a544') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12396, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "口头", "is_correct": true, "explanation": "反义：书面指用文字表达，口头指用语言说出，两者相对。"}, {"text": "迅速", "is_correct": false, "explanation": "与“书面”没有反义关系，只形容速度快。"}, {"text": "辽阔", "is_correct": false, "explanation": "与“书面”没有反义关系，形容面积广大。"}, {"text": "清晰", "is_correct": false, "explanation": "与“书面”没有反义关系，形容清楚明白。"}], "correct_answer": "口头", "explanations": {"口头": "反义：书面指用文字表达，口头指用语言说出，两者相对。", "迅速": "与“书面”没有反义关系，只形容速度快。", "辽阔": "与“书面”没有反义关系，形容面积广大。", "清晰": "与“书面”没有反义关系，形容清楚明白。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '54ba7f5d-a0b0-46b1-8110-2a1fda43a544') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12396, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "口头", "is_correct": true, "explanation": "反义：书面指用文字表达，口头指用语言说出，两者相对。"}, {"text": "沉重", "is_correct": false, "explanation": "与“书面”没有反义关系，形容分量大或心情压抑。"}, {"text": "温暖", "is_correct": false, "explanation": "与“书面”没有反义关系，形容温度或感受。"}, {"text": "明亮", "is_correct": false, "explanation": "与“书面”没有反义关系，形容光线充足。"}], "correct_answer": "口头", "explanations": {"口头": "反义：书面指用文字表达，口头指用语言说出，两者相对。", "沉重": "与“书面”没有反义关系，形容分量大或心情压抑。", "温暖": "与“书面”没有反义关系，形容温度或感受。", "明亮": "与“书面”没有反义关系，形容光线充足。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '54ba7f5d-a0b0-46b1-8110-2a1fda43a544') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12396, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "用文字形式表达的（相对于口头）", "primary_collocate": null, "pronunciation": "shū miàn", "ipa": "ʂu˥ mjɛn˥˩", "syllable_count": 2, "sentences": [{"text": "这次会议的内容要留下书面记录。", "target_word": "书面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把你的意见写成书面报告。", "target_word": "书面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事公司会给你书面通知。", "target_word": "书面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师让我们交一份书面作业。", "target_word": "书面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用书面形式回答了问题。", "target_word": "书面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "买房时要签书面合同。", "target_word": "书面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想要你的书面答复。", "target_word": "书面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次考试有书面和口头两部分。", "target_word": "书面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他向学校提出了书面申请。", "target_word": "书面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请用书面方式告诉大家。", "target_word": "书面", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "书面语", "label": "复合"}, {"form": "書面", "label": "繁体"}], "register": "书面语", "sense_fingerprint": "用文字形式表达的，与口头相对（书面通知、书面报告）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4da4f6c8-6bbf-4c97-a4e8-ea8e0f7f3746') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12396, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "书面", "is_correct": true, "explanation": "正确：书面指用文字表达的，“书面记录”指用文字留下的记录，符合句意。"}, {"text": "安静", "is_correct": false, "explanation": "语义：安静描述声音或环境，不能修饰文字形式的记录。"}, {"text": "清澈", "is_correct": false, "explanation": "搭配：“清澈”多用于水、眼睛等，不能说“清澈的记录”。"}, {"text": "高大", "is_correct": false, "explanation": "体貌：“高大”形容人或物的体型，不能修饰“记录”。"}], "explanations": {"书面": "正确：书面指用文字表达的，“书面记录”指用文字留下的记录，符合句意。", "安静": "语义：安静描述声音或环境，不能修饰文字形式的记录。", "清澈": "搭配：“清澈”多用于水、眼睛等，不能说“清澈的记录”。", "高大": "体貌：“高大”形容人或物的体型，不能修饰“记录”。"}, "sentence_index": 0, "correct_answer": "书面"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这次会议的气氛很书面。", "explanation": "这里应该用〈正式〉。书面指用文字表达，与口头相对，不指庄重的程度；会议的庄重要用“正式”。"}, {"text": "大家书面地唱起了国歌。", "explanation": "这里应该用〈齐声〉。唱国歌是出声的，“书面”指用文字表达，两者矛盾，应说“齐声唱”。"}, {"text": "他的表情很书面。", "explanation": "这里应该用〈严肃〉。书面只描述文字形式，不能形容人的表情；表情郑重要用“严肃”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '54ba7f5d-a0b0-46b1-8110-2a1fda43a544') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12396, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "书面", "is_correct": true, "explanation": "正确：书面答复指用文字写下的回复，符合句意。"}, {"text": "咸", "is_correct": false, "explanation": "语义：咸是味道，不能修饰“答复”，句中指用文字的回复。"}, {"text": "甜", "is_correct": false, "explanation": "搭配：“甜”多用于描述食物的味道，不与“答复”搭配。"}, {"text": "胖", "is_correct": false, "explanation": "体貌：“胖”形容人的体形，不能修饰“答复”。"}], "explanations": {"书面": "正确：书面答复指用文字写下的回复，符合句意。", "咸": "语义：咸是味道，不能修饰“答复”，句中指用文字的回复。", "甜": "搭配：“甜”多用于描述食物的味道，不与“答复”搭配。", "胖": "体貌：“胖”形容人的体形，不能修饰“答复”。"}, "sentence_index": 6, "correct_answer": "书面"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这次开幕式很书面。", "explanation": "这里应该用〈隆重〉。书面指用文字表达，不指场面的盛大；开幕式的场面要用“隆重”。"}, {"text": "这个小孩的歌声很书面。", "explanation": "这里应该用〈动听〉。书面指用文字表达，不能形容声音的好坏；歌声好听要用“动听”。"}, {"text": "这座纪念碑显得很书面。", "explanation": "这里应该用〈庄严〉。书面只描述文字形式，纪念碑的庄重气氛要用“庄严”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '54ba7f5d-a0b0-46b1-8110-2a1fda43a544') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12396, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他交了一条书面报告。", "corrected_sentence": "他交了一份书面报告。", "error_description": "量词错误：“报告”应用“份”计量，“条”不能用于书面报告，应说“一份书面报告”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '54ba7f5d-a0b0-46b1-8110-2a1fda43a544') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12396, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们需要一本书面证明。", "corrected_sentence": "我们需要一份书面证明。", "error_description": "量词错误：“证明”应用“份”计量，“本”用于书册，应说“一份书面证明”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '54ba7f5d-a0b0-46b1-8110-2a1fda43a544') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
