INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12397, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "影像指通过光学或电子设备记录下来的图像，如照片、视频中的视觉内容。", "primary_collocate": null, "pronunciation": "yǐng xiàng", "ipa": "iŋ˨˩˦ ɕjɑŋ˥˩", "syllable_count": 2, "sentences": [{"text": "这台相机能拍出清楚的影像。", "target_word": "影像", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "屏幕上出现了一段模糊的影像。", "target_word": "影像", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察看了现场的监控影像。", "target_word": "影像", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想把那段影像保存下来。", "target_word": "影像", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手机里存着很多旅行的影像。", "target_word": "影像", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生用影像检查病人的身体。", "target_word": "影像", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "影像太暗，我们看不清人脸。", "target_word": "影像", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些影像是去年夏天拍的。", "target_word": "影像", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师给我们放了一段历史影像。", "target_word": "影像", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手机坏了，我丢了那段影像。", "target_word": "影像", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一段影像", "label": "量词"}, {"form": "影像资料", "label": "复合"}], "register": "中性", "sense_fingerprint": "光学或电子设备记录的图像（监控影像、医学影像）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4da4f6c8-6bbf-4c97-a4e8-ea8e0f7f3746') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12397, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "影像", "is_correct": true, "explanation": "正确：影像，指通过设备记录下来的图像。"}, {"text": "影响", "is_correct": false, "explanation": "xiǎng 与 xiàng 声调不同（第三声与第四声），意思是对事物产生的作用。"}, {"text": "引向", "is_correct": false, "explanation": "yǐn 与 yǐng 韵母不同（in 与 ing），意思是引导朝某个方向。"}, {"text": "迎向", "is_correct": false, "explanation": "yíng 与 yǐng 声调不同（第二声与第三声），意思是迎着某个方向。"}], "explanations": {"影像": "正确：影像，指通过设备记录下来的图像。", "影响": "xiǎng 与 xiàng 声调不同（第三声与第四声），意思是对事物产生的作用。", "引向": "yǐn 与 yǐng 韵母不同（in 与 ing），意思是引导朝某个方向。", "迎向": "yíng 与 yǐng 声调不同（第二声与第三声），意思是迎着某个方向。"}, "sentence_index": null, "correct_answer": "影像"}, "level_3": {"options": [{"text": "影像", "is_correct": true, "explanation": "正确：影像指拍摄得到的画面，可以说“拍出清楚的”。"}, {"text": "声音", "is_correct": false, "explanation": "搭配：“拍出”的对象是可见的画面，相机拍不出“清楚的声音”。"}, {"text": "味道", "is_correct": false, "explanation": "语义：味道是嗅觉感受，无法被相机记录，与“拍出”不相容。"}, {"text": "体重", "is_correct": false, "explanation": "语义：体重是数值，与拍摄无关，“拍出清楚的体重”说不通。"}], "explanations": {"影像": "正确：影像指拍摄得到的画面，可以说“拍出清楚的”。", "声音": "搭配：“拍出”的对象是可见的画面，相机拍不出“清楚的声音”。", "味道": "语义：味道是嗅觉感受，无法被相机记录，与“拍出”不相容。", "体重": "语义：体重是数值，与拍摄无关，“拍出清楚的体重”说不通。"}, "sentence_index": 0, "correct_answer": "影像"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他每天早上用影像刷牙。", "explanation": "这里应该用〈牙膏〉。刷牙要用牙膏，影像是记录下来的画面，不能用来刷牙。"}, {"text": "他喝了一口影像。", "explanation": "这里应该用〈饮料〉。喝的是饮料，影像是记录下来的画面，不能用来喝。"}, {"text": "这件事对他的成长有很大影像。", "explanation": "这里应该用〈影响〉。影像指画面，“有很大……”说的是作用，要用〈影响〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '54ba7f5d-a0b0-46b1-8110-2a1fda43a544') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12397, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "影像", "is_correct": true, "explanation": "正确：影像，指通过设备记录下来的图像。"}, {"text": "景象", "is_correct": false, "explanation": "jǐng 与 yǐng 声母不同（j 与零声母），声调相同，意思是景色、场面。"}, {"text": "印象", "is_correct": false, "explanation": "yìn xiàng 与 yǐng xiàng 韵尾不同（n 与 ng），声调也不同，意思是给人留下的感受。"}, {"text": "影响", "is_correct": false, "explanation": "xiǎng 与 xiàng 声调不同（第三声与第四声），意思是对事物产生的作用。"}], "explanations": {"影像": "正确：影像，指通过设备记录下来的图像。", "景象": "jǐng 与 yǐng 声母不同（j 与零声母），声调相同，意思是景色、场面。", "印象": "yìn xiàng 与 yǐng xiàng 韵尾不同（n 与 ng），声调也不同，意思是给人留下的感受。", "影响": "xiǎng 与 xiàng 声调不同（第三声与第四声），意思是对事物产生的作用。"}, "sentence_index": null, "correct_answer": "影像"}, "level_3": {"options": [{"text": "影像", "is_correct": true, "explanation": "正确：影像指拍下的画面，“太暗”“看不清人脸”都说的是画面的明暗清晰。"}, {"text": "脚步", "is_correct": false, "explanation": "搭配：“暗”修饰光线或颜色，不能修饰脚步。"}, {"text": "气味", "is_correct": false, "explanation": "语义：气味与光线明暗无关，“气味太暗”说不通。"}, {"text": "旋律", "is_correct": false, "explanation": "语义：旋律是听觉的，与“看不清人脸”的视觉语境无关。"}], "explanations": {"影像": "正确：影像指拍下的画面，“太暗”“看不清人脸”都说的是画面的明暗清晰。", "脚步": "搭配：“暗”修饰光线或颜色，不能修饰脚步。", "气味": "语义：气味与光线明暗无关，“气味太暗”说不通。", "旋律": "语义：旋律是听觉的，与“看不清人脸”的视觉语境无关。"}, "sentence_index": 6, "correct_answer": "影像"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他每天骑影像去上学。", "explanation": "这里应该用〈自行车〉。骑的是自行车，影像是记录下来的画面，不能用来骑。"}, {"text": "妈妈用影像炒菜。", "explanation": "这里应该用〈锅〉。炒菜要用锅，影像是记录下来的画面，不能用来炒菜。"}, {"text": "他用影像打开了门。", "explanation": "这里应该用〈钥匙〉。开门要用钥匙，影像是记录下来的画面，不能用来开门。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '54ba7f5d-a0b0-46b1-8110-2a1fda43a544') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12397, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只影像拍得很清楚。", "corrected_sentence": "这段影像拍得很清楚。", "error_description": "“这只影像”量词错误：影像的量词是“段”，“只”不能用于影像，应为“这段影像”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '54ba7f5d-a0b0-46b1-8110-2a1fda43a544') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12397, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我把这本影像传给了朋友。", "corrected_sentence": "我把这段影像传给了朋友。", "error_description": "量词错误：影像的量词是“段”，“本”用于书册，不能用于影像，应说“这段影像”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '54ba7f5d-a0b0-46b1-8110-2a1fda43a544') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
