INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12398, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "副词，表示动作或状态并没有发生（书面语），相当于‘并没有’。", "primary_collocate": null, "pronunciation": "bìng wèi", "ipa": "pɪŋ˥˩ weɪ˥˩", "syllable_count": 2, "sentences": [{"text": "他并未参加昨天的会议。", "target_word": "并未", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事我并未告诉任何人。", "target_word": "并未", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生说他的病并未好转。", "target_word": "并未", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雨下了一夜，地上并未积水。", "target_word": "并未", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她并未因为失败而放弃。", "target_word": "并未", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司并未公布今年的计划。", "target_word": "并未", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我并未听到有人敲门。", "target_word": "并未", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师并未批评他，只是提醒了一下。", "target_word": "并未", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "虽然搬了家，他们的关系并未改变。", "target_word": "并未", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个消息并未引起大家的注意。", "target_word": "并未", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "并未：书面副词，否定动作或状态已经发生", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4da4f6c8-6bbf-4c97-a4e8-ea8e0f7f3746') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12398, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "并未", "is_correct": true, "explanation": "正确：并未，书面副词，表示否定动作或状态已经发生。"}, {"text": "病危", "is_correct": false, "explanation": "bìng wēi 与 bìng wèi 第二音节声调不同（第一声与第四声），意思是病情十分危险。"}, {"text": "并为", "is_correct": false, "explanation": "bìng wéi 与 bìng wèi 第二音节声调不同（第二声与第四声），意思是合并成为。"}, {"text": "兵卫", "is_correct": false, "explanation": "bīng 与 bìng 声调不同（第一声与第四声），意思是守卫的士兵。"}], "explanations": {"并未": "正确：并未，书面副词，表示否定动作或状态已经发生。", "病危": "bìng wēi 与 bìng wèi 第二音节声调不同（第一声与第四声），意思是病情十分危险。", "并为": "bìng wéi 与 bìng wèi 第二音节声调不同（第二声与第四声），意思是合并成为。", "兵卫": "bīng 与 bìng 声调不同（第一声与第四声），意思是守卫的士兵。"}, "sentence_index": null, "correct_answer": "并未"}, "level_3": {"options": [{"text": "并未", "is_correct": true, "explanation": "正确：“并未”否定“参加昨天的会议”这一已发生的事，与“昨天”吻合。"}, {"text": "正在", "is_correct": false, "explanation": "语义：“正在”表示动作进行中，与“昨天”这一已过去的时间矛盾。"}, {"text": "一直", "is_correct": false, "explanation": "搭配：“一直”要与持续的时段搭配，“昨天”是时间点，不能搭配。"}, {"text": "必定", "is_correct": false, "explanation": "语义：“必定”指将来的确定，与“昨天”这一已过去的时间矛盾。"}], "explanations": {"并未": "正确：“并未”否定“参加昨天的会议”这一已发生的事，与“昨天”吻合。", "正在": "语义：“正在”表示动作进行中，与“昨天”这一已过去的时间矛盾。", "一直": "搭配：“一直”要与持续的时段搭配，“昨天”是时间点，不能搭配。", "必定": "语义：“必定”指将来的确定，与“昨天”这一已过去的时间矛盾。"}, "sentence_index": 0, "correct_answer": "并未"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这并未是我的错。", "explanation": "这里应该用〈并不是〉。并未表示已经发生的动作没有发生，判断句“是……”的否定要用〈并不是〉。"}, {"text": "下个星期他并未来上课。", "explanation": "这里应该用〈不会〉。并未只用于已经发生的事，“下个星期”指将来，要用〈不会〉。"}, {"text": "他并未太喜欢辣的东西。", "explanation": "这里应该用〈不太〉。并未否定已经发生的事，“太喜欢”是程度搭配，要用〈不太〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '54ba7f5d-a0b0-46b1-8110-2a1fda43a544') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12398, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "并未", "is_correct": true, "explanation": "正确：“并未”否定“听到”这一已发生的结果，与句意吻合。"}, {"text": "故意", "is_correct": false, "explanation": "语义：“听到”是无意的感知，不能“故意”听到。"}, {"text": "仔细", "is_correct": false, "explanation": "搭配：“仔细”修饰有意的动作，不能修饰“听到”这类结果。"}, {"text": "拼命", "is_correct": false, "explanation": "搭配：“拼命”修饰用力的动作，不能修饰“听到”。"}], "explanations": {"并未": "正确：“并未”否定“听到”这一已发生的结果，与句意吻合。", "故意": "语义：“听到”是无意的感知，不能“故意”听到。", "仔细": "搭配：“仔细”修饰有意的动作，不能修饰“听到”这类结果。", "拼命": "搭配：“拼命”修饰用力的动作，不能修饰“听到”。"}, "sentence_index": 6, "correct_answer": "并未"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "要是下雨，我们就并未去公园。", "explanation": "这里应该用〈不〉。并未只否定已经发生的事，假设中的将来情况要用〈不〉。"}, {"text": "明天他并未来。", "explanation": "这里应该用〈不会〉。并未用于已经发生的事，“明天”指将来，要用〈不会〉。"}, {"text": "我并未太会做饭。", "explanation": "这里应该用〈不太会〉。并未只否定已经发生的事，“太会做饭”是程度搭配，要用〈不太会〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '54ba7f5d-a0b0-46b1-8110-2a1fda43a544') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12398, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我也没并未收到回信。", "corrected_sentence": "我也并未收到回信。", "error_description": "“没并未”双重否定：“并未”已表示否定，前面不能再加“没”，应为“我也并未收到回信”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '54ba7f5d-a0b0-46b1-8110-2a1fda43a544') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12398, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他很并未通知我们。", "corrected_sentence": "他并未通知我们。", "error_description": "“很并未”错误：“并未”是否定副词，不能受程度副词“很”修饰，应去掉“很”，为“他并未通知我们”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '54ba7f5d-a0b0-46b1-8110-2a1fda43a544') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12399, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "产生", "is_correct": true, "explanation": "正确：“产生”与“消亡”相反，指事物开始出现、存在。"}, {"text": "思考", "is_correct": false, "explanation": "“思考”与“消亡”在任何义项上都不构成反义，二者无关。"}, {"text": "漂浮", "is_correct": false, "explanation": "“漂浮”指浮在液体或空中，与“消亡”没有相对关系。"}, {"text": "翻译", "is_correct": false, "explanation": "“翻译”指转换语言，与“消亡”没有相对关系。"}], "correct_answer": "产生", "explanations": {"产生": "正确：“产生”与“消亡”相反，指事物开始出现、存在。", "思考": "“思考”与“消亡”在任何义项上都不构成反义，二者无关。", "漂浮": "“漂浮”指浮在液体或空中，与“消亡”没有相对关系。", "翻译": "“翻译”指转换语言，与“消亡”没有相对关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '54ba7f5d-a0b0-46b1-8110-2a1fda43a544') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12399, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "兴起", "is_correct": true, "explanation": "正确：“兴起”与“消亡”相反，指事物开始兴盛、出现。"}, {"text": "游玩", "is_correct": false, "explanation": "“游玩”指出去玩耍，与“消亡”在任何义项上都没有反义关系。"}, {"text": "清洗", "is_correct": false, "explanation": "“清洗”指用水等去除污垢，与“消亡”没有相对关系。"}, {"text": "写作", "is_correct": false, "explanation": "“写作”指写文章，与“消亡”没有相对关系。"}], "correct_answer": "兴起", "explanations": {"兴起": "正确：“兴起”与“消亡”相反，指事物开始兴盛、出现。", "游玩": "“游玩”指出去玩耍，与“消亡”在任何义项上都没有反义关系。", "清洗": "“清洗”指用水等去除污垢，与“消亡”没有相对关系。", "写作": "“写作”指写文章，与“消亡”没有相对关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '54ba7f5d-a0b0-46b1-8110-2a1fda43a544') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12399, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "指事物逐渐消失，最终不复存在。", "primary_collocate": null, "pronunciation": "xiāo wáng", "ipa": "ɕiɑʊ˥ wɑŋ˧˥", "syllable_count": 2, "sentences": [{"text": "在全球化与数字化的当代，尽管书面记录与影像媒介主导了信息传播，口头叙事并未消亡，而是以新的形态回归：播客、口述史项目、非物质文化遗产保护运动，皆可视作对原始交流模式的现代回响。", "target_word": "消亡", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "很多古老的语言正在慢慢消亡。", "target_word": "消亡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "恐龙为什么会在地球上消亡？", "target_word": "消亡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这门濒临失传的技艺，若无人传授，终将消亡。", "target_word": "消亡", "complexity_tier": "T3", "furigana": "zhè mén bīn lín shī chuán de jì yì, ruò wú rén chuán shòu, zhōng jiāng xiāo wáng.", "sentence_source": "generated"}, {"text": "随着城市发展，一些小村庄逐渐消亡了。", "target_word": "消亡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有人担心方言会随着老人离开而消亡。", "target_word": "消亡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种古老的宗教仪式在近代逐渐消亡。", "target_word": "消亡", "complexity_tier": "T3", "furigana": "zhè zhǒng gǔ lǎo de zōng jiào yí shì zài jìn dài zhú jiàn xiāo wáng.", "sentence_source": "generated"}, {"text": "旧的习惯消亡，新的习惯出现。", "target_word": "消亡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "没有人使用的文字，最后会消亡。", "target_word": "消亡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种小鸟早在一百年前就消亡了。", "target_word": "消亡", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "消亡：书面动词，事物逐渐消失直至不复存在", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4da4f6c8-6bbf-4c97-a4e8-ea8e0f7f3746') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12399, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "消亡", "is_correct": true, "explanation": "正确答案：消亡（xiāo wáng），指事物逐渐消失、最终不复存在。"}, {"text": "小王", "is_correct": false, "explanation": "xiǎo（第三声）与 xiāo（第一声）声调不同，意思是小王（年幼的国王或对人的称呼）。"}, {"text": "销往", "is_correct": false, "explanation": "wǎng（第三声）与 wáng（第二声）声调不同，意思是销往（卖到某地）。"}, {"text": "消防", "is_correct": false, "explanation": "fáng 与 wáng 声母不同（f 与 w），意思是消防（预防和扑救火灾）。"}], "explanations": {"消亡": "正确答案：消亡（xiāo wáng），指事物逐渐消失、最终不复存在。", "小王": "xiǎo（第三声）与 xiāo（第一声）声调不同，意思是小王（年幼的国王或对人的称呼）。", "销往": "wǎng（第三声）与 wáng（第二声）声调不同，意思是销往（卖到某地）。", "消防": "fáng 与 wáng 声母不同（f 与 w），意思是消防（预防和扑救火灾）。"}, "sentence_index": null, "correct_answer": "消亡"}, "level_3": {"options": [{"text": "消亡", "is_correct": true, "explanation": "正确：“消亡”指事物逐渐不复存在；后句“而是以新的形态回归”说明叙事没有消失，只是换了形式。"}, {"text": "诞生", "is_correct": false, "explanation": "语义：“诞生”指从无到有地出现，与后句“回归”（回到原来的状态）相矛盾，叙事并非新生。"}, {"text": "降临", "is_correct": false, "explanation": "语义：“降临”指从外而来、来到某处（多用于夜幕、幸福、灾难），与叙事“并未消亡、而是以新的形态回归”的语境不合。"}, {"text": "出生", "is_correct": false, "explanation": "搭配：“出生”只用于人或动物等生命体的诞生，不用于口头叙事。"}], "explanations": {"消亡": "正确：“消亡”指事物逐渐不复存在；后句“而是以新的形态回归”说明叙事没有消失，只是换了形式。", "诞生": "语义：“诞生”指从无到有地出现，与后句“回归”（回到原来的状态）相矛盾，叙事并非新生。", "降临": "语义：“降临”指从外而来、来到某处（多用于夜幕、幸福、灾难），与叙事“并未消亡、而是以新的形态回归”的语境不合。", "出生": "搭配：“出生”只用于人或动物等生命体的诞生，不用于口头叙事。"}, "sentence_index": 0, "correct_answer": "消亡"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我的钥匙不知何时消亡了。", "explanation": "这里应该用〈消失〉。消亡指事物逐渐不复存在，多用于物种、文化、制度等；钥匙不见了应说消失。"}, {"text": "时间悄悄消亡了。", "explanation": "这里应该用〈消逝〉。消逝多用于时间、光阴、声音等无形之物；消亡用于有存在形态的事物，时间不说消亡。"}, {"text": "疑虑终于消亡了。", "explanation": "这里应该用〈消散〉。消散用于疑虑、怒气、雾气等；消亡不用于心理或情绪。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '54ba7f5d-a0b0-46b1-8110-2a1fda43a544') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12399, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "消亡", "is_correct": true, "explanation": "正确答案：消亡（xiāo wáng），指事物逐渐消失、最终不复存在。"}, {"text": "妖王", "is_correct": false, "explanation": "yāo（第一声）与 xiāo 首音不同（y 与 x），意思是妖王（妖怪之王）。"}, {"text": "消长", "is_correct": false, "explanation": "cháng（第二声）与 wáng 声母不同（ch 与 w），意思是消长（增减与盛衰）。"}, {"text": "先王", "is_correct": false, "explanation": "xiān（第一声）与 xiāo 韵母不同（ian 与 iao），意思是先王（已故的君王）。"}], "explanations": {"消亡": "正确答案：消亡（xiāo wáng），指事物逐渐消失、最终不复存在。", "妖王": "yāo（第一声）与 xiāo 首音不同（y 与 x），意思是妖王（妖怪之王）。", "消长": "cháng（第二声）与 wáng 声母不同（ch 与 w），意思是消长（增减与盛衰）。", "先王": "xiān（第一声）与 xiāo 韵母不同（ian 与 iao），意思是先王（已故的君王）。"}, "sentence_index": null, "correct_answer": "消亡"}, "level_3": {"options": [{"text": "消亡", "is_correct": true, "explanation": "正确：“消亡”指事物逐渐不复存在，与“逐渐”相配，符合仪式逐渐衰亡的语境。"}, {"text": "出版", "is_correct": false, "explanation": "搭配：“出版”的对象是书籍、报刊等，不能说“宗教仪式出版”。"}, {"text": "加剧", "is_correct": false, "explanation": "语义：“加剧”多指矛盾、问题、疾病等负面情况加重，与“逐渐”后的仪式不搭。"}, {"text": "歼灭", "is_correct": false, "explanation": "配价：“歼灭”是及物动词，要求施事（人或军队）作主语，不能让仪式自行“歼灭”。"}], "explanations": {"消亡": "正确：“消亡”指事物逐渐不复存在，与“逐渐”相配，符合仪式逐渐衰亡的语境。", "出版": "搭配：“出版”的对象是书籍、报刊等，不能说“宗教仪式出版”。", "加剧": "语义：“加剧”多指矛盾、问题、疾病等负面情况加重，与“逐渐”后的仪式不搭。", "歼灭": "配价：“歼灭”是及物动词，要求施事（人或军队）作主语，不能让仪式自行“歼灭”。"}, "sentence_index": 6, "correct_answer": "消亡"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他在三十岁时消亡了。", "explanation": "这里应该用〈死亡〉。消亡用于事物逐渐不复存在，不用于人的生命结束。"}, {"text": "蜡烛在风中消亡了。", "explanation": "这里应该用〈熄灭〉。火焰、灯火、蜡烛停止燃烧用熄灭，消亡不用于此。"}, {"text": "人群渐渐消亡了。", "explanation": "这里应该用〈散去〉。人群离开用散去，消亡不用于人群。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '54ba7f5d-a0b0-46b1-8110-2a1fda43a544') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12399, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这种古老的语言被消亡了。", "corrected_sentence": "这种古老的语言消亡了。", "error_description": "错误：“被消亡”。“消亡”是不及物动词，不能加“被”构成被动句；应说“这种古老的语言消亡了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '54ba7f5d-a0b0-46b1-8110-2a1fda43a544') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12399, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们的方言把消亡了。", "corrected_sentence": "我们的方言消亡了。", "error_description": "错误：“把消亡”。“消亡”是不及物动词，不能用于把字句；应去掉“把”，说“我们的方言消亡了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '54ba7f5d-a0b0-46b1-8110-2a1fda43a544') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12400, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '54ba7f5d-a0b0-46b1-8110-2a1fda43a544') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12400, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '54ba7f5d-a0b0-46b1-8110-2a1fda43a544') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12400, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "指返回、回到原来的位置或状态。", "primary_collocate": null, "pronunciation": "huí guī", "ipa": "xweɪ˧˥ kweɪ˥", "syllable_count": 2, "sentences": [{"text": "他离开多年后又回归了家乡。", "target_word": "回归", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很多年轻人毕业后选择回归农村。", "target_word": "回归", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "受伤的球星终于回归球队了。", "target_word": "回归", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经过长途旅行，他回归平静的生活。", "target_word": "回归", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "离开一年的老朋友又回归了团队。", "target_word": "回归", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她放下工作，回归家庭。", "target_word": "回归", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位歌手休息三年后回归舞台。", "target_word": "回归", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "假期结束，大家回归校园。", "target_word": "回归", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "病好后，他回归正常的生活。", "target_word": "回归", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "香港于一九九七年回归祖国。", "target_word": "回归", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "回归：动词，回到原来的位置或状态", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4da4f6c8-6bbf-4c97-a4e8-ea8e0f7f3746') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12400, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "回归", "is_correct": true, "explanation": "正确答案：回归（huí guī），指回到原来的位置或状态。"}, {"text": "回国", "is_correct": false, "explanation": "guó（第二声）与 guī 韵母不同（uo 与 ui），声调也不同，意思是回国（回到自己的国家）。"}, {"text": "回锅", "is_correct": false, "explanation": "guō（第一声）与 guī 韵母不同（uo 与 ui），意思是回锅（食物再次加热）。"}, {"text": "汇归", "is_correct": false, "explanation": "声调混淆：huì（第四声）与 huí（第二声）声调不同，其余音节相同；汇归指水流等汇入某处。"}], "explanations": {"回归": "正确答案：回归（huí guī），指回到原来的位置或状态。", "回国": "guó（第二声）与 guī 韵母不同（uo 与 ui），声调也不同，意思是回国（回到自己的国家）。", "回锅": "guō（第一声）与 guī 韵母不同（uo 与 ui），意思是回锅（食物再次加热）。", "汇归": "声调混淆：huì（第四声）与 huí（第二声）声调不同，其余音节相同；汇归指水流等汇入某处。"}, "sentence_index": null, "correct_answer": "回归"}, "level_3": {"options": [{"text": "回归", "is_correct": true, "explanation": "正确：“回归”指回到原来的地方，与“离开多年后”相呼应。"}, {"text": "诞生", "is_correct": false, "explanation": "配价：“诞生”是不及物动词，不带宾语，不能说“又诞生了家乡”。"}, {"text": "生育", "is_correct": false, "explanation": "搭配：“生育”的对象是子女，不能用于家乡。"}, {"text": "盛行", "is_correct": false, "explanation": "搭配：“盛行”用于风气、习俗、思潮，不能说“又盛行了家乡”。"}], "explanations": {"回归": "正确：“回归”指回到原来的地方，与“离开多年后”相呼应。", "诞生": "配价：“诞生”是不及物动词，不带宾语，不能说“又诞生了家乡”。", "生育": "搭配：“生育”的对象是子女，不能用于家乡。", "盛行": "搭配：“盛行”用于风气、习俗、思潮，不能说“又盛行了家乡”。"}, "sentence_index": 0, "correct_answer": "回归"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这些资料可以回归为三类。", "explanation": "这里应该用〈归纳〉。回归指回到原来的位置或状态，不表示把材料整理归类；把资料按类别整理要用归纳。"}, {"text": "他回归了新的阶段。", "explanation": "这里应该用〈进入〉。回归指回到原来的状态，开启新的阶段应说进入。"}, {"text": "他在北京回归了三天。", "explanation": "这里应该用〈逗留〉。回归表示回到原处，不表示在某地停留多久。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '54ba7f5d-a0b0-46b1-8110-2a1fda43a544') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12400, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "回归", "is_correct": true, "explanation": "正确：“回归”指回到原来的位置或状态，符合歌手重返舞台的语境。"}, {"text": "替代", "is_correct": false, "explanation": "语义：“替代”要说明替代了谁或什么，“歌手替代舞台”与语境不符。"}, {"text": "降临", "is_correct": false, "explanation": "搭配：“降临”多与夜幕、幸福、灾难等从外而来的事搭配，不用于歌手重返舞台。"}, {"text": "撤离", "is_correct": false, "explanation": "语义：“撤离”指离开某地，与“休息三年后重返舞台”的方向相反。"}], "explanations": {"回归": "正确：“回归”指回到原来的位置或状态，符合歌手重返舞台的语境。", "替代": "语义：“替代”要说明替代了谁或什么，“歌手替代舞台”与语境不符。", "降临": "搭配：“降临”多与夜幕、幸福、灾难等从外而来的事搭配，不用于歌手重返舞台。", "撤离": "语义：“撤离”指离开某地，与“休息三年后重返舞台”的方向相反。"}, "sentence_index": 6, "correct_answer": "回归"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他终于回归了欠款。", "explanation": "这里应该用〈偿还〉。回归指回到原来的位置或状态，不表示还钱；还清欠款要用偿还。"}, {"text": "售货员回归了他找的零钱。", "explanation": "这里应该用〈找回〉。回归指回到原来的位置或状态，不用于收到找零的情形；顾客拿回找零应说找回。"}, {"text": "学生们今天回归了作业。", "explanation": "这里应该用〈交〉。回归指回到原来的位置或状态，作业不会自己回到老师那里；把作业交给老师要用交。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '54ba7f5d-a0b0-46b1-8110-2a1fda43a544') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12400, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她终于被回归职场。", "corrected_sentence": "她终于回归职场。", "error_description": "错误：“被回归”。“回归”是不及物动词，不能加“被”构成被动句；应说“她终于回归职场”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '54ba7f5d-a0b0-46b1-8110-2a1fda43a544') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12400, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他终于回归老家来了。", "corrected_sentence": "他终于回归老家了。", "error_description": "错误：“回归……来”。“回归”表示回到原处，不带“来”；“来”属于“回来”，应去掉，说“他终于回归老家了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '54ba7f5d-a0b0-46b1-8110-2a1fda43a544') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
