INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12401, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "一种数字媒体形式，用户可以通过互联网下载或在线收听音频节目。", "primary_collocate": null, "pronunciation": "bō kè", "ipa": "pwo˥ kʰɤ˥˩", "syllable_count": 2, "sentences": [{"text": "在全球化与数字化的当代，尽管书面记录与影像媒介主导了信息传播，口头叙事并未消亡，而是以新的形态回归：播客、口述史项目、非物质文化遗产保护运动，皆可视作对原始交流模式的现代回响。", "target_word": "播客", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "我每天上班路上都听一个英语播客。", "target_word": "播客", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个播客每周更新两次，内容很有意思。", "target_word": "播客", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他做了一个介绍中国文化的播客。", "target_word": "播客", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "很多人喜欢在睡觉前听播客。", "target_word": "播客", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这个科技播客有一百多万听众。", "target_word": "播客", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她请了一位作家来播客里聊新书。", "target_word": "播客", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你可以在网上免费下载这个播客。", "target_word": "播客", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我想自己做一个关于美食的播客。", "target_word": "播客", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这期播客讲的是怎样学好汉语。", "target_word": "播客", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "期", "label": "量词"}, {"form": "播客节目", "label": "复合"}], "register": "中性", "sense_fingerprint": "播客：可在网上下载或收听的音频节目形式", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '18071dd5-44bf-44c0-9410-71b353ae85d0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12401, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "播客", "is_correct": true, "explanation": "正确：播客指可下载或在线收听的音频节目，这里与口述史项目并列，指口头叙事的新形态。"}, {"text": "报纸", "is_correct": false, "explanation": "语义：报纸属于书面记录和传统媒介，与“口头叙事……以新的形态回归”的意思相反。"}, {"text": "信件", "is_correct": false, "explanation": "语义：信件是书面交流方式，句中强调的是口头叙事的回归，信件不符合这一语境。"}, {"text": "电影", "is_correct": false, "explanation": "语义：电影属于影像媒介，句中说影像媒介主导了信息传播，不是口头叙事的回归。"}], "explanations": {"播客": "正确：播客指可下载或在线收听的音频节目，这里与口述史项目并列，指口头叙事的新形态。", "报纸": "语义：报纸属于书面记录和传统媒介，与“口头叙事……以新的形态回归”的意思相反。", "信件": "语义：信件是书面交流方式，句中强调的是口头叙事的回归，信件不符合这一语境。", "电影": "语义：电影属于影像媒介，句中说影像媒介主导了信息传播，不是口头叙事的回归。"}, "sentence_index": 0, "correct_answer": "播客"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在菜市场买了一斤播客。", "explanation": "这里应该用〈白菜〉。播客是可以收听的音频节目，不能论斤在菜市场买。"}, {"text": "他给我寄了一个播客，装在盒子里。", "explanation": "这里应该用〈礼物〉。播客是网上收听的节目，不是实物，不能装在盒子里寄。"}, {"text": "他在火车站捡到了一个播客，里面有很多钱。", "explanation": "这里应该用〈钱包〉。播客是音频节目，不能捡到，里面也不能装钱。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f839809-6c26-42b4-8b7f-0dcce5f051c6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12401, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "播客", "is_correct": true, "explanation": "正确：这里指节目，“来播客里聊”表示作家在播客节目中做客，符合句意。"}, {"text": "信封", "is_correct": false, "explanation": "语义：信封是装信件的纸袋，不能作为聊天新书的场所。"}, {"text": "玻璃杯", "is_correct": false, "explanation": "语义：玻璃杯是盛水的器具，不能用在“来……里聊新书”的结构中。"}, {"text": "大衣", "is_correct": false, "explanation": "搭配：“来……里聊”需要能容纳人的场所，“大衣”不能与“聊”搭配。"}], "explanations": {"播客": "正确：这里指节目，“来播客里聊”表示作家在播客节目中做客，符合句意。", "信封": "语义：信封是装信件的纸袋，不能作为聊天新书的场所。", "玻璃杯": "语义：玻璃杯是盛水的器具，不能用在“来……里聊新书”的结构中。", "大衣": "搭配：“来……里聊”需要能容纳人的场所，“大衣”不能与“聊”搭配。"}, "sentence_index": 6, "correct_answer": "播客"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她把一个播客挂在了客厅的墙上。", "explanation": "这里应该用〈画〉。播客是音频节目，不能挂在墙上；能挂在墙上的是画。"}, {"text": "我把播客放进冰箱里了。", "explanation": "这里应该用〈牛奶〉。播客是音频节目，不是食物，不能放进冰箱。"}, {"text": "他穿着一个新播客去上班。", "explanation": "这里应该用〈外套〉。播客是音频节目，不能穿在身上。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f839809-6c26-42b4-8b7f-0dcce5f051c6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12401, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我每天晚上都听一只历史播客。", "corrected_sentence": "我每天晚上都听一个历史播客。", "error_description": "量词错误：“一只历史播客”应改为“一个历史播客”。“只”用于动物等，播客是音频节目，应用量词“个”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f839809-6c26-42b4-8b7f-0dcce5f051c6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12401, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她在一个英语播客们里学习发音。", "corrected_sentence": "她在一个英语播客里学习发音。", "error_description": "后缀错误：“播客们”应改为“播客”。“们”只用于指人的名词，播客是音频节目，不能加“们”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f839809-6c26-42b4-8b7f-0dcce5f051c6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
