INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12402, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "指用口头的方式表达，通常与书面表达相对。", "primary_collocate": null, "pronunciation": "kǒu shù", "ipa": "kʰou̯˨˩˦ ʂu˥˩", "syllable_count": 2, "sentences": [{"text": "这些老故事从未被写下来，只能由老人一边回忆，一边口述给年轻人，再由他们整理成册。", "target_word": "口述", "complexity_tier": "T5", "sentence_source": "generated"}, {"text": "爷爷眼睛不好，只能口述，让孙女帮他写信。", "target_word": "口述", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不会写字，就口述了自己的故事。", "target_word": "口述", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师请我们口述一遍昨天看到的事。", "target_word": "口述", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生口述病历，护士在电脑上记下来。", "target_word": "口述", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这份报告不用写，你口述给我听就行。", "target_word": "口述", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "作家受伤了，只好口述，由朋友代笔。", "target_word": "口述", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把旅行的经历口述给了记者。", "target_word": "口述", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶不识字，儿孙们就听她口述老故事。", "target_word": "口述", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "会议很重要，秘书一边听领导口述，一边记录。", "target_word": "口述", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "口述了", "label": "体标"}, {"form": "口述过", "label": "体标"}, {"form": "口述史", "label": "复合"}], "register": "中性", "sense_fingerprint": "口述：用口头方式表达，与书面表达相对", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd85b7b25-3bf8-4da1-af69-47b35a3d9947') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12402, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "口述", "is_correct": true, "explanation": "正确：「口述」指用口头方式讲述，此句中老人只能凭回忆口讲，与语境相符。"}, {"text": "朗读", "is_correct": false, "explanation": "语义：「朗读」需要照着现成的文字念，而句中故事「从未被写下来」，句意不通。"}, {"text": "书写", "is_correct": false, "explanation": "语义：句中故事「从未被写下来」，且「只能」口讲，「书写」与句意矛盾。"}, {"text": "默写", "is_correct": false, "explanation": "语义：「默写」指凭记忆写出，与句中「只能」口头讲述的语境相反。"}], "explanations": {"口述": "正确：「口述」指用口头方式讲述，此句中老人只能凭回忆口讲，与语境相符。", "朗读": "语义：「朗读」需要照着现成的文字念，而句中故事「从未被写下来」，句意不通。", "书写": "语义：句中故事「从未被写下来」，且「只能」口讲，「书写」与句意矛盾。", "默写": "语义：「默写」指凭记忆写出，与句中「只能」口头讲述的语境相反。"}, "sentence_index": 0, "correct_answer": "口述"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "演员在舞台上口述诗歌。", "explanation": "这里应该用〈朗诵〉。朗诵是有感情地念出已写好的作品，「口述」是用嘴说出自己的话，不用于念现成的诗。"}, {"text": "他没有说话，却口述了整篇论文。", "explanation": "这里应该用〈写〉。「口述」要用嘴说出，而句中说「没有说话」，前后矛盾。"}, {"text": "孩子用粉笔口述了答案。", "explanation": "这里应该用〈写〉。「口述」是用嘴说出，不用粉笔等书写工具，用粉笔应说写。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5a7135ca-31ed-44de-b065-1abec0640602') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12402, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "口述", "is_correct": true, "explanation": "口述：用口头方式表达，此句中指作家由朋友代笔、自己口头讲述，句意通顺。"}, {"text": "书写", "is_correct": false, "explanation": "语义：作家受伤无法书写，且句中由朋友代笔，「书写」与句意矛盾。"}, {"text": "誊抄", "is_correct": false, "explanation": "搭配：「誊抄」的对象是已写好的文稿，与「口述」的讲述方式不搭。"}, {"text": "执笔", "is_correct": false, "explanation": "语义：「执笔」指亲自拿笔写，与「受伤了」和「由朋友代笔」矛盾。"}], "explanations": {"口述": "口述：用口头方式表达，此句中指作家由朋友代笔、自己口头讲述，句意通顺。", "书写": "语义：作家受伤无法书写，且句中由朋友代笔，「书写」与句意矛盾。", "誊抄": "搭配：「誊抄」的对象是已写好的文稿，与「口述」的讲述方式不搭。", "执笔": "语义：「执笔」指亲自拿笔写，与「受伤了」和「由朋友代笔」矛盾。"}, "sentence_index": 6, "correct_answer": "口述"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把汽水口述给了妈妈。", "explanation": "这里应该用〈送〉。送是把实物交给别人，「口述」只用于说出话语或内容，汽水是实物，不能用口述转交。"}, {"text": "工人口述了一张桌子。", "explanation": "这里应该用〈做〉。做是造出实物，「口述」只用于说出话语或内容，桌子是实物，不能口述。"}, {"text": "他口述了一辆自行车。", "explanation": "这里应该用〈买〉。买是取得实物，「口述」只用于说出话语或内容，自行车是实物，不能口述。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5a7135ca-31ed-44de-b065-1abec0640602') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12402, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她口述非常流利。", "corrected_sentence": "她口述得非常流利。", "error_description": "补语错误：状态补语前要加「得」，应说「口述得非常流利」，不说「口述非常流利」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5a7135ca-31ed-44de-b065-1abec0640602') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12402, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他口述了完这个故事。", "corrected_sentence": "他口述完了这个故事。", "error_description": "结果补语错误：结果补语「完」应紧接动词，应说「口述完了」，不说「口述了完」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5a7135ca-31ed-44de-b065-1abec0640602') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12406, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '563d4160-02a3-4e8c-b5c0-0b1913a44586') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12406, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '563d4160-02a3-4e8c-b5c0-0b1913a44586') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12406, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "认为、当作。", "primary_collocate": null, "pronunciation": "shì zuò", "ipa": "ʂɻ̩˥˩ tswo˥˩", "syllable_count": 2, "sentences": [{"text": "在此背景下，城市不再被视作自然的对立面，而是通过技术创新与制度设计，成为可持续性、粮食主权与经济活力协同演进的复杂适应系统。", "target_word": "视作", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "在全球化与数字化的当代，尽管书面记录与影像媒介主导了信息传播，口头叙事并未消亡，而是以新的形态回归：播客、口述史项目、非物质文化遗产保护运动，皆可视作对原始交流模式的现代回响。", "target_word": "视作", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "他把这次失败视作一次机会。", "target_word": "视作", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很多人把老师视作自己的朋友。", "target_word": "视作", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们不能把孩子的问题视作小事。", "target_word": "视作", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她一直把这只小狗视作家人。", "target_word": "视作", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司把客户的意见视作最重要的参考。", "target_word": "视作", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把这座老房子视作家族的记忆。", "target_word": "视作", "complexity_tier": "T3", "furigana": "tā bǎ zhè zuò lǎo fáng zi shì zuò jiā zú de jì yì.", "sentence_source": "generated"}, {"text": "有些人把比赛视作一场战争。", "target_word": "视作", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位老人把邻居的孩子视作自己的孙子。", "target_word": "视作", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "视作：把某人或某事认为是、当作另一种事物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8eb6ea89-b4e2-487f-9034-a8829d8e7345') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12406, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "视作", "is_correct": true, "explanation": "“被视作……”表示被认为是某种事物，符合书面语语境。"}, {"text": "保护", "is_correct": false, "explanation": "语义：“城市被保护自然的对立面”说不通，句意是把城市看作某种事物。"}, {"text": "推翻", "is_correct": false, "explanation": "语义：“推翻”指颠覆，与“城市不再被……”的句意不符。"}, {"text": "等于", "is_correct": false, "explanation": "配价：“等于”不用于被动句，“被等于……”不成立。"}], "explanations": {"视作": "“被视作……”表示被认为是某种事物，符合书面语语境。", "保护": "语义：“城市被保护自然的对立面”说不通，句意是把城市看作某种事物。", "推翻": "语义：“推翻”指颠覆，与“城市不再被……”的句意不符。", "等于": "配价：“等于”不用于被动句，“被等于……”不成立。"}, "sentence_index": 0, "correct_answer": "视作"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把树影视作了人，吓得后退了一步。", "explanation": "这里应该用〈看成〉。“视作”表示有意识地认定，不用于把影子错看成人。"}, {"text": "他把镜子视作窗户，一头撞了上去。", "explanation": "这里应该用〈误认为〉。“视作”是有意识的认定，不用于因看错而把镜子当成窗户的情况。"}, {"text": "我把远处的大石头视作了一个人，吓了一跳。", "explanation": "这里应该用〈误认成〉。“视作”表示有意识地认定，不能表示把石头错看成人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '563d4160-02a3-4e8c-b5c0-0b1913a44586') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12406, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "视作", "is_correct": true, "explanation": "“把意见视作参考”表示把意见当作重要的参考，符合句意。"}, {"text": "反映", "is_correct": false, "explanation": "搭配：“反映”的对象是情况或意见，不能接“最重要的参考”。"}, {"text": "编辑", "is_correct": false, "explanation": "语义：“编辑”是修改文字，与“意见视作参考”的句意不符。"}, {"text": "拒绝", "is_correct": false, "explanation": "语义：“拒绝最重要的参考”与“最重要”的评价自相矛盾。"}], "explanations": {"视作": "“把意见视作参考”表示把意见当作重要的参考，符合句意。", "反映": "搭配：“反映”的对象是情况或意见，不能接“最重要的参考”。", "编辑": "语义：“编辑”是修改文字，与“意见视作参考”的句意不符。", "拒绝": "语义：“拒绝最重要的参考”与“最重要”的评价自相矛盾。"}, "sentence_index": 6, "correct_answer": "视作"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她把桌上的水杯视作了花瓶，一不小心碰倒了。", "explanation": "这里应该用〈误认为〉。“视作”是有意识的认定，不用于把水杯错看成花瓶的情况。"}, {"text": "我把路边的垃圾视作了包子，咬了一口。", "explanation": "这里应该用〈错当〉。“视作”不用于把垃圾错当成食物的情况，应说“错当成”。"}, {"text": "我把黑暗中的那只小狗视作了一只猫，走近才看清。", "explanation": "这里应该用〈错当〉。“视作”是有意识的看待，不用于错当的情况。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '563d4160-02a3-4e8c-b5c0-0b1913a44586') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12406, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他把这次考试视作成一次锻炼的机会。", "corrected_sentence": "他把这次考试视作一次锻炼的机会。", "error_description": "多余的“成”：“视作”后直接接宾语，不用“成”（“当成”才用“成”），应说“视作一次锻炼的机会”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '563d4160-02a3-4e8c-b5c0-0b1913a44586') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12406, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们把那位老师视作为榜样。", "corrected_sentence": "我们把那位老师视作榜样。", "error_description": "多余的“为”：“视作”后面直接接宾语，不要加“为”，应说“视作榜样”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '563d4160-02a3-4e8c-b5c0-0b1913a44586') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12407, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "否定", "is_correct": true, "explanation": "正确：“否定”与“肯定”构成反义，表示不认可、否认。"}, {"text": "赞美", "is_correct": false, "explanation": "非反义：“赞美”与“肯定”意思相近，属于近义，不构成反义。"}, {"text": "计算", "is_correct": false, "explanation": "非反义：“计算”指算数，与“肯定”无关。"}, {"text": "讨论", "is_correct": false, "explanation": "非反义：“讨论”是交换意见，与“肯定”不构成反义。"}], "correct_answer": "否定", "explanations": {"否定": "正确：“否定”与“肯定”构成反义，表示不认可、否认。", "赞美": "非反义：“赞美”与“肯定”意思相近，属于近义，不构成反义。", "计算": "非反义：“计算”指算数，与“肯定”无关。", "讨论": "非反义：“讨论”是交换意见，与“肯定”不构成反义。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0bd86450-962e-4140-9952-3018e82309e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12407, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "否定", "is_correct": true, "explanation": "正确：“否定”与“肯定”构成反义，表示不认可、否认。"}, {"text": "同意", "is_correct": false, "explanation": "非反义：“同意”与“肯定”意思相近，属于近义，不构成反义。"}, {"text": "跑步", "is_correct": false, "explanation": "非反义：“跑步”是运动，与“肯定”无关。"}, {"text": "修改", "is_correct": false, "explanation": "非反义：“修改”指改动，与“肯定”不构成反义。"}], "correct_answer": "否定", "explanations": {"否定": "正确：“否定”与“肯定”构成反义，表示不认可、否认。", "同意": "非反义：“同意”与“肯定”意思相近，属于近义，不构成反义。", "跑步": "非反义：“跑步”是运动，与“肯定”无关。", "修改": "非反义：“修改”指改动，与“肯定”不构成反义。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0bd86450-962e-4140-9952-3018e82309e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12407, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "明确表达对某种价值或意义的支持和认可", "primary_collocate": null, "pronunciation": "kěn dìng", "ipa": "kʰən˨˩˦ tiŋ˥˩", "syllable_count": 2, "sentences": [{"text": "老师肯定了我的努力。", "target_word": "肯定", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "大家都肯定他的工作能力。", "target_word": "肯定", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "经理当面肯定了小王的想法。", "target_word": "肯定", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们应该肯定孩子的每一点进步。", "target_word": "肯定", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "专家肯定了这个办法。", "target_word": "肯定", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈笑着肯定了我的选择。", "target_word": "肯定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从不肯定别人，总是只说缺点。", "target_word": "肯定", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司肯定了她这一年的付出。", "target_word": "肯定", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "领导在会上肯定了我们的做法。", "target_word": "肯定", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "朋友们都肯定我的决定。", "target_word": "肯定", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "肯定了", "label": "体标"}, {"form": "肯定过", "label": "体标"}], "register": "中性", "sense_fingerprint": "明确认可、赞同某人或某事的价值", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f5780da-c6e6-4d29-93fe-0d7e321c3e1c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12407, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "肯定", "is_correct": true, "explanation": "正确：“肯定了我的努力”表示认可努力的价值，符合语境。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”不能以“努力”这类抽象名词为宾语。"}, {"text": "偷", "is_correct": false, "explanation": "语义：“偷”是窃取，与老师的正面评价相悖。"}, {"text": "洗", "is_correct": false, "explanation": "搭配：“洗”不能与“努力”这类抽象名词搭配作宾语。"}], "explanations": {"肯定": "正确：“肯定了我的努力”表示认可努力的价值，符合语境。", "吃": "搭配：“吃”不能以“努力”这类抽象名词为宾语。", "偷": "语义：“偷”是窃取，与老师的正面评价相悖。", "洗": "搭配：“洗”不能与“努力”这类抽象名词搭配作宾语。"}, "sentence_index": 0, "correct_answer": "肯定"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他肯定了自己的错误。", "explanation": "这里应该用〈承认〉。“肯定”表示认可、赞同，不能用于承认错误。"}, {"text": "他的脸上肯定了笑容。", "explanation": "这里应该用〈露出〉。“肯定”表示认可、赞同，不能用来描述表情。"}, {"text": "这次失败肯定了他的信心。", "explanation": "这里应该用〈打击〉。“肯定”表示认可、支持，不能表示使人受挫。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0bd86450-962e-4140-9952-3018e82309e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12407, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "肯定", "is_correct": true, "explanation": "正确：“从不肯定别人”指从不认可别人，与“只说缺点”相呼应。"}, {"text": "煮", "is_correct": false, "explanation": "搭配：“煮”的宾语多为食物，不能接“别人”。"}, {"text": "洗澡", "is_correct": false, "explanation": "配价：“洗澡”是不及物动词，后面不能直接带“别人”作宾语。"}, {"text": "理发", "is_correct": false, "explanation": "配价：“理发”是离合词，不能直接带“别人”作宾语，需说“为别人理发”。"}], "explanations": {"肯定": "正确：“从不肯定别人”指从不认可别人，与“只说缺点”相呼应。", "煮": "搭配：“煮”的宾语多为食物，不能接“别人”。", "洗澡": "配价：“洗澡”是不及物动词，后面不能直接带“别人”作宾语。", "理发": "配价：“理发”是离合词，不能直接带“别人”作宾语，需说“为别人理发”。"}, "sentence_index": 6, "correct_answer": "肯定"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "老师肯定了我的错误。", "explanation": "这里应该用〈批评〉。“肯定”表示认可，不能用来指出错误。"}, {"text": "这盘菜肯定了我的食欲。", "explanation": "这里应该用〈勾起〉。“肯定”表示认可、赞同，不能用于食欲被引发。"}, {"text": "妈妈肯定了我的粗心。", "explanation": "这里应该用〈责备〉。“肯定”表示认可，不能用来指责过失。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0bd86450-962e-4140-9952-3018e82309e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12407, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "经理肯定了着他的计划。", "corrected_sentence": "经理肯定了他的计划。", "error_description": "体标错误：“了”与“着”不能同时用在同一个动词后，应只用“了”，说“经理肯定了他的计划”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0bd86450-962e-4140-9952-3018e82309e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12407, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "朋友们都没肯定了我的决定。", "corrected_sentence": "朋友们都没肯定我的决定。", "error_description": "体标错误：“没”表示否定已发生的动作，句中不能再用“了”，应说“没肯定”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0bd86450-962e-4140-9952-3018e82309e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
