INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12408, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "指亲身在事情发生的地点。", "primary_collocate": null, "pronunciation": "zài chǎng", "ipa": "tsaɪ̯˥˩ ʈʂʰaŋ˨˩˦", "syllable_count": 2, "sentences": [{"text": "这些实践重新肯定了身体在场、声音质感与即兴互动所蕴含的认知深度——它们无法被完全转译为文字或数据。", "target_word": "在场", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "事情发生的时候，我正好在场。", "target_word": "在场", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "开会时，经理和老师都在场。", "target_word": "在场", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "当时在场的人都听到了他的话。", "target_word": "在场", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他不在场，所以不知道发生了什么。", "target_word": "在场", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这件事有很多人在场，可以作证。", "target_word": "在场", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "会议开始时，所有人都已经在场了。", "target_word": "在场", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "警察问在场的每个人看到了什么。", "target_word": "在场", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你在场的话，他就不会生气了。", "target_word": "在场", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子出生时，爸爸一直在场。", "target_word": "在场", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "在场的", "label": "定语形式"}, {"form": "不在场", "label": "否定形式"}, {"form": "在场了", "label": "体标"}], "register": "中性", "sense_fingerprint": "在场：亲身处在事情发生的现场", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '18071dd5-44bf-44c0-9410-71b353ae85d0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12408, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "在场", "is_correct": true, "explanation": "正确：在场指亲身处于事情发生的现场，符合“身体在场”的说法。"}, {"text": "在唱", "is_correct": false, "explanation": "“在唱”的第二音节是 chàng（第四声），与 chǎng（第三声）声调不同，意思是正在唱歌。"}, {"text": "再长", "is_correct": false, "explanation": "“再长”的第二音节是 zhǎng，与 chǎng 的声母不同（zh 与 ch），意思是继续生长。"}, {"text": "再尝", "is_correct": false, "explanation": "“再尝”的第二音节是 cháng（第二声），与 chǎng（第三声）声调不同，意思是再尝一次。"}, {"text": "再唱", "is_correct": false, "explanation": "“再唱”的第二音节是 chàng（第四声），与 chǎng 声调不同，意思是再唱一遍。"}], "explanations": {"在场": "正确：在场指亲身处于事情发生的现场，符合“身体在场”的说法。", "在唱": "“在唱”的第二音节是 chàng（第四声），与 chǎng（第三声）声调不同，意思是正在唱歌。", "再长": "“再长”的第二音节是 zhǎng，与 chǎng 的声母不同（zh 与 ch），意思是继续生长。", "再尝": "“再尝”的第二音节是 cháng（第二声），与 chǎng（第三声）声调不同，意思是再尝一次。", "再唱": "“再唱”的第二音节是 chàng（第四声），与 chǎng 声调不同，意思是再唱一遍。"}, "sentence_index": null, "correct_answer": "在场"}, "level_3": {"options": [{"text": "在场", "is_correct": true, "explanation": "正确：在场指亲身处于事情发生的地点，这里说“身体在场”，与“肯定”的语境相合。"}, {"text": "缺席", "is_correct": false, "explanation": "语义：“缺席”与“身体在场”的意思相反，与“肯定”的语境相违背。"}, {"text": "回避", "is_correct": false, "explanation": "语义：“回避”与“肯定”相反，身体在场不能被“回避”。"}, {"text": "站立", "is_correct": false, "explanation": "搭配：“身体”后接“在场”表示亲临现场，“站立”不能构成这种搭配。"}], "explanations": {"在场": "正确：在场指亲身处于事情发生的地点，这里说“身体在场”，与“肯定”的语境相合。", "缺席": "语义：“缺席”与“身体在场”的意思相反，与“肯定”的语境相违背。", "回避": "语义：“回避”与“肯定”相反，身体在场不能被“回避”。", "站立": "搭配：“身体”后接“在场”表示亲临现场，“站立”不能构成这种搭配。"}, "sentence_index": 0, "correct_answer": "在场"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "那辆自行车也在场，没人注意到它。", "explanation": "这里不能用〈在场〉。在场只用于人，指人亲身处在某地；自行车是物品，应说“停在”。"}, {"text": "那盆花也在场，看着大家吵架。", "explanation": "这里不能用〈在场〉。在场只用于人；花是植物，不能亲身处在现场，应说“摆在”。"}, {"text": "那台电视机在场，播放了整场比赛。", "explanation": "这里不能用〈在场〉。在场只用于人；电视机是设备，不能亲身在场，应说“安装在”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f839809-6c26-42b4-8b7f-0dcce5f051c6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12408, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "在场", "is_correct": true, "explanation": "正确：在场指亲身处于事情发生的现场。"}, {"text": "再闯", "is_correct": false, "explanation": "“再闯”的第二音节是 chuǎng，和 chǎng 声调相同，只多一个介音 u。意思是再冲一次。"}, {"text": "在床", "is_correct": false, "explanation": "“在床”的第二音节是 chuáng（第二声），和 chǎng 相比多一个介音 u，声调也不同。意思是在床上。"}, {"text": "在窗", "is_correct": false, "explanation": "“在窗”的第二音节是 chuāng（第一声），和 chǎng 相比多一个介音 u，声调也不同。意思是在窗边。"}], "explanations": {"在场": "正确：在场指亲身处于事情发生的现场。", "再闯": "“再闯”的第二音节是 chuǎng，和 chǎng 声调相同，只多一个介音 u。意思是再冲一次。", "在床": "“在床”的第二音节是 chuáng（第二声），和 chǎng 相比多一个介音 u，声调也不同。意思是在床上。", "在窗": "“在窗”的第二音节是 chuāng（第一声），和 chǎng 相比多一个介音 u，声调也不同。意思是在窗边。"}, "sentence_index": null, "correct_answer": "在场"}, "level_3": {"options": [{"text": "在场", "is_correct": true, "explanation": "正确：在场指人已经处在会议现场，与“会议开始时，所有人都已经在场了”相合。"}, {"text": "缺席", "is_correct": false, "explanation": "语义：“缺席”与“都已经在场”相反，会议开始时所有人缺席不合句意。"}, {"text": "散场", "is_correct": false, "explanation": "语义：“散场”指活动结束后离开，会议刚开始时不能散场。"}, {"text": "撤离", "is_correct": false, "explanation": "语义：“撤离”指离开危险的地方，会议开始时所有人都已经撤离与句意不符。"}], "explanations": {"在场": "正确：在场指人已经处在会议现场，与“会议开始时，所有人都已经在场了”相合。", "缺席": "语义：“缺席”与“都已经在场”相反，会议开始时所有人缺席不合句意。", "散场": "语义：“散场”指活动结束后离开，会议刚开始时不能散场。", "撤离": "语义：“撤离”指离开危险的地方，会议开始时所有人都已经撤离与句意不符。"}, "sentence_index": 6, "correct_answer": "在场"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这本书也在场，一直放在桌子上。", "explanation": "这里不能用〈在场〉。在场只用于人，指人亲身处在某地；书是物品，不能亲身在场。"}, {"text": "那把钥匙也在场，躺在门口的地上。", "explanation": "这里不能用〈在场〉。在场只用于人；钥匙是物品，不能亲身在场，应说“躺在”。"}, {"text": "那份合同也在场，签了字就生效了。", "explanation": "这里不能用〈在场〉。在场只用于人；合同是文件，不能亲身在场，应说“放在”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f839809-6c26-42b4-8b7f-0dcce5f051c6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12408, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我父亲那天很在场，目睹了整个过程。", "corrected_sentence": "我父亲那天在场，目睹了整个过程。", "error_description": "副词错误：“很在场”应改为“在场”。“在场”表示人亲身处在事情发生的现场，是不能用程度副词“很”修饰的动词，应直接说“在场”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f839809-6c26-42b4-8b7f-0dcce5f051c6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12408, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "演出的时候，观众们都在场舞台，气氛很热烈。", "corrected_sentence": "演出的时候，观众们都在场，气氛很热烈。", "error_description": "搭配错误：“在场”是不及物动词，不能直接带处所宾语“舞台”，应删去“舞台”，说“都在场”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f839809-6c26-42b4-8b7f-0dcce5f051c6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
