INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12409, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指物体表面给人的触觉感受或视觉、听觉上的品质。", "primary_collocate": null, "pronunciation": "zhì gǎn", "ipa": "ʈʂɻ̩˥˩ kan˨˩˦", "syllable_count": 2, "sentences": [{"text": "这些实践重新肯定了身体在场、声音质感与即兴互动所蕴含的认知深度——它们无法被完全转译为文字或数据。", "target_word": "质感", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这块布的质感很好，看起来很高级。", "target_word": "质感", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张照片的质感很特别，像老电影一样。", "target_word": "质感", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "设计师想让这个杯子有玻璃的质感。", "target_word": "质感", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "木头家具的质感让房间变得很温暖。", "target_word": "质感", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的声音很有质感，听起来很稳。", "target_word": "质感", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种墙纸有石头的质感，但是很轻。", "target_word": "质感", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件外套没有质感，一点也不高级。", "target_word": "质感", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她喜欢有质感的东西，不太爱买便宜货。", "target_word": "质感", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这幅画用了厚厚的颜色，质感特别强。", "target_word": "质感", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "質感", "label": "繁体"}, {"form": "一种质感", "label": "量词"}], "register": "书面", "sense_fingerprint": "物体或声音、画面给人的触觉、视觉、听觉品质感", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '18071dd5-44bf-44c0-9410-71b353ae85d0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12409, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "质感", "is_correct": true, "explanation": "「质感」指声音给人的质地感受，与「身体在场」「即兴互动」一起描述这些实践的感官特点，语境吻合。"}, {"text": "价格", "is_correct": false, "explanation": "语义：「价格」指商品的钱数，声音没有价格，接在「声音」后面说不通。"}, {"text": "热量", "is_correct": false, "explanation": "搭配：「声音」一般不和「热量」搭配，句中的语境也不涉及能量。"}, {"text": "面积", "is_correct": false, "explanation": "语义：「面积」指平面的大小，声音没有面积，与「身体在场」「互动」都不协调。"}], "explanations": {"质感": "「质感」指声音给人的质地感受，与「身体在场」「即兴互动」一起描述这些实践的感官特点，语境吻合。", "价格": "语义：「价格」指商品的钱数，声音没有价格，接在「声音」后面说不通。", "热量": "搭配：「声音」一般不和「热量」搭配，句中的语境也不涉及能量。", "面积": "语义：「面积」指平面的大小，声音没有面积，与「身体在场」「互动」都不协调。"}, "sentence_index": 0, "correct_answer": "质感"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个消息的质感很重，大家都很紧张。", "explanation": "这里应该用〈分量〉。「质感」指物体表面的触感或视觉、听觉上的品质，不能用来说消息的重要程度；消息的重要程度要用「分量」。"}, {"text": "他的质感很好，每次考试都考第一。", "explanation": "这里应该用〈成绩〉。「质感」指物体或声音的品质感，不能用来说学习成绩。"}, {"text": "我对这份工作的质感很好，很有兴趣。", "explanation": "这里应该用〈感觉〉。「质感」指物体的触感或视觉特征，不能用来说人对工作的心理感受。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f839809-6c26-42b4-8b7f-0dcce5f051c6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12409, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "质感", "is_correct": true, "explanation": "「质感」指墙纸表面像石头的触感或外观，与后半句「但是很轻」形成对比，说的正是有石头的样子却很轻。"}, {"text": "寿命", "is_correct": false, "explanation": "语义：「寿命」指生物或物品存在的年限，不能用来形容墙纸表面的特点。"}, {"text": "数量", "is_correct": false, "explanation": "搭配：「数量」指个数多少，不能说「有石头的数量」。"}, {"text": "海拔", "is_correct": false, "explanation": "语义：「海拔」指地面高出海平面的高度，与墙纸和石头的表面特征毫不相干。"}], "explanations": {"质感": "「质感」指墙纸表面像石头的触感或外观，与后半句「但是很轻」形成对比，说的正是有石头的样子却很轻。", "寿命": "语义：「寿命」指生物或物品存在的年限，不能用来形容墙纸表面的特点。", "数量": "搭配：「数量」指个数多少，不能说「有石头的数量」。", "海拔": "语义：「海拔」指地面高出海平面的高度，与墙纸和石头的表面特征毫不相干。"}, "sentence_index": 6, "correct_answer": "质感"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这辆车的质感很快，几秒钟就跑完了一百米。", "explanation": "这里应该用〈速度〉。「质感」指物体表面的触感或视觉、听觉上的品质，不能用来说车的快慢；车的快慢要用「速度」。"}, {"text": "我对这幅画的质感很深，很难忘。", "explanation": "这里应该用〈感受〉。「质感」指物体表面的触感或视觉特征，不能用来表达人对画作的感受有多深。"}, {"text": "孩子的质感很大，压得他喘不过气。", "explanation": "这里应该用〈压力〉。「质感」不能用来说人心里的负担，「压力」才是。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f839809-6c26-42b4-8b7f-0dcce5f051c6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12409, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这双鞋有一只很好的质感，穿起来很舒服。", "corrected_sentence": "这双鞋有一种很好的质感，穿起来很舒服。", "error_description": "「质感」是抽象名词，量词应用「种」（一种质感）。用「只」是错的，「只」用于单个或成对的具体物品。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f839809-6c26-42b4-8b7f-0dcce5f051c6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12409, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这块石头的质感的很粗糙，摸起来扎手。", "corrected_sentence": "这块石头的质感很粗糙，摸起来扎手。", "error_description": "助词错误：“质感的很粗糙”多了一个“的”，应改为“质感很粗糙”。“质感”后面直接接形容词作谓语时不加“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f839809-6c26-42b4-8b7f-0dcce5f051c6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
