INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12410, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5a7135ca-31ed-44de-b065-1abec0640602') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12410, 1, 'prompt1_core', '{"pos": "情态动词", "semantic_class": "function", "definition": "表示没有能力或条件去做某事。", "primary_collocate": null, "pronunciation": "wú fǎ", "ipa": "u˧˥ fa˨˩˦", "syllable_count": 2, "sentences": [{"text": "手机没电了，我无法给你打电话。", "target_word": "无法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他太忙了，无法来参加你的婚礼。", "target_word": "无法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大雪封了路，我们无法出门。", "target_word": "无法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个问题太难，我一个人无法解决。", "target_word": "无法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我无法用语言说出心里的感谢。", "target_word": "无法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事太奇怪了，我无法解释它为什么会发生。", "target_word": "无法", "complexity_tier": "T3", "furigana": "zhè jiàn shì tài qí guài le, wǒ wú fǎ jiě shì tā wèi shén me huì fā shēng.", "sentence_source": "generated"}, {"text": "没有护照，你无法坐飞机去国外。", "target_word": "无法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子哭得太厉害，妈妈无法听清他说什么。", "target_word": "无法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的腿受伤了，现在无法走路。", "target_word": "无法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "没有网络，我们无法开视频会议。", "target_word": "无法", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "無法", "label": "繁体"}], "register": "中性", "sense_fingerprint": "无法：没有能力或条件，不能做某事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd85b7b25-3bf8-4da1-af69-47b35a3d9947') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12410, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "无法", "is_correct": true, "explanation": "正确：「无法」表示没有能力或条件去做某事，与「手机没电了」的原因相符。"}, {"text": "能", "is_correct": false, "explanation": "语义：「能」表示有能力或条件，与「手机没电了」的前提相矛盾。"}, {"text": "可以", "is_correct": false, "explanation": "语义：「可以」表示许可或可能，手机没电却说「可以打电话」，与前半句矛盾。"}, {"text": "必须", "is_correct": false, "explanation": "语义：「必须」表示义务或必然，与「没电」导致的做不到相反，句意矛盾。"}], "explanations": {"无法": "正确：「无法」表示没有能力或条件去做某事，与「手机没电了」的原因相符。", "能": "语义：「能」表示有能力或条件，与「手机没电了」的前提相矛盾。", "可以": "语义：「可以」表示许可或可能，手机没电却说「可以打电话」，与前半句矛盾。", "必须": "语义：「必须」表示义务或必然，与「没电」导致的做不到相反，句意矛盾。"}, "sentence_index": 0, "correct_answer": "无法"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "学校规定学生无法带手机。", "explanation": "这里应该用〈不能〉表示规定不允许。「无法」只说客观上做不到，不能用来表示禁止。"}, {"text": "这件事不严重，你无法紧张。", "explanation": "这里应该用〈不必〉表示没有必要。「无法」说做不到，而句子要表达的是没有必要紧张。"}, {"text": "公共场所无法随便扔垃圾。", "explanation": "这里应该用〈不可〉表示禁止。「无法」指客观上做不到，不能用来表示不允许。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5a7135ca-31ed-44de-b065-1abec0640602') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12410, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "无法", "is_correct": true, "explanation": "正确：「无法」表示没有能力或条件，与「没有护照」的限制相符。"}, {"text": "应该", "is_correct": false, "explanation": "语义：「应该」表示理应如此，而「没有护照」说明根本不能出国，与「应该坐飞机出国」矛盾。"}, {"text": "会", "is_correct": false, "explanation": "语义：「会」表示将要发生或学会某事，但「没有护照」的条件让「坐飞机出国」不成立。"}, {"text": "能够", "is_correct": false, "explanation": "语义：「能够」表示有能力或条件，与「没有护照」的前提相矛盾。"}], "explanations": {"无法": "正确：「无法」表示没有能力或条件，与「没有护照」的限制相符。", "应该": "语义：「应该」表示理应如此，而「没有护照」说明根本不能出国，与「应该坐飞机出国」矛盾。", "会": "语义：「会」表示将要发生或学会某事，但「没有护照」的条件让「坐飞机出国」不成立。", "能够": "语义：「能够」表示有能力或条件，与「没有护照」的前提相矛盾。"}, "sentence_index": 6, "correct_answer": "无法"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他觉得没意思，无法参加比赛。", "explanation": "这里应该用〈拒绝〉。「无法」说没有能力或条件，而「觉得没意思」说明他是主动不参加。"}, {"text": "这种小错误，他无法放在眼里。", "explanation": "这里应该用〈不会〉。「无法」说没有能力，而句子说的是他瞧不上这种小错误，是主动不在乎，并非做不到。"}, {"text": "这些家务我懒得做，所以无法做完。", "explanation": "这里应该用〈懒得〉。「无法」说没有能力或条件，而句子说的是我不愿意动手，并非做不到。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5a7135ca-31ed-44de-b065-1abec0640602') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12410, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我昨天无法了参加会议。", "corrected_sentence": "我昨天无法参加会议。", "error_description": "错误形式：「无法了」；正确形式：「无法」。「无法」是情态动词，后面不能加「了」，「了」只能跟在动词之后表示完成。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5a7135ca-31ed-44de-b065-1abec0640602') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12410, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "下雨天路滑，我们没无法骑车去学校。", "corrected_sentence": "下雨天路滑，我们无法骑车去学校。", "error_description": "错误形式：「没无法骑车去学校」；正确形式：「无法骑车去学校」。「无法」本身已表示没有能力或条件，前面不能再加否定词「没」，两个否定叠加后句意混乱。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5a7135ca-31ed-44de-b065-1abec0640602') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
