INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12411, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f839809-6c26-42b4-8b7f-0dcce5f051c6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12411, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "将一种语言或文字转换成另一种语言或文字。", "primary_collocate": null, "pronunciation": "zhuǎn yì", "ipa": "ʈʂwan˨˩˦ i˥˩", "syllable_count": 2, "sentences": [{"text": "尽管机器翻译日益精准，许多诗歌的韵律与意境仍难以被完全转译为另一种语言，译者往往要在忠实与达意之间作出取舍。", "target_word": "转译", "complexity_tier": "T5", "sentence_source": "generated"}, {"text": "这位老师把中文诗转译成了英文。", "target_word": "转译", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他正在把这本小说转译成日文。", "target_word": "转译", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这首古诗很难转译，意思容易丢。", "target_word": "转译", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她转译过很多篇科学文章。", "target_word": "转译", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "把这封信转译成中文要花一个小时。", "target_word": "转译", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "机器能快速转译短句，但不一定准确。", "target_word": "转译", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把这篇英文摘要转译成了中文。", "target_word": "转译", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "转译时，你要注意原文的意思。", "target_word": "转译", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书已经转译成十多种文字了。", "target_word": "转译", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "轉譯", "label": "繁体"}, {"form": "转译了", "label": "体标"}, {"form": "转译过", "label": "体标"}], "register": "书面", "sense_fingerprint": "把一种语言文字的内容改成另一种语言文字", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '18071dd5-44bf-44c0-9410-71b353ae85d0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12411, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "转译", "is_correct": true, "explanation": "「转译」指把一种语言的诗歌转换成另一种语言，这里说韵律与意境难以被完全转成另一种语言，语境吻合。"}, {"text": "播放", "is_correct": false, "explanation": "语义：「播放」指放映或播送，不能用来说把诗歌转换成另一种语言。"}, {"text": "烹饪", "is_correct": false, "explanation": "语义：「烹饪」指做饭做菜，与诗歌和语言的转换毫不相干。"}, {"text": "分配", "is_correct": false, "explanation": "语义：「分配」指按份额分派，与语言的转换无关。"}], "explanations": {"转译": "「转译」指把一种语言的诗歌转换成另一种语言，这里说韵律与意境难以被完全转成另一种语言，语境吻合。", "播放": "语义：「播放」指放映或播送，不能用来说把诗歌转换成另一种语言。", "烹饪": "语义：「烹饪」指做饭做菜，与诗歌和语言的转换毫不相干。", "分配": "语义：「分配」指按份额分派，与语言的转换无关。"}, "sentence_index": 0, "correct_answer": "转译"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把会议的内容转译给了大家。", "explanation": "这里应该用〈转述〉。「转译」指把一种语言文字转换成另一种，这里只是把内容告诉大家，没有换语言。"}, {"text": "电视台把比赛转译到了全国。", "explanation": "这里应该用〈转播〉。「转译」指语言文字的转换，比赛画面的传送要用「转播」。"}, {"text": "他把注意力转译到了工作上。", "explanation": "这里应该用〈转移〉。「转译」只用于语言文字的转换，注意力的改变要用「转移」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f839809-6c26-42b4-8b7f-0dcce5f051c6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12411, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "转译", "is_correct": true, "explanation": "「转译」指把一种语言的句子转换成另一种，机器能快速转换短句，但不一定准确，符合语境。"}, {"text": "烘干", "is_correct": false, "explanation": "语义：「烘干」用来使湿的东西变干，不能用来形容处理句子。"}, {"text": "饲养", "is_correct": false, "explanation": "搭配：「饲养」的对象是动植物，不能和「短句」搭配。"}, {"text": "冷藏", "is_correct": false, "explanation": "语义：「冷藏」指放在低温中保存，与句子的处理毫不相干。"}], "explanations": {"转译": "「转译」指把一种语言的句子转换成另一种，机器能快速转换短句，但不一定准确，符合语境。", "烘干": "语义：「烘干」用来使湿的东西变干，不能用来形容处理句子。", "饲养": "搭配：「饲养」的对象是动植物，不能和「短句」搭配。", "冷藏": "语义：「冷藏」指放在低温中保存，与句子的处理毫不相干。"}, "sentence_index": 6, "correct_answer": "转译"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的态度转译了很多。", "explanation": "这里应该用〈转变〉。「转译」只用于语言文字的转换，态度的改变要用「转变」。"}, {"text": "车子在路口转译。", "explanation": "这里应该用〈转弯〉。「转译」指语言文字的转换，车子改变方向要用「转弯」。"}, {"text": "快递员把包裹转译给了我。", "explanation": "这里应该用〈转交〉。「转译」指语言文字的转换，包裹交给别人要用「转交」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f839809-6c26-42b4-8b7f-0dcce5f051c6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12411, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他把这份合同转译了英文。", "corrected_sentence": "他把这份合同转译成了英文。", "error_description": "「转译」后面要加结果补语「成」，应说「转译成了英文」；漏掉「成」就不对了。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f839809-6c26-42b4-8b7f-0dcce5f051c6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12411, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们已经把这篇文章转译了过。", "corrected_sentence": "我们已经把这篇文章转译过了。", "error_description": "体标顺序错误：「了」和「过」不能这样并用，应说「转译过了」，「过」在前，「了」在后。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f839809-6c26-42b4-8b7f-0dcce5f051c6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
