INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12412, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5a7135ca-31ed-44de-b065-1abec0640602') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12412, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "语法是语言的结构规则，包括词形变化和句子结构。", "primary_collocate": null, "pronunciation": "yǔ fǎ", "ipa": "y˨˩˦ fa˨˩˦", "syllable_count": 2, "sentences": [{"text": "句子里词的顺序怎么排，是语法要讲的主要内容。", "target_word": "语法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "汉语语法比较简单，没有词形变化。", "target_word": "语法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书专门讲英语语法的规则。", "target_word": "语法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学外语要学语法，也要多听多说。", "target_word": "语法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师今天讲了德语的语法，我听不懂。", "target_word": "语法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个句子的语法有问题，词的顺序不对。", "target_word": "语法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "德语语法里，名词有性和格的变化。", "target_word": "语法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的词汇很多，可是语法常常出错。", "target_word": "语法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我每天花半小时复习语法。", "target_word": "语法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学好语法，才能写出正确的句子。", "target_word": "语法", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "語法", "label": "繁体"}, {"form": "语法书", "label": "复合"}, {"form": "语法错误", "label": "复合"}], "register": "中性", "sense_fingerprint": "语法：语言的结构规则，含词形变化和句子结构", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd85b7b25-3bf8-4da1-af69-47b35a3d9947') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12412, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "语法", "is_correct": true, "explanation": "正确：「语法」指语言的结构规则，这里指词的排列顺序规则，句意通顺。"}, {"text": "语调", "is_correct": false, "explanation": "语义：「语调」指说话时声音的高低起伏，与词的排列顺序无关，句意不通。"}, {"text": "字体", "is_correct": false, "explanation": "语义：「字体」指文字的书写形式，与词的排列顺序无关，句意不通。"}, {"text": "语气", "is_correct": false, "explanation": "语义：「语气」指说话的态度和口吻，与词的排列顺序无关，句意不通。"}], "explanations": {"语法": "正确：「语法」指语言的结构规则，这里指词的排列顺序规则，句意通顺。", "语调": "语义：「语调」指说话时声音的高低起伏，与词的排列顺序无关，句意不通。", "字体": "语义：「字体」指文字的书写形式，与词的排列顺序无关，句意不通。", "语气": "语义：「语气」指说话的态度和口吻，与词的排列顺序无关，句意不通。"}, "sentence_index": 0, "correct_answer": "语法"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这栋楼的语法很复杂，我看不懂。", "explanation": "这里应该用〈结构〉。「语法」指语言的规则，不能用来说楼房的结构。"}, {"text": "他的语法很好听。", "explanation": "这里应该用〈声音〉。「语法」是规则，不能用来形容好听与否。"}, {"text": "他的歌声很有语法。", "explanation": "这里应该用〈韵味〉。「语法」指语言规则，不能用来形容歌声有没有韵味。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5a7135ca-31ed-44de-b065-1abec0640602') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12412, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "语法", "is_correct": true, "explanation": "正确：「语法」指词形变化和句子结构的规则，名词的性和格正属于语法变化。"}, {"text": "发音", "is_correct": false, "explanation": "语义：「发音」指声音，名词的性和格属于语法变化，与发音无关，句意不通。"}, {"text": "标点", "is_correct": false, "explanation": "搭配：「标点」不带词形变化，不能说「标点里有性和格的变化」。"}, {"text": "字母", "is_correct": false, "explanation": "语义：「字母」只是书写符号，不存在名词的性和格变化，与句意不符。"}], "explanations": {"语法": "正确：「语法」指词形变化和句子结构的规则，名词的性和格正属于语法变化。", "发音": "语义：「发音」指声音，名词的性和格属于语法变化，与发音无关，句意不通。", "标点": "搭配：「标点」不带词形变化，不能说「标点里有性和格的变化」。", "字母": "语义：「字母」只是书写符号，不存在名词的性和格变化，与句意不符。"}, "sentence_index": 6, "correct_answer": "语法"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这道菜的语法很好，大家都爱吃。", "explanation": "这里应该用〈味道〉。「语法」指规则，不能用来形容菜好不好吃。"}, {"text": "她对孩子很有语法。", "explanation": "这里应该用〈感情〉。「语法」是语言规则，不能指人与人之间的情感。"}, {"text": "这位老师的语法很开放。", "explanation": "这里应该用〈思想〉。「语法」是语言的规则，不能用来形容一个人的观念是否开放。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5a7135ca-31ed-44de-b065-1abec0640602') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12412, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我地语法不太好。", "corrected_sentence": "我的语法不太好。", "error_description": "错误形式：「我地语法不太好」；正确形式：「我的语法不太好」。「地」用于修饰动词、形容词，名词前的定语标记要用「的」，应说「我的语法」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5a7135ca-31ed-44de-b065-1abec0640602') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12412, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个句子有一只语法错误。", "corrected_sentence": "这个句子有一个语法错误。", "error_description": "错误形式：「一只语法错误」；正确形式：「一个语法错误」。「语法错误」是抽象的错误，量词要用「个」；「只」用于某些动物或成对的东西，不能用来数错误。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5a7135ca-31ed-44de-b065-1abec0640602') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12413, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "故意", "is_correct": true, "explanation": "故意与无意识是反义词，指有意而为，与“不是有意的”相对。"}, {"text": "辽阔", "is_correct": false, "explanation": "辽阔形容空间范围，与无意识无反义关系。"}, {"text": "粗糙", "is_correct": false, "explanation": "粗糙形容质地，与无意识无反义关系。"}, {"text": "迅速", "is_correct": false, "explanation": "迅速形容速度，与无意识无反义关系。"}], "correct_answer": "故意", "explanations": {"故意": "故意与无意识是反义词，指有意而为，与“不是有意的”相对。", "辽阔": "辽阔形容空间范围，与无意识无反义关系。", "粗糙": "粗糙形容质地，与无意识无反义关系。", "迅速": "迅速形容速度，与无意识无反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ef8669af-1187-499f-b907-8925a3beaf1a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12413, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "故意", "is_correct": true, "explanation": "故意与无意识是反义词，指有意而为，与“不是有意的”相对。"}, {"text": "陡峭", "is_correct": false, "explanation": "陡峭形容地势，与无意识无反义关系。"}, {"text": "干燥", "is_correct": false, "explanation": "干燥形容湿度或质地，与无意识无反义关系。"}, {"text": "湿润", "is_correct": false, "explanation": "湿润形容湿度，与无意识无反义关系。"}], "correct_answer": "故意", "explanations": {"故意": "故意与无意识是反义词，指有意而为，与“不是有意的”相对。", "陡峭": "陡峭形容地势，与无意识无反义关系。", "干燥": "干燥形容湿度或质地，与无意识无反义关系。", "湿润": "湿润形容湿度，与无意识无反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ef8669af-1187-499f-b907-8925a3beaf1a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12413, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "没有意识到的、不是有意的；心理学上也指未被自觉意识到的心理活动。", "primary_collocate": null, "pronunciation": "wú yì shí", "ipa": "u˧˥ i˥˩ ʂɨ˧˥", "syllable_count": 3, "sentences": [{"text": "叙事，作为人类理解时间、自我与他者关系的基本语法，持续在个体记忆与集体无意识之间架设桥梁。", "target_word": "无意识", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这只是无意识的小动作，他自己也没发现。", "target_word": "无意识", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "说话时抖腿，常常是无意识的习惯。", "target_word": "无意识", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她说那句话是无意识的，并不想伤害你。", "target_word": "无意识", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很多习惯都是无意识养成的。", "target_word": "无意识", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的无意识反应，说明他早就知道了。", "target_word": "无意识", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他走路时的小动作，都是无意识的。", "target_word": "无意识", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子无意识的一句话，让妈妈很感动。", "target_word": "无意识", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个错误是无意识的，请不要生气。", "target_word": "无意识", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "心理学家研究人的无意识活动。", "target_word": "无意识", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "无意识地", "label": "复合"}, {"form": "集体无意识", "label": "复合"}, {"form": "無意識", "label": "繁体"}], "register": "书面语", "sense_fingerprint": "自己没有觉察到的、不是故意的；心理学上指未被意识到的心理活动", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3c5811c7-5286-4a58-bed4-0f21f210b18a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12413, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "无意识", "is_correct": true, "explanation": "无意识：不是有意的，此处指集体中不被自觉意识到的心理成分。"}, {"text": "家具", "is_correct": false, "explanation": "语义：家具是器物，不能在“集体……之间”中作为心理层面的中介。"}, {"text": "脾气", "is_correct": false, "explanation": "搭配：“集体脾气”不成立，“脾气”指个人性情，不能用“集体”修饰。"}, {"text": "玩意儿", "is_correct": false, "explanation": "语域：“玩意儿”为口语，与这段学术性叙述的语域不合，且不指心理成分。"}], "explanations": {"无意识": "无意识：不是有意的，此处指集体中不被自觉意识到的心理成分。", "家具": "语义：家具是器物，不能在“集体……之间”中作为心理层面的中介。", "脾气": "搭配：“集体脾气”不成立，“脾气”指个人性情，不能用“集体”修饰。", "玩意儿": "语域：“玩意儿”为口语，与这段学术性叙述的语域不合，且不指心理成分。"}, "sentence_index": 0, "correct_answer": "无意识"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她说那句话是无意识的，是早就计划好的。", "explanation": "这里应该用〈故意〉。“早就计划好”说明是有意的，与“无意识”（不是有意的）矛盾。"}, {"text": "她说那句话的态度无意识，并不想伤害你。", "explanation": "这里应该用〈随意〉。无意识指没有意识到或不是有意的，不用来形容态度；“态度随意”要用随意。"}, {"text": "她想了很久才说那句话，完全是无意识的。", "explanation": "这里应该用〈有意〉。“想了很久才说”是经过考虑的，不能说是无意识的。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ef8669af-1187-499f-b907-8925a3beaf1a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12413, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "无意识", "is_correct": true, "explanation": "无意识：不是有意的，此处指走路时的小动作不受主观控制。"}, {"text": "笔直", "is_correct": false, "explanation": "搭配：“笔直”多用于线条或姿态，不用来形容小动作的性质。"}, {"text": "贵重", "is_correct": false, "explanation": "语义：“贵重”指价值高，小动作不具有价值高低的性质。"}, {"text": "贼亮", "is_correct": false, "explanation": "语域：“贼亮”为口语，与这段书面表述的语域不合，且形容光亮而非动作。"}], "explanations": {"无意识": "无意识：不是有意的，此处指走路时的小动作不受主观控制。", "笔直": "搭配：“笔直”多用于线条或姿态，不用来形容小动作的性质。", "贵重": "语义：“贵重”指价值高，小动作不具有价值高低的性质。", "贼亮": "语域：“贼亮”为口语，与这段书面表述的语域不合，且形容光亮而非动作。"}, "sentence_index": 6, "correct_answer": "无意识"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这场比赛的无意识很精彩。", "explanation": "这里应该用〈表现〉。无意识指没有意识到或不是有意的心理活动或行为，不指比赛中的表现；“比赛表现很精彩”要用表现。"}, {"text": "他凭无意识说了那句话。", "explanation": "这里应该用〈直觉〉。“凭”后接的是依据，直觉可以作依据，“无意识”不能作依据。"}, {"text": "他咬笔的动作是长期养成的无意识。", "explanation": "这里应该用〈习惯〉。无意识指没有意识到或不是有意的，不能像习惯那样长期养成；“养成习惯”要用习惯。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ef8669af-1187-499f-b907-8925a3beaf1a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12413, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这句口误是无意识地，他并没有察觉。", "corrected_sentence": "这句口误是无意识的，他并没有察觉。", "error_description": "“是……的”句中，“无意识”作谓语要用“的”，不能用“地”；“地”只用在动词前作状语。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ef8669af-1187-499f-b907-8925a3beaf1a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12413, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他无意识的咬着笔，自己也没发现。", "corrected_sentence": "他无意识地咬着笔，自己也没发现。", "error_description": "“无意识”修饰动词“咬”作状语时应用“地”，不用“的”。“无意识的咬”应改为“无意识地咬”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ef8669af-1187-499f-b907-8925a3beaf1a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
