INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12416, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "指事物最根本、最本质的特性或性质。", "primary_collocate": null, "pronunciation": "gēn běn xìng", "ipa": "kən˥ pən˨˩˦ ɕiŋ˥˩", "syllable_count": 3, "sentences": [{"text": "更深层而言，口头传统揭示了一种根本性的存在论：人类并非单纯生活在物理现实中，而是栖居于由故事构筑的意义网络之中。", "target_word": "根本性", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "当代理具备跨平台持续学习能力时，个体数据的隐私边界将面临根本性重构。", "target_word": "根本性", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这是一个根本性的问题。", "target_word": "根本性", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "两个国家的差别是根本性的。", "target_word": "根本性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这次改革带来了根本性的变化。", "target_word": "根本性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们的矛盾是根本性的，很难解决。", "target_word": "根本性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司需要做出根本性的改变。", "target_word": "根本性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "专家认为这个办法不能解决根本性问题。", "target_word": "根本性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这两种说法有根本性的不同。", "target_word": "根本性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "互联网给人们的生活带来了根本性的影响。", "target_word": "根本性", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "根本性：事物最根本、最本质的特性", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f3e4321f-de6e-46a4-8743-02c784fb0964') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12416, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "根本性", "is_correct": true, "explanation": "根本性：指事物最根本、最本质的特性，与“更深层而言”的语境相合，作“一种……的存在论”的定语。"}, {"text": "表面性", "is_correct": false, "explanation": "语义：上句说“更深层而言”，要求深层本质；“表面性”指表层特征，与句意相反。"}, {"text": "物质性", "is_correct": false, "explanation": "语义：下文说人类“并非单纯生活在物理现实中”，“物质性”强调物理层面，与之相矛盾。"}, {"text": "随意性", "is_correct": false, "explanation": "搭配：“随意性”指任意、不受约束，不能用作“存在论”这种阐释存在本质的理论的基本性质。"}], "explanations": {"根本性": "根本性：指事物最根本、最本质的特性，与“更深层而言”的语境相合，作“一种……的存在论”的定语。", "表面性": "语义：上句说“更深层而言”，要求深层本质；“表面性”指表层特征，与句意相反。", "物质性": "语义：下文说人类“并非单纯生活在物理现实中”，“物质性”强调物理层面，与之相矛盾。", "随意性": "搭配：“随意性”指任意、不受约束，不能用作“存在论”这种阐释存在本质的理论的基本性质。"}, "sentence_index": 0, "correct_answer": "根本性"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家超市的根本性很多。", "explanation": "这里应该用〈数量〉。“根本性”指事物最本质的特性，不能用来表示多少，商品的多少要说“数量”。"}, {"text": "这件衣服的根本性很便宜。", "explanation": "这里应该用〈价格〉。“根本性”指事物最本质的特性，不表示价钱高低，说价钱要用“价格”。"}, {"text": "这个房间的根本性很大。", "explanation": "这里应该用〈面积〉。“根本性”指事物最本质的特性，不能用来形容空间的大小，房间大小要说“面积”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '130f335a-1162-4cda-8e52-2b2b8a232d05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12416, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "根本性", "is_correct": true, "explanation": "根本性：指最本质的变化，与“公司需要做出”的大幅改变相合，作“改变”的定语。"}, {"text": "偶然性", "is_correct": false, "explanation": "语义：“偶然性”指出于偶然，与“公司需要做出”的主动决策相悖。"}, {"text": "习惯性", "is_correct": false, "explanation": "搭配：“习惯性”说惯常、重复，不能修饰“做出”的一次性改变。"}, {"text": "静态性", "is_correct": false, "explanation": "语义：“静态性”指静止不变，与“做出改变”的意思相矛盾。"}], "explanations": {"根本性": "根本性：指最本质的变化，与“公司需要做出”的大幅改变相合，作“改变”的定语。", "偶然性": "语义：“偶然性”指出于偶然，与“公司需要做出”的主动决策相悖。", "习惯性": "搭配：“习惯性”说惯常、重复，不能修饰“做出”的一次性改变。", "静态性": "语义：“静态性”指静止不变，与“做出改变”的意思相矛盾。"}, "sentence_index": 6, "correct_answer": "根本性"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个月我的根本性增加了三公斤。", "explanation": "这里应该用〈体重〉。“根本性”指事物的本质特性，不能用来表示重量的增加，人的重量要说“体重”。"}, {"text": "这次考试他的根本性很好。", "explanation": "这里应该用〈成绩〉。“根本性”指事物的本质特性，不能用来评价考试的好坏，要说“成绩”。"}, {"text": "这盏灯的根本性很高。", "explanation": "这里应该用〈亮度〉。“根本性”指事物的本质特性，不表示明亮程度，灯的明暗要说“亮度”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '130f335a-1162-4cda-8e52-2b2b8a232d05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12416, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他们想找出问题的很根本性原因。", "corrected_sentence": "他们想找出问题的根本性原因。", "error_description": "错误在“很”：“根本性”是区别词，表示性质类别，没有程度之分，不能受“很”修饰。应为“问题的根本性原因”，去掉“很”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '130f335a-1162-4cda-8e52-2b2b8a232d05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12416, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这是一种根本性得区别。", "corrected_sentence": "这是一种根本性的区别。", "error_description": "错误在结构助词：“根本性”修饰名词“区别”时应用“的”，“得”用于动词或形容词后的补语，不能用于此处。应为“一种根本性的区别”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '130f335a-1162-4cda-8e52-2b2b8a232d05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
