INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12419, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "指居住、停留，多用于鸟类或人。", "primary_collocate": null, "pronunciation": "qī jū", "ipa": "tɕʰi˥ tɕy˥", "syllable_count": 2, "sentences": [{"text": "更深层而言，口头传统揭示了一种根本性的存在论：人类并非单纯生活在物理现实中，而是栖居于由故事构筑的意义网络之中。", "target_word": "栖居", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "许多候鸟冬天栖居在南方的湖边。", "target_word": "栖居", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这片树林里栖居着上百只白鹭。", "target_word": "栖居", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人想一直栖居在这个安静的小村子里。", "target_word": "栖居", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山里的人世世代代栖居在石头房子里。", "target_word": "栖居", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "燕子每年春天都会回来栖居在我家屋檐下。", "target_word": "栖居", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他离开城市，栖居于海边的一座小岛。", "target_word": "栖居", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大树上栖居着不同种类的小鸟。", "target_word": "栖居", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位诗人想栖居在山水之间。", "target_word": "栖居", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冬天到了，天鹅栖居在不结冰的河面上。", "target_word": "栖居", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "棲居", "label": "繁体"}], "register": "书面语", "sense_fingerprint": "鸟类或人居住、停留于某处", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e62f285c-3fff-4d83-96f3-aac2e819e030') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12419, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "栖居", "is_correct": true, "explanation": "正确：栖居 qī jū 指居住、停留，与听到的读音一致。"}, {"text": "起居", "is_correct": false, "explanation": "qǐ jū（第三声）与 qī jū（第一声）声调不同，意思是日常生活起居。"}, {"text": "棋局", "is_correct": false, "explanation": "qí jú 与 qī jū 两个音节的声调都不同，意思是下棋时的局面。"}, {"text": "齐聚", "is_correct": false, "explanation": "qí jù 与 qī jū 只有声调不同，意思是聚集在一起。"}], "explanations": {"栖居": "正确：栖居 qī jū 指居住、停留，与听到的读音一致。", "起居": "qǐ jū（第三声）与 qī jū（第一声）声调不同，意思是日常生活起居。", "棋局": "qí jú 与 qī jū 两个音节的声调都不同，意思是下棋时的局面。", "齐聚": "qí jù 与 qī jū 只有声调不同，意思是聚集在一起。"}, "sentence_index": null, "correct_answer": "栖居"}, "level_3": {"options": [{"text": "栖居", "is_correct": true, "explanation": "正确：栖居指居住、停留，与“而是……于由故事构筑的意义网络之中”的安定语境相合。"}, {"text": "流浪", "is_correct": false, "explanation": "语义：流浪指漂泊无定，与句中人类稳定地身处意义网络的意思相反。"}, {"text": "打扫", "is_correct": false, "explanation": "语义：打扫指清除灰尘，不能说“打扫于……之中”描述人的存在状态。"}, {"text": "出售", "is_correct": false, "explanation": "语义：出售指卖东西，人类不能“出售于”意义网络之中，句子不通。"}], "explanations": {"栖居": "正确：栖居指居住、停留，与“而是……于由故事构筑的意义网络之中”的安定语境相合。", "流浪": "语义：流浪指漂泊无定，与句中人类稳定地身处意义网络的意思相反。", "打扫": "语义：打扫指清除灰尘，不能说“打扫于……之中”描述人的存在状态。", "出售": "语义：出售指卖东西，人类不能“出售于”意义网络之中，句子不通。"}, "sentence_index": 0, "correct_answer": "栖居"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他每天都要在工厂栖居，负责生产零件。", "explanation": "这里应该用〈工作〉。栖居表示居住或停留，不表示工作；负责生产零件应说工作。"}, {"text": "这张桌子栖居在房间的角落里。", "explanation": "这里应该用〈放在〉。栖居只用于鸟类或人作主语，桌子不能栖居，表示物品位置应说放在。"}, {"text": "他在广场栖居，跳了一支舞。", "explanation": "这里应该用〈跳舞〉。栖居表示居住或停留，不表示跳舞；跳了一支舞应说跳舞。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b6fc027-c13c-4674-a693-301e756e4da3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12419, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "栖居", "is_correct": true, "explanation": "正确：栖居 qī jū 指居住、停留，与听到的读音一致。"}, {"text": "七局", "is_correct": false, "explanation": "qī jú 与 qī jū 只有末字声调不同，意思是比赛的第七局。"}, {"text": "器具", "is_correct": false, "explanation": "qì jù 与 qī jū 声调不同，意思是器械、用具。"}, {"text": "契据", "is_correct": false, "explanation": "qì jù 与 qī jū 声调不同，意思是契约和字据。"}], "explanations": {"栖居": "正确：栖居 qī jū 指居住、停留，与听到的读音一致。", "七局": "qī jú 与 qī jū 只有末字声调不同，意思是比赛的第七局。", "器具": "qì jù 与 qī jū 声调不同，意思是器械、用具。", "契据": "qì jù 与 qī jū 声调不同，意思是契约和字据。"}, "sentence_index": null, "correct_answer": "栖居"}, "level_3": {"options": [{"text": "栖居", "is_correct": true, "explanation": "正确：栖居指居住，与“离开城市，……于海边的一座小岛”的定居语境相合。"}, {"text": "路过", "is_correct": false, "explanation": "语义：路过指短暂经过，与句中离开城市后定居小岛的意思不符。"}, {"text": "游览", "is_correct": false, "explanation": "搭配：“游览”多接景点、名胜，不能用“游览于……一座小岛”表示定居。"}, {"text": "修理", "is_correct": false, "explanation": "语义：修理指把坏的东西修好，不能说“修理于海边的一座小岛”。"}], "explanations": {"栖居": "正确：栖居指居住，与“离开城市，……于海边的一座小岛”的定居语境相合。", "路过": "语义：路过指短暂经过，与句中离开城市后定居小岛的意思不符。", "游览": "搭配：“游览”多接景点、名胜，不能用“游览于……一座小岛”表示定居。", "修理": "语义：修理指把坏的东西修好，不能说“修理于海边的一座小岛”。"}, "sentence_index": 6, "correct_answer": "栖居"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他在音乐厅栖居，弹奏了一首钢琴曲。", "explanation": "这里应该用〈演奏〉。栖居表示居住或停留，不表示演奏乐器；弹奏钢琴曲应说演奏。"}, {"text": "他在医院栖居，给病人做了手术。", "explanation": "这里应该用〈做手术〉。栖居表示居住或停留，不表示给病人动手术。"}, {"text": "他在办公室栖居，每天打扫卫生。", "explanation": "这里应该用〈打扫〉。栖居表示居住或停留，不表示清扫卫生；每天打扫卫生应说打扫。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b6fc027-c13c-4674-a693-301e756e4da3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12419, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "河边栖居一群白鹭。", "corrected_sentence": "河边栖居着一群白鹭。", "error_description": "“栖居”描述某处存在某物时，后面要带“着”，应说“栖居着一群白鹭”，漏掉“着”不自然。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b6fc027-c13c-4674-a693-301e756e4da3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12419, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我家的鸽子都栖居屋顶上。", "corrected_sentence": "我家的鸽子都栖居在屋顶上。", "error_description": "“栖居”后面引出地点时要用“在”，应说“栖居在屋顶上”，漏掉“在”不规范。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b6fc027-c13c-4674-a693-301e756e4da3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
