INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12422, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "property", "definition": "事物真实可靠的程度。", "primary_collocate": null, "pronunciation": "zhēn shí xìng", "ipa": "ʈʂən˥ ʂʐ̩˧˥ ɕiŋ˥˩", "syllable_count": 3, "sentences": [{"text": "当一则民间传说跨越千年仍能引发共鸣，其力量不在于事件的考古真实性，而在于它对人性困境的原型性捕捉。", "target_word": "真实性", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "记者要先检查消息的真实性，再写文章。", "target_word": "真实性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张照片的真实性很高，没有人怀疑。", "target_word": "真实性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们无法确定这份材料的真实性。", "target_word": "真实性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师问他这个故事的真实性有多高。", "target_word": "真实性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "法官认真检查了证据的真实性。", "target_word": "真实性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书的真实性受到了很多专家的肯定。", "target_word": "真实性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "网上的新闻要先看看它的真实性。", "target_word": "真实性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这封信的真实性有问题，不能相信。", "target_word": "真实性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "专家用了很多方法来检查这幅画的真实性。", "target_word": "真实性", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "真實性", "label": "繁体"}], "register": "书面语", "sense_fingerprint": "事物真实可靠的程度", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e62f285c-3fff-4d83-96f3-aac2e819e030') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12422, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "真实性", "is_correct": true, "explanation": "正确。真实性指事物真实可靠的程度，与“考古”搭配，表示事件的可靠程度。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色不是判断事件可靠程度的标准，与“考古”的语境不合。"}, {"text": "体积", "is_correct": false, "explanation": "搭配：“考古体积”不能成立，体积不能用来说明事件是否可靠。"}, {"text": "长度", "is_correct": false, "explanation": "语义：长度是度量，不能表示事件的可靠程度。"}], "explanations": {"真实性": "正确。真实性指事物真实可靠的程度，与“考古”搭配，表示事件的可靠程度。", "颜色": "语义：颜色不是判断事件可靠程度的标准，与“考古”的语境不合。", "体积": "搭配：“考古体积”不能成立，体积不能用来说明事件是否可靠。", "长度": "语义：长度是度量，不能表示事件的可靠程度。"}, "sentence_index": 0, "correct_answer": "真实性"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这件商品的真实性很合理，大家都买得起。", "explanation": "这里应该用〈价格〉。“真实性”指可靠程度，不能用来评价价钱；价钱合理要说“价格”。"}, {"text": "这份证据有一把真实性，让人难以怀疑。", "explanation": "这里应该用〈种〉。“把”用于有柄的器具，抽象的真实性要说“一种真实性”。"}, {"text": "这幅画的真实性很鲜艳，一下子就吸引了我。", "explanation": "这里应该用〈颜色〉。“真实性”指可靠程度，不能用“鲜艳”来形容；画的鲜艳指颜色。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b6fc027-c13c-4674-a693-301e756e4da3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12422, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "真实性", "is_correct": true, "explanation": "正确。真实性指事物可靠的程度，这里是专家肯定的对象。"}, {"text": "厚度", "is_correct": false, "explanation": "语义：厚度是物体的厚薄，不能受到专家的肯定。"}, {"text": "体重", "is_correct": false, "explanation": "语义：体重是人或动物的重量，不能受到专家的肯定，与“真实性”的语境不合。"}, {"text": "温度", "is_correct": false, "explanation": "搭配：“温度”不能与“受到很多专家的肯定”搭配。"}], "explanations": {"真实性": "正确。真实性指事物可靠的程度，这里是专家肯定的对象。", "厚度": "语义：厚度是物体的厚薄，不能受到专家的肯定。", "体重": "语义：体重是人或动物的重量，不能受到专家的肯定，与“真实性”的语境不合。", "温度": "搭配：“温度”不能与“受到很多专家的肯定”搭配。"}, "sentence_index": 6, "correct_answer": "真实性"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这幅画的真实性很久远，已经有三百年了。", "explanation": "这里应该用〈年代〉。“真实性”指可靠程度，不能用来说时间长短；说年代久远要用“年代”。"}, {"text": "这幅画有一块真实性，让人难以相信。", "explanation": "这里应该用〈种〉。“块”多用于片状或块状的东西，抽象的真实性要说“一种真实性”。"}, {"text": "这幅画是真实性，价值很高。", "explanation": "这里应该用〈真品〉。真实性指可靠的程度，不能指一件真的东西。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b6fc027-c13c-4674-a693-301e756e4da3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12422, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这份证据得真实性已经得到确认。", "corrected_sentence": "这份证据的真实性已经得到确认。", "error_description": "“证据”与“真实性”之间的修饰标记应为“的”，不能用“得”（“得”不引出名词）。应说“这份证据的真实性”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b6fc027-c13c-4674-a693-301e756e4da3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12422, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这篇报道得真实性经过了多次核实。", "corrected_sentence": "这篇报道的真实性经过了多次核实。", "error_description": "“得”不能引出名词作修饰语，“报道”与“真实性”之间应用“的”，应说“这篇报道的真实性”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b6fc027-c13c-4674-a693-301e756e4da3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
