INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12423, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b6fc027-c13c-4674-a693-301e756e4da3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12423, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "人类区别于动物的本性，如情感、道德、欲望等综合特质。", "primary_collocate": null, "pronunciation": "rén xìng", "ipa": "ɻən˧˥ ɕiŋ˥˩", "syllable_count": 2, "sentences": [{"text": "当一则民间传说跨越千年仍能引发共鸣，其力量不在于事件的考古真实性，而在于它对人性困境的原型性捕捉。", "target_word": "人性", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这部小说写出了人性的善与恶。", "target_word": "人性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "人性中有爱，也有害怕。", "target_word": "人性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他相信人性本来是好的。", "target_word": "人性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "灾难里，我们看到了人性最好的一面。", "target_word": "人性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这部电影很懂人性，故事让人想了很久。", "target_word": "人性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "作家常常写人性的复杂。", "target_word": "人性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "困难的时候，最能看出人性。", "target_word": "人性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的书让我思考人性是什么。", "target_word": "人性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好的故事会让我们更懂得人性。", "target_word": "人性", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "人性化", "label": "复合"}], "register": "书面语", "sense_fingerprint": "人类特有的本性", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e62f285c-3fff-4d83-96f3-aac2e819e030') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12423, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "人性", "is_correct": true, "explanation": "正确：「人性」指人类的本性，符合「对……困境」的语境。"}, {"text": "天气", "is_correct": false, "explanation": "语义：「困境」指人或社会的困难处境，天气不会处于困境。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色没有处境，不能遭遇困境。"}, {"text": "花朵", "is_correct": false, "explanation": "搭配：「困境」通常与人或社会搭配，不说花朵的困境。"}], "explanations": {"人性": "正确：「人性」指人类的本性，符合「对……困境」的语境。", "天气": "语义：「困境」指人或社会的困难处境，天气不会处于困境。", "颜色": "语义：颜色没有处境，不能遭遇困境。", "花朵": "搭配：「困境」通常与人或社会搭配，不说花朵的困境。"}, "sentence_index": 0, "correct_answer": "人性"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的人性很开朗。", "explanation": "这里应该用〈性格〉。「人性」指人类共有的本性，形容某个人开朗要用「性格」。"}, {"text": "猫有夜间活动的人性。", "explanation": "这里应该用〈习性〉。「人性」只指人类的本性，动物的习性要用「习性」。"}, {"text": "水的人性是向下流。", "explanation": "这里应该用〈本性〉。「人性」只指人类的本性，水的本性要用「本性」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b6fc027-c13c-4674-a693-301e756e4da3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12423, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "人性", "is_correct": true, "explanation": "正确：「人性」指人类的本性，可以作「……的复杂」的对象。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：「复杂」多指人、事情或关系的内在构成，冰箱不是作家常写的对象。"}, {"text": "锅炉", "is_correct": false, "explanation": "语义：作家写作的内容是人的内心与关系，锅炉不构成写作对象。"}, {"text": "早餐", "is_correct": false, "explanation": "搭配：「复杂」不能用来形容早餐。"}], "explanations": {"人性": "正确：「人性」指人类的本性，可以作「……的复杂」的对象。", "冰箱": "语义：「复杂」多指人、事情或关系的内在构成，冰箱不是作家常写的对象。", "锅炉": "语义：作家写作的内容是人的内心与关系，锅炉不构成写作对象。", "早餐": "搭配：「复杂」不能用来形容早餐。"}, "sentence_index": 6, "correct_answer": "人性"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "地球上有很多人性。", "explanation": "这里应该用〈人类〉。「人性」指人的本性，说一群人要用「人类」，「人性」不能数量化。"}, {"text": "早起是他的人性。", "explanation": "这里应该用〈习惯〉。「人性」指人的本性，个人的生活习惯要用「习惯」。"}, {"text": "这种金属的人性很硬。", "explanation": "这里应该用〈性质〉。「人性」只指人类的本性，金属的硬度等特点要用「性质」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b6fc027-c13c-4674-a693-301e756e4da3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12423, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "灾难里，我们看到了人性得另一面。", "corrected_sentence": "灾难里，我们看到了人性的另一面。", "error_description": "「人性」修饰「另一面」，是定中关系，应用结构助词「的」，不能用「得」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b6fc027-c13c-4674-a693-301e756e4da3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12423, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这部小说写出了人性得光辉。", "corrected_sentence": "这部小说写出了人性的光辉。", "error_description": "「人性」与「光辉」之间是修饰关系，应用结构助词「的」，不能用「得」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b6fc027-c13c-4674-a693-301e756e4da3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
