INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12426, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "function", "definition": "指生物体进行生殖活动的能力，通常涉及生殖器官的功能。", "primary_collocate": null, "pronunciation": "xìng gōng néng", "ipa": "ɕiŋ˥˩ kʊŋ˥ nɤŋ˧˥", "syllable_count": 3, "sentences": [{"text": "他一直不好意思去医院，因为怕性功能出了问题。", "target_word": "性功能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生说，他的性功能一切正常。", "target_word": "性功能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "年纪大了，性功能会慢慢下降。", "target_word": "性功能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "压力太大会影响性功能。", "target_word": "性功能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种药可能会让性功能变差。", "target_word": "性功能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他去医院检查了性功能。", "target_word": "性功能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "睡眠不好的人，性功能也容易出问题。", "target_word": "性功能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经常运动对性功能有好处。", "target_word": "性功能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生建议他先检查性功能，再决定怎么治疗。", "target_word": "性功能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "性功能和身体健康有很大的关系。", "target_word": "性功能", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "生物体的生殖能力，医学和健康语境", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd85b7b25-3bf8-4da1-af69-47b35a3d9947') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12426, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "性功能", "is_correct": true, "explanation": "正确：指生物体进行生殖活动的能力，符合本义。"}, {"text": "性别", "is_correct": false, "explanation": "语义：性别指男或女，与身体功能的问题无关，句意不通。"}, {"text": "收入", "is_correct": false, "explanation": "语义：收入指钱财来源，与身体功能的问题无关，句意不通。"}, {"text": "学历", "is_correct": false, "explanation": "语义：学历指受教育的程度，与身体功能的问题无关，句意不通。"}], "explanations": {"性功能": "正确：指生物体进行生殖活动的能力，符合本义。", "性别": "语义：性别指男或女，与身体功能的问题无关，句意不通。", "收入": "语义：收入指钱财来源，与身体功能的问题无关，句意不通。", "学历": "语义：学历指受教育的程度，与身体功能的问题无关，句意不通。"}, "sentence_index": 0, "correct_answer": "性功能"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这台电脑的性功能很好，运行得很快。", "explanation": "这里应该用〈性能〉。性能用于机器、设备的表现；性功能只指生物的生殖能力，不能用于电脑。"}, {"text": "这个按钮的性功能很多，什么都能做。", "explanation": "这里应该用〈功能〉。按钮的功能指操作上的用途；性功能只指生殖能力，不适用于按钮。"}, {"text": "这个社区的性功能很完善，居民都很满意。", "explanation": "这里应该用〈设施〉。设施指公共建筑、设备等配套条件；性功能只指生殖能力，不能用来说社区的配套。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5a7135ca-31ed-44de-b065-1abec0640602') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12426, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "性功能", "is_correct": true, "explanation": "正确：指生殖能力，与“睡眠不好”引起的问题相符。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气指气象状况，不会因人的睡眠不好而出问题，句意不通。"}, {"text": "邮编", "is_correct": false, "explanation": "语义：邮编是地址的号码，与人的睡眠和身体无关，句意不通。"}, {"text": "包裹", "is_correct": false, "explanation": "语义：包裹指寄送的物件，与人的睡眠和身体功能无关，句意不通。"}], "explanations": {"性功能": "正确：指生殖能力，与“睡眠不好”引起的问题相符。", "天气": "语义：天气指气象状况，不会因人的睡眠不好而出问题，句意不通。", "邮编": "语义：邮编是地址的号码，与人的睡眠和身体无关，句意不通。", "包裹": "语义：包裹指寄送的物件，与人的睡眠和身体功能无关，句意不通。"}, "sentence_index": 6, "correct_answer": "性功能"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他对声音的性功能很灵敏。", "explanation": "这里应该用〈听觉〉。听觉指辨别声音的感觉；性功能只指生殖能力，不能用来说对声音的反应。"}, {"text": "他对吃饭没有性功能。", "explanation": "这里应该用〈食欲〉。食欲指想吃东西的欲望；性功能只指生殖能力，不能用来说对吃饭的兴趣。"}, {"text": "他的性功能很灵敏，能尝出很细的味道。", "explanation": "这里应该用〈味觉〉。味觉指辨别味道的感觉；性功能不表示味觉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5a7135ca-31ed-44de-b065-1abec0640602') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12426, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "长期熬夜会被影响性功能。", "corrected_sentence": "长期熬夜会影响性功能。", "error_description": "误用「被」：主语「长期熬夜」是施事，句子是主动的，不能加「被」，应说「长期熬夜会影响性功能」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5a7135ca-31ed-44de-b065-1abec0640602') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12426, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "熬夜把性功能不好。", "corrected_sentence": "熬夜对性功能不好。", "error_description": "误用介词：「把」字句后须接动词，这里应改用「对」，说「熬夜对性功能不好」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5a7135ca-31ed-44de-b065-1abec0640602') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
