INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12433, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "按一定节奏和姿势舞动身体；也比喻像舞蹈一样跳动。", "primary_collocate": null, "pronunciation": "tiào wǔ", "ipa": "tʰiɑʊ̯⁵¹ u²¹⁴", "syllable_count": 2, "sentences": [{"text": "三个箭头像在跳舞，也有象征意义。", "target_word": "跳舞", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "火苗在风中跳舞。", "target_word": "跳舞", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雪花在空中轻轻跳舞。", "target_word": "跳舞", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小女孩穿着红裙子跳舞。", "target_word": "跳舞", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "阳光在水面上跳舞。", "target_word": "跳舞", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们在院子里跳舞。", "target_word": "跳舞", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我喜欢看海鸥在海上跳舞。", "target_word": "跳舞", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "树叶在秋风里跳舞。", "target_word": "跳舞", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "灯光在墙上跳舞，很好看。", "target_word": "跳舞", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她今天晚上要去学跳舞。", "target_word": "跳舞", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "跳了舞", "label": "体标"}, {"form": "跳着舞", "label": "体标"}, {"form": "跳过舞", "label": "体标"}], "register": "中性", "sense_fingerprint": "动词：舞动身体，也比喻事物像舞蹈般跳动", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '842fb074-b13a-42dd-9ece-3ecc7134eb5d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12433, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "跳舞", "is_correct": true, "explanation": "跳舞：此处为比喻义，三个箭头像舞蹈般跳动，与句意相合，是唯一能填入的词。"}, {"text": "缴费", "is_correct": false, "explanation": "语义：“缴费”是人支付费用的行为，箭头不可能“像在缴费”，比喻不成立。"}, {"text": "吃饭", "is_correct": false, "explanation": "语义：“吃饭”是人的行为，与三个箭头的比喻不相合。"}, {"text": "游览", "is_correct": false, "explanation": "语义：“游览”是人的观光活动，箭头不能游览，与比喻不相合。"}], "explanations": {"跳舞": "跳舞：此处为比喻义，三个箭头像舞蹈般跳动，与句意相合，是唯一能填入的词。", "缴费": "语义：“缴费”是人支付费用的行为，箭头不可能“像在缴费”，比喻不成立。", "吃饭": "语义：“吃饭”是人的行为，与三个箭头的比喻不相合。", "游览": "语义：“游览”是人的观光活动，箭头不能游览，与比喻不相合。"}, "sentence_index": 0, "correct_answer": "跳舞"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他饿了，想跳舞一碗面条。", "explanation": "这里应该用〈吃〉。饿了要吃面条；跳舞是舞动身体，不能带“一碗面条”作宾语。"}, {"text": "他能跳舞三百米，真厉害。", "explanation": "这里应该用〈游泳〉。游泳是在水中前进，三百米指游过的距离；跳舞不表示移动的距离。"}, {"text": "这名选手跳舞跳过了两米。", "explanation": "这里应该用〈跳高〉。跳高是跃过横杆的运动，“跳过两米”说的是跳跃的高度；跳舞不能表示跳跃高度。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'db5df177-4ea5-4b7f-9975-32ce13f139fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12433, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "跳舞", "is_correct": true, "explanation": "跳舞：海鸥在海上飞舞跳跃，与句意相合，是唯一能填入的词。"}, {"text": "考试", "is_correct": false, "explanation": "语义：海鸥不能在海上考试，句意不通。"}, {"text": "上课", "is_correct": false, "explanation": "语义：海鸥不会在海上上课，与句意不符。"}, {"text": "缴费", "is_correct": false, "explanation": "搭配：“缴费”的主体通常是人，且需要费用对象，海鸥在海上缴费不合。"}], "explanations": {"跳舞": "跳舞：海鸥在海上飞舞跳跃，与句意相合，是唯一能填入的词。", "考试": "语义：海鸥不能在海上考试，句意不通。", "上课": "语义：海鸥不会在海上上课，与句意不符。", "缴费": "搭配：“缴费”的主体通常是人，且需要费用对象，海鸥在海上缴费不合。"}, "sentence_index": 6, "correct_answer": "跳舞"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他第一次从飞机上跳舞，吓得不敢睁眼。", "explanation": "这里应该用〈跳伞〉。跳舞是按节奏舞动身体，不指从高处跳下。"}, {"text": "选手从十米台上跳舞，溅起很大的水花。", "explanation": "这里应该用〈跳水〉。跳舞是舞动身体，不指入水的动作。"}, {"text": "他在体育课上练习跳舞，成绩是三米五。", "explanation": "这里应该用〈跳远〉。跳舞不用来计量跳跃的距离。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'db5df177-4ea5-4b7f-9975-32ce13f139fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12433, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我小时候跳舞过。", "corrected_sentence": "我小时候跳过舞。", "error_description": "错误：离合词“跳舞”中间插入体标“过”的位置不对。正确：“过”应放在“跳”后，说“跳过舞”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'db5df177-4ea5-4b7f-9975-32ce13f139fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12433, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们草地上跳舞。", "corrected_sentence": "我们在草地上跳舞。", "error_description": "错误：表示地点的介词“在”漏掉了。正确：应说“我们在草地上跳舞”，地点要用“在”引出，放在动词前。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'db5df177-4ea5-4b7f-9975-32ce13f139fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
