INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12437, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'db5df177-4ea5-4b7f-9975-32ce13f139fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12437, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "瓶子是口小腹大的容器，通常用于盛放液体。", "primary_collocate": null, "pronunciation": "píng zi", "ipa": "pʰiŋ³⁵ tsɨ", "syllable_count": 2, "sentences": [{"text": "它出现在瓶子、纸盒上。", "target_word": "瓶子", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "桌子上放着一个空瓶子。", "target_word": "瓶子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把瓶子放在冰箱里。", "target_word": "瓶子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个瓶子里装着牛奶。", "target_word": "瓶子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不小心打破了一个瓶子。", "target_word": "瓶子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想买一个红色的瓶子。", "target_word": "瓶子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明把花插在瓶子里。", "target_word": "瓶子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "瓶子太滑，我拿不住。", "target_word": "瓶子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她用旧瓶子做了一盏灯。", "target_word": "瓶子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "瓶子里的水已经喝完了。", "target_word": "瓶子", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "只", "label": "量词"}], "register": "口语", "sense_fingerprint": "名词：口小腹大、用来装液体的容器", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '842fb074-b13a-42dd-9ece-3ecc7134eb5d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12437, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "瓶子", "is_correct": true, "explanation": "正确：“瓶子”与“纸盒”同为可见的容器，可以并列出现在“它出现在……上”中。"}, {"text": "人", "is_correct": false, "explanation": "语义：人不是能让东西“出现”的承载物，与“纸盒”并列不通。"}, {"text": "空气", "is_correct": false, "explanation": "搭配：“在……上”不能与“空气”搭配，空气不是平面承载物。"}, {"text": "雨", "is_correct": false, "explanation": "语义：雨是天气现象，不是可以承载物品的东西，与“纸盒”并列不通。"}], "explanations": {"瓶子": "正确：“瓶子”与“纸盒”同为可见的容器，可以并列出现在“它出现在……上”中。", "人": "语义：人不是能让东西“出现”的承载物，与“纸盒”并列不通。", "空气": "搭配：“在……上”不能与“空气”搭配，空气不是平面承载物。", "雨": "语义：雨是天气现象，不是可以承载物品的东西，与“纸盒”并列不通。"}, "sentence_index": 0, "correct_answer": "瓶子"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他用瓶子洗澡。", "explanation": "这里应该用〈浴缸〉。洗澡要用能盛水、能容人的浴缸，瓶子口小，装不下人。"}, {"text": "他用瓶子给自己理发。", "explanation": "这里应该用〈剪刀〉。理发要用能剪断头发的剪刀，瓶子无法剪发。"}, {"text": "他用瓶子装书。", "explanation": "这里应该用〈书包〉。书又大又扁，放不进口小的瓶子，装书要用书包。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'db5df177-4ea5-4b7f-9975-32ce13f139fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12437, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "瓶子", "is_correct": true, "explanation": "正确：“插”后接的是能容纳花的容器，“瓶子”符合句意。"}, {"text": "电视", "is_correct": false, "explanation": "语义：电视不是容器，花不能插在电视里。"}, {"text": "天空", "is_correct": false, "explanation": "语义：花不能插在天空里，句意不通。"}, {"text": "墙", "is_correct": false, "explanation": "语义：花不能插进墙里，与“插花”的意思不符。"}], "explanations": {"瓶子": "正确：“插”后接的是能容纳花的容器，“瓶子”符合句意。", "电视": "语义：电视不是容器，花不能插在电视里。", "天空": "语义：花不能插在天空里，句意不通。", "墙": "语义：花不能插进墙里，与“插花”的意思不符。"}, "sentence_index": 6, "correct_answer": "瓶子"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他用瓶子煮面。", "explanation": "这里应该用〈锅〉。瓶子不能用来加热煮面，煮面要用锅。"}, {"text": "他把菜端到瓶子上。", "explanation": "这里应该用〈盘子〉。菜要放在平底的盘子上，瓶子口小，放不了菜。"}, {"text": "他把衣服放进瓶子里。", "explanation": "这里应该用〈柜子〉。衣服体积大，装不进口小的瓶子。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'db5df177-4ea5-4b7f-9975-32ce13f139fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12437, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我买了两瓶子牛奶。", "corrected_sentence": "我买了两瓶牛奶。", "error_description": "错误：“瓶子”是名词，不能放在数词后充当量词，应说“两瓶牛奶”，用量词“瓶”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'db5df177-4ea5-4b7f-9975-32ce13f139fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12437, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她把一张空瓶子扔进了垃圾桶。", "corrected_sentence": "她把一个空瓶子扔进了垃圾桶。", "error_description": "错误：“瓶子”前用了量词“张”。正确：“张”用于纸、桌子等扁平物品，瓶子应该用“个”，说“一个空瓶子”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'db5df177-4ea5-4b7f-9975-32ce13f139fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
