INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12445, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "由三条线段首尾相连围成的封闭图形。", "primary_collocate": null, "pronunciation": "sān jiǎo xíng", "ipa": "san˥ tɕjau˨˩˦ ɕiŋ˧˥", "syllable_count": 3, "sentences": [{"text": "他们在纸上画了三条线，组成一个三角形。", "target_word": "三角形", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个三角形的三条边一样长。", "target_word": "三角形", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师在黑板上画了一个大三角形。", "target_word": "三角形", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "三角形有三个角，也有三条边。", "target_word": "三角形", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "屋顶的侧面看起来像一个三角形。", "target_word": "三角形", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你量一量这个三角形的每条边。", "target_word": "三角形", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用三根木条做了一个三角形。", "target_word": "三角形", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个红色的图形是三角形吗？", "target_word": "三角形", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "路边的牌子是三角形的，很容易看到。", "target_word": "三角形", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "桌上有圆形、方形和三角形的积木。", "target_word": "三角形", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个三角形", "label": "量词"}, {"form": "直角三角形", "label": "复合"}, {"form": "等边三角形", "label": "复合"}], "register": "中性", "sense_fingerprint": "三条线段围成的几何图形", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9bfbe3a8-7aeb-4ee1-8a32-ba6db3e80028') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12445, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "三角形", "is_correct": true, "explanation": "三角形：三条线首尾相连组成的图形，与画图的语境一致。"}, {"text": "歌曲", "is_correct": false, "explanation": "语义：三个箭头在纸上只能组成图形，不能组成一首歌曲。"}, {"text": "节目", "is_correct": false, "explanation": "语义：“组成”的对象是图形，节目与在纸上画箭头的语境不符。"}, {"text": "感情", "is_correct": false, "explanation": "搭配：“组成”通常说组成图形或团体，不能说组成感情。"}], "explanations": {"三角形": "三角形：三条线首尾相连组成的图形，与画图的语境一致。", "歌曲": "语义：三个箭头在纸上只能组成图形，不能组成一首歌曲。", "节目": "语义：“组成”的对象是图形，节目与在纸上画箭头的语境不符。", "感情": "搭配：“组成”通常说组成图形或团体，不能说组成感情。"}, "sentence_index": 0, "correct_answer": "三角形"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他用三角形画直线。", "explanation": "这里应该用〈三角板〉。三角形是图形，画直线的工具要用三角板。"}, {"text": "他用三角形量了量桌子有多长。", "explanation": "这里应该用〈尺子〉。三角形是图形，量长度的工具是尺子。"}, {"text": "他们三人之间有一段三角形关系。", "explanation": "这里应该用〈三角关系〉。三角形指图形，三人之间的感情纠葛要说三角关系。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c9caf03-da33-4142-a119-fea37774a70e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12445, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "三角形", "is_correct": true, "explanation": "三角形：用木条搭成的图形，与句中“做了一个”的语境一致。"}, {"text": "面包", "is_correct": false, "explanation": "语义：句中用的是木条，做不出面包。"}, {"text": "米饭", "is_correct": false, "explanation": "搭配：“做”能搭配“饭”，但应说“做了一顿饭”，不能说“一个米饭”。"}, {"text": "泥人", "is_correct": false, "explanation": "语义：句中用的是木条，做不出泥人。"}], "explanations": {"三角形": "三角形：用木条搭成的图形，与句中“做了一个”的语境一致。", "面包": "语义：句中用的是木条，做不出面包。", "米饭": "搭配：“做”能搭配“饭”，但应说“做了一顿饭”，不能说“一个米饭”。", "泥人": "语义：句中用的是木条，做不出泥人。"}, "sentence_index": 6, "correct_answer": "三角形"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他在乐队里敲了一个三角形。", "explanation": "这里应该用〈三角铁〉。三角形是图形，敲的应是打击乐器三角铁。"}, {"text": "便利店里的三角形很好吃。", "explanation": "这里应该用〈三角饭团〉。三角形是图形，不能吃，三角饭团才是食物。"}, {"text": "他同时喜欢两个女孩，陷入了三角形的恋爱。", "explanation": "这里应该用〈三角恋〉。三角形是图形，三人之间的感情纠葛要说三角恋。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c9caf03-da33-4142-a119-fea37774a70e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12445, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他在作业本上画了一条三角形。", "corrected_sentence": "他在作业本上画了一个三角形。", "error_description": "量词错误：“三角形”是图形，应用“个”，不能用“条”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c9caf03-da33-4142-a119-fea37774a70e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12445, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "数学课上，我们学习了三角形是面积。", "corrected_sentence": "数学课上，我们学习了三角形的面积。", "error_description": "错误：“三角形”和“面积”之间应用“的”表示所属，不能用“是”连接。应说“三角形的面积”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c9caf03-da33-4142-a119-fea37774a70e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
