INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12449, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "指已经没有用处、可以丢弃的纸张。", "primary_collocate": null, "pronunciation": "fèi zhǐ", "ipa": "fei˥˩ ʈʂɻ̩˨˩˦", "syllable_count": 2, "sentences": [{"text": "环保课告诉我们：废纸、塑料瓶和易拉罐不是废物，可以变成新东西。", "target_word": "废纸", "complexity_tier": "T5", "sentence_source": "generated"}, {"text": "桌子下面有很多废纸，请你捡起来。", "target_word": "废纸", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把废纸放进旁边的蓝色垃圾桶。", "target_word": "废纸", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把用过的废纸卖给了收废品的人。", "target_word": "废纸", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校每个月都会收集废纸。", "target_word": "废纸", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这些废纸可以送到工厂做新纸。", "target_word": "废纸", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "地上的废纸太多了，我们一起打扫吧。", "target_word": "废纸", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈把一堆废纸扔进了垃圾桶。", "target_word": "废纸", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "别把废纸扔在地上，要扔到垃圾桶里。", "target_word": "废纸", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明把废纸整理好，交给了老师。", "target_word": "废纸", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "一张废纸", "label": "量词"}, {"form": "一堆废纸", "label": "量词"}, {"form": "廢紙", "label": "繁体"}], "register": "中性", "sense_fingerprint": "没有用处、可丢弃或回收的纸", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9bfbe3a8-7aeb-4ee1-8a32-ba6db3e80028') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12449, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "废纸", "is_correct": true, "explanation": "正确：废纸和塑料瓶、易拉罐一样，都可以回收再利用。"}, {"text": "猫", "is_correct": false, "explanation": "语义：猫是有生命的动物，不能“变成新东西”，与“不是废物，可以变成新东西”的说法不符。"}, {"text": "糟粕", "is_correct": false, "explanation": "语义：糟粕本身就是被丢弃的渣滓，与“不是废物”的说法直接矛盾。"}, {"text": "蛋糕", "is_correct": false, "explanation": "语义：蛋糕是食品，吃掉就没有了，不能像塑料瓶、易拉罐那样回收再造。"}], "explanations": {"废纸": "正确：废纸和塑料瓶、易拉罐一样，都可以回收再利用。", "猫": "语义：猫是有生命的动物，不能“变成新东西”，与“不是废物，可以变成新东西”的说法不符。", "糟粕": "语义：糟粕本身就是被丢弃的渣滓，与“不是废物”的说法直接矛盾。", "蛋糕": "语义：蛋糕是食品，吃掉就没有了，不能像塑料瓶、易拉罐那样回收再造。"}, "sentence_index": 0, "correct_answer": "废纸"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他每天早上都在看废纸。", "explanation": "这里应该用〈报纸〉。废纸已经没有用处，不能拿来阅读；能读的应是报纸。"}, {"text": "工程师正在研究废纸，准备设计新的大楼。", "explanation": "这里应该用〈图纸〉。废纸只是没用的旧纸，不是用来设计工程的图纸。"}, {"text": "他收到了一张废纸，是朋友寄来的。", "explanation": "这里应该用〈信〉。废纸是没用的旧纸，不能当作朋友寄来的信。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c9caf03-da33-4142-a119-fea37774a70e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12449, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "废纸", "is_correct": true, "explanation": "正确：句中指地上散落、需要打扫的没用纸张，正是废纸。"}, {"text": "钢琴", "is_correct": false, "explanation": "语义：钢琴是大型乐器，不会多到散落在地上、需要一起打扫。"}, {"text": "道理", "is_correct": false, "explanation": "语义：道理是抽象的，不会散落在地上，也不用打扫。"}, {"text": "汽车", "is_correct": false, "explanation": "语义：汽车是大型交通工具，不会成堆散落在地上需要打扫。"}], "explanations": {"废纸": "正确：句中指地上散落、需要打扫的没用纸张，正是废纸。", "钢琴": "语义：钢琴是大型乐器，不会多到散落在地上、需要一起打扫。", "道理": "语义：道理是抽象的，不会散落在地上，也不用打扫。", "汽车": "语义：汽车是大型交通工具，不会成堆散落在地上需要打扫。"}, "sentence_index": 6, "correct_answer": "废纸"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他拿着一叠废纸去银行存款。", "explanation": "这里应该用〈钞票〉。废纸没有价值，不能存进银行；存款要用钞票。"}, {"text": "他把一叠废纸放进钱包里。", "explanation": "这里应该用〈纸币〉。废纸没有价值，不能当钱放进钱包；放进钱包的应是纸币。"}, {"text": "校长把废纸发给了比赛第一名的同学。", "explanation": "这里应该用〈奖状〉。废纸没有用处，不能作为奖励发给获奖者。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c9caf03-da33-4142-a119-fea37774a70e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12449, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "小明把废纸整理的很整齐。", "corrected_sentence": "小明把废纸整理得很整齐。", "error_description": "补语标记错误：“整理”后表示程度的补语应用“得”连接，写成“的”是错误。正确：整理得很整齐；错误：整理的很整齐。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c9caf03-da33-4142-a119-fea37774a70e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12449, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我把用过废纸丢了。", "corrected_sentence": "我把用过的废纸丢了。", "error_description": "定语标记错误：“用过”修饰“废纸”时要加“的”，应说“用过的废纸”，漏掉“的”是错误。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c9caf03-da33-4142-a119-fea37774a70e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
