INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12455, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "指物品经过处理后能够再次被利用。", "primary_collocate": null, "pronunciation": "kě huí shōu", "ipa": "kʰɤ˨˩˦ xweɪ˧˥ ʂoʊ˥˥", "syllable_count": 3, "sentences": [{"text": "这一设计的起源可追溯至1970年美国首届“地球日”活动，当时包装行业亟需一种公众易于识别的标识，以区分可回收材料与普通垃圾。", "target_word": "可回收", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "看到这个标志，就把可回收的东西放在蓝颜色的垃圾桶里。", "target_word": "可回收", "complexity_tier": "T4", "sentence_source": "mined"}, {"text": "这个瓶子是可回收的。", "target_word": "可回收", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "纸和塑料都是可回收的东西。", "target_word": "可回收", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请把可回收的垃圾放进蓝桶。", "target_word": "可回收", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种包装盒是可回收的吗？", "target_word": "可回收", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "旧衣服也是可回收的东西。", "target_word": "可回收", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "超市里有可回收的购物袋。", "target_word": "可回收", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "家里可回收的东西要分开放。", "target_word": "可回收", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "玻璃瓶是可回收的，别扔到别的桶里。", "target_word": "可回收", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "可回收物", "label": "复合"}, {"form": "可回收垃圾", "label": "复合"}], "register": "中性", "sense_fingerprint": "物品经处理后能再次利用，常用于垃圾分类", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '77085c74-6cb5-4c24-9776-6ad1cbffcff0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12455, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "甜美", "is_correct": false, "explanation": "语义：“甜美”形容味道或样子，不能用来区分材料能否再利用。"}, {"text": "热情", "is_correct": false, "explanation": "搭配：“热情”多形容人或态度，不与“材料”搭配。"}, {"text": "悲伤", "is_correct": false, "explanation": "语义：“悲伤”表示情绪，与句中讲的材料分类和标识不相关。"}, {"text": "可回收", "is_correct": true, "explanation": "可回收指物品经处理后能再利用，正好用来区分材料与普通垃圾。"}], "explanations": {"甜美": "语义：“甜美”形容味道或样子，不能用来区分材料能否再利用。", "热情": "搭配：“热情”多形容人或态度，不与“材料”搭配。", "悲伤": "语义：“悲伤”表示情绪，与句中讲的材料分类和标识不相关。", "可回收": "可回收指物品经处理后能再利用，正好用来区分材料与普通垃圾。"}, "sentence_index": 0, "correct_answer": "可回收"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们要可回收旧电池。", "explanation": "这里应该用〈回收〉。“可回收”是形容词，不能直接带宾语，表示动作要用动词“回收”。"}, {"text": "风能是一种可回收能源。", "explanation": "这里应该用〈可再生〉。风能是自然持续产生的能源，不是经处理后再利用的物品，应该说可再生。"}, {"text": "请把废纸送到可回收站。", "explanation": "这里应该用〈回收站〉。“可回收”描述物品的属性，不能用来指地点，应该说回收站。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3995bbd3-30f8-4c0f-9a78-6e3664693c5d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12455, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "易碎", "is_correct": false, "explanation": "语义：旧衣服不会“易碎”，句子说的是能否回收。"}, {"text": "寒冷", "is_correct": false, "explanation": "语义：“寒冷”形容温度感受，与旧衣服的回收属性无关。"}, {"text": "滚烫", "is_correct": false, "explanation": "搭配：“滚烫”形容温度很高，不用来说旧衣服是滚烫的东西。"}, {"text": "可回收", "is_correct": true, "explanation": "旧衣服经处理后可以再利用，所以是可回收的东西。"}], "explanations": {"易碎": "语义：旧衣服不会“易碎”，句子说的是能否回收。", "寒冷": "语义：“寒冷”形容温度感受，与旧衣服的回收属性无关。", "滚烫": "搭配：“滚烫”形容温度很高，不用来说旧衣服是滚烫的东西。", "可回收": "旧衣服经处理后可以再利用，所以是可回收的东西。"}, "sentence_index": 6, "correct_answer": "可回收"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他是一个可回收的人。", "explanation": "这里不能用〈可回收〉。“可回收”只用来说物品能否再利用，不能用来形容人，形容人要说可靠等词。"}, {"text": "我想把那句话可回收。", "explanation": "这里应该用〈收回〉。“可回收”指物品能再利用，收回言语要说收回。"}, {"text": "昨天的比赛是可回收的。", "explanation": "这里不能用〈可回收〉。“可回收”只用于能再利用的物品，比赛是活动，不能说可回收。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3995bbd3-30f8-4c0f-9a78-6e3664693c5d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12455, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这种塑料袋是可回收。", "corrected_sentence": "这种塑料袋是可回收的。", "error_description": "漏“的”：“是”后接形容词作谓语时要用“是……的”结构，应说“是可回收的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3995bbd3-30f8-4c0f-9a78-6e3664693c5d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12455, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这种纸没可回收。", "corrected_sentence": "这种纸不可回收。", "error_description": "否定词错误：“可回收”前要用“不”，不能用“没”，应说“不可回收”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3995bbd3-30f8-4c0f-9a78-6e3664693c5d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
