INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12457, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "property", "definition": "颜色是物体吸收和反射不同波长的光，在人眼中产生的视觉印象。", "primary_collocate": null, "pronunciation": "yán sè", "ipa": "jɛn˧˥ sɤ˥˩", "syllable_count": 2, "sentences": [{"text": "看到这个标志，就把可回收的东西放在蓝颜色的垃圾桶里。", "target_word": "颜色", "complexity_tier": "T4", "sentence_source": "mined"}, {"text": "红灯的颜色很亮，司机老远就能看见。", "target_word": "颜色", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这件衣服的颜色太深了，我想换一件浅的。", "target_word": "颜色", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "树叶到了秋天会改变颜色，由绿变黄。", "target_word": "颜色", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你喜欢什么颜色的书包？", "target_word": "颜色", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "彩虹有七种颜色。", "target_word": "颜色", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "太阳下山以后，天空的颜色慢慢变暗了。", "target_word": "颜色", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这两块布的颜色不一样，一块红，一块粉。", "target_word": "颜色", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个房间的颜色很暖，让人觉得很舒服。", "target_word": "颜色", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "蓝色是我最喜欢的颜色，因为它像大海。", "target_word": "颜色", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "种", "label": "量词"}, {"form": "顏色", "label": "繁体"}], "register": "中性", "sense_fingerprint": "物体反射光后眼睛看到的颜色，如深浅、冷暖", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '77c37cae-b219-4aee-bb4e-93cb237f46fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12457, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "颜色", "is_correct": true, "explanation": "颜色（yán sè）：物体反射光后眼睛看到的颜色，是本词条的读音与意义。"}, {"text": "严肃", "is_correct": false, "explanation": "yán 相同，第二音节韵母 e 与 u 不同，意思是严肃。"}, {"text": "眼色", "is_correct": false, "explanation": "yǎn（上声）与 yán（阳平）声调不同，意思是眼神示意。"}, {"text": "难色", "is_correct": false, "explanation": "声母 n 与 y 不同，意思是为难的神色。"}], "explanations": {"颜色": "颜色（yán sè）：物体反射光后眼睛看到的颜色，是本词条的读音与意义。", "严肃": "yán 相同，第二音节韵母 e 与 u 不同，意思是严肃。", "眼色": "yǎn（上声）与 yán（阳平）声调不同，意思是眼神示意。", "难色": "声母 n 与 y 不同，意思是为难的神色。"}, "sentence_index": null, "correct_answer": "颜色"}, "level_3": {"options": [{"text": "颜色", "is_correct": true, "explanation": "颜色：修饰在“蓝”之后，指垃圾桶所对应的颜色，句意通顺。"}, {"text": "形状", "is_correct": false, "explanation": "语义：形状指外形，不能与“蓝”组合来指颜色。"}, {"text": "味道", "is_correct": false, "explanation": "语义：味道指气味或滋味，与“蓝”不能搭配，句意不通。"}, {"text": "声音", "is_correct": false, "explanation": "语义：声音指声响，与“蓝”不能搭配，句意不通。"}], "explanations": {"颜色": "颜色：修饰在“蓝”之后，指垃圾桶所对应的颜色，句意通顺。", "形状": "语义：形状指外形，不能与“蓝”组合来指颜色。", "味道": "语义：味道指气味或滋味，与“蓝”不能搭配，句意不通。", "声音": "语义：声音指声响，与“蓝”不能搭配，句意不通。"}, "sentence_index": 0, "correct_answer": "颜色"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这幅画很颜色，大家都很喜欢。", "explanation": "这里应该用〈鲜艳〉或〈好看〉。“颜色”是名词，不能直接受“很”修饰。"}, {"text": "我把颜色放进了书包里。", "explanation": "这里把〈颜色〉当作实物。颜色是物体的视觉属性，不能被放进书包。"}, {"text": "这只颜色很好看。", "explanation": "这里应该用〈种〉。颜色的量词是“种”，不用“只”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3ef8427-8705-4e76-a145-d2df3a556326') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12457, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "颜色", "is_correct": true, "explanation": "颜色：作“天空的”的中心语，指天空的颜色随时间变暗，句意通顺。"}, {"text": "温度", "is_correct": false, "explanation": "语义：温度指冷热程度，天空的温度不会变暗，句意不通。"}, {"text": "重量", "is_correct": false, "explanation": "语义：重量指轻重，天空的重量不会变暗，句意不通。"}, {"text": "速度", "is_correct": false, "explanation": "搭配：“变暗”的主语不能是速度，“天空的速度”慢慢变暗不成立。"}], "explanations": {"颜色": "颜色：作“天空的”的中心语，指天空的颜色随时间变暗，句意通顺。", "温度": "语义：温度指冷热程度，天空的温度不会变暗，句意不通。", "重量": "语义：重量指轻重，天空的重量不会变暗，句意不通。", "速度": "搭配：“变暗”的主语不能是速度，“天空的速度”慢慢变暗不成立。"}, "sentence_index": 6, "correct_answer": "颜色"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这首歌的颜色很好听。", "explanation": "这里应该用〈旋律〉。颜色是眼睛看到的，不能用“好听”来形容。"}, {"text": "他的颜色很高，很多人喜欢他。", "explanation": "这里应该用〈颜值〉。颜色指色彩本身，不能指相貌好看。"}, {"text": "请你给这幅画颜色。", "explanation": "这里应该用〈上色〉。“颜色”是名词，不能直接作动词。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3ef8427-8705-4e76-a145-d2df3a556326') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12457, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他挑了一只颜色的窗帘。", "corrected_sentence": "他挑了一种颜色的窗帘。", "error_description": "量词错误：“颜色”的量词用“种”，不用“只”，应说“一种颜色”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3ef8427-8705-4e76-a145-d2df3a556326') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12457, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这块布把颜色慢慢变淡了。", "corrected_sentence": "这块布的颜色慢慢变淡了。", "error_description": "施事错误：“把”字句需要有致使者，而布本身不会使自己的颜色变淡，应说“这块布的颜色慢慢变淡了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3ef8427-8705-4e76-a145-d2df3a556326') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
