INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12458, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "圆圈是一个闭合的圆形线条，所有点到中心距离相等。", "primary_collocate": null, "pronunciation": "yuán quān", "ipa": "ɥɛn˧˥ tɕʰɥɛn˥", "syllable_count": 2, "sentences": [{"text": "它的设计像一个绿色的箭头圆圈，表示废物可以被重复利用。", "target_word": "圆圈", "complexity_tier": "T4", "sentence_source": "mined"}, {"text": "老师在黑板上画了一个大圆圈。", "target_word": "圆圈", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请你在正确答案上画一个圆圈。", "target_word": "圆圈", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "地图上的红圆圈是我们学校。", "target_word": "圆圈", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她用红笔把这个词画了一个圆圈。", "target_word": "圆圈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个圆圈的中心有一个小黑点。", "target_word": "圆圈", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "纸上的圆圈画得很圆，像用圆规画的。", "target_word": "圆圈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在沙地上用树枝画出一个圆圈。", "target_word": "圆圈", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请在表格里的圆圈中写上你的名字。", "target_word": "圆圈", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个标志是一个蓝色的圆圈，中间有一条线。", "target_word": "圆圈", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "圓圈", "label": "繁体"}], "register": "中性", "sense_fingerprint": "圆圈：画出来的闭合圆形线条，各点到中心距离相等", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '78836ff6-43bd-45b4-82eb-9adfdab50fcf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12458, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "蛋糕", "is_correct": false, "explanation": "语义：蛋糕是食物，不能作为箭头形的标志图形。"}, {"text": "钢琴", "is_correct": false, "explanation": "语义：钢琴是乐器，与设计图形的描述无关。"}, {"text": "圆圈", "is_correct": true, "explanation": "“圆圈”指画出的闭合圆形线条，与绿色箭头围成循环、表示重复利用的标志相符。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：“绿色的箭头颜色”不成立，“颜色”不能作为设计图形的主体。"}], "explanations": {"蛋糕": "语义：蛋糕是食物，不能作为箭头形的标志图形。", "钢琴": "语义：钢琴是乐器，与设计图形的描述无关。", "圆圈": "“圆圈”指画出的闭合圆形线条，与绿色箭头围成循环、表示重复利用的标志相符。", "颜色": "搭配：“绿色的箭头颜色”不成立，“颜色”不能作为设计图形的主体。"}, "sentence_index": 0, "correct_answer": "圆圈"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "老师在黑板上画了一只大圆圈。", "explanation": "这里应该用〈个〉。“圆圈”的量词是“个”，“只”用于动物，不能用来数圆圈。"}, {"text": "他用圆圈盖了一座房子。", "explanation": "这里应该用〈砖〉。“圆圈”是画出来的线条，不是建材，不能用来盖房子。"}, {"text": "他用圆圈给妈妈写了一封信。", "explanation": "这里应该用〈笔〉。“圆圈”是画出来的圆形线条，不是写字的工具。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f8ff73d8-aa3f-4a7c-8686-6aff4021dffb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12458, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "方框", "is_correct": false, "explanation": "语义：方框是方形的，与“画得很圆”的描写相矛盾。"}, {"text": "圆圈", "is_correct": true, "explanation": "“圆圈”是闭合的圆形线条，与纸上的图形画得很圆、像用圆规画的描写相符。"}, {"text": "三角", "is_correct": false, "explanation": "语义：三角形有三个角，与“画得很圆”的描写相矛盾。"}, {"text": "直线", "is_correct": false, "explanation": "搭配：直线是笔直的线，不能用“画得很圆”来描述，搭配不当。"}], "explanations": {"方框": "语义：方框是方形的，与“画得很圆”的描写相矛盾。", "圆圈": "“圆圈”是闭合的圆形线条，与纸上的图形画得很圆、像用圆规画的描写相符。", "三角": "语义：三角形有三个角，与“画得很圆”的描写相矛盾。", "直线": "搭配：直线是笔直的线，不能用“画得很圆”来描述，搭配不当。"}, "sentence_index": 6, "correct_answer": "圆圈"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这本书一共有三百个圆圈。", "explanation": "这里应该用〈页〉。“圆圈”是画出来的圆形线条，不能用来表示书的页数。"}, {"text": "他的圆圈脸很可爱。", "explanation": "这里应该用〈圆脸〉。“圆圈”不能直接作定语修饰脸，描述脸形要用“圆脸”。"}, {"text": "这个皮球是一个白色的圆圈。", "explanation": "这里应该用〈圆球〉。“圆圈”指平面上的圆形线条，立体的皮球要说“圆球”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f8ff73d8-aa3f-4a7c-8686-6aff4021dffb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12458, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他在纸上画了一只圆圈。", "corrected_sentence": "他在纸上画了一个圆圈。", "error_description": "错误形式：“一只圆圈”。正确形式：“一个圆圈”。“圆圈”是无生命的图形，量词用“个”，“只”用于动物。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f8ff73d8-aa3f-4a7c-8686-6aff4021dffb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12458, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他在沙地上画了一个圆圈个。", "corrected_sentence": "他在沙地上画了一个圆圈。", "error_description": "错误形式：“圆圈个”，名词后多加了一个量词“个”。正确形式：“一个圆圈”。数量词只需用一次，“个”已经出现在“一个”中，名词后不能再加。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f8ff73d8-aa3f-4a7c-8686-6aff4021dffb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
