INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12459, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "指从当前回溯到过去某个时间点。", "primary_collocate": null, "pronunciation": "zhuī sù dào", "ipa": "ʈʂweɪ˥ su˥˩ tɑʊ˥˩", "syllable_count": 3, "sentences": [{"text": "这个标志的历史可以追溯到20世纪70年代。", "target_word": "追溯到", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "这个节日的历史可以追溯到唐朝。", "target_word": "追溯到", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们家的故事一直追溯到一百年前。", "target_word": "追溯到", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这座老桥最早可以追溯到明朝。", "target_word": "追溯到", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "专家把这种习惯追溯到了两千年前。", "target_word": "追溯到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种茶的历史追溯到两千多年前。", "target_word": "追溯到", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "往前追溯到十年前，这里还是一片农田。", "target_word": "追溯到", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家饭店的历史要追溯到爷爷那一代。", "target_word": "追溯到", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这首歌的来源可以追溯到清朝。", "target_word": "追溯到", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师说，汉字的起源能追溯到三千多年前。", "target_word": "追溯到", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "追溯到了", "label": "体标"}], "register": "中性", "sense_fingerprint": "追溯到：事物的历史或起源可以回溯到过去的某个时间点", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '78836ff6-43bd-45b4-82eb-9adfdab50fcf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12459, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "追溯到", "is_correct": true, "explanation": "正确：“追溯到”表示从现在回到过去的某个时间点，与“历史可以……”搭配，符合句意。"}, {"text": "预测到", "is_correct": false, "explanation": "语义：“预测”指推测未来，句中说的是过去的历史，不能预测到20世纪70年代。"}, {"text": "推迟到", "is_correct": false, "explanation": "语义：“推迟”指把事情往后延，历史不能被推迟到某个过去的时间点。"}, {"text": "追求到", "is_correct": false, "explanation": "配价：“追求”要求目标宾语，不能接“到”加时间点作补语。"}], "explanations": {"追溯到": "正确：“追溯到”表示从现在回到过去的某个时间点，与“历史可以……”搭配，符合句意。", "预测到": "语义：“预测”指推测未来，句中说的是过去的历史，不能预测到20世纪70年代。", "推迟到": "语义：“推迟”指把事情往后延，历史不能被推迟到某个过去的时间点。", "追求到": "配价：“追求”要求目标宾语，不能接“到”加时间点作补语。"}, "sentence_index": 0, "correct_answer": "追溯到"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "天气预报追溯到明天会下雨。", "explanation": "这里应该用〈预测〉。追溯到是从现在回到过去的时间点，不能指向未来的天气。"}, {"text": "假期结束后，我们终于追溯到了学校。", "explanation": "这里应该用〈回到〉。追溯到只用于时间、历史或起源，不表示人的身体回到某个地方。"}, {"text": "会议被追溯到下周三举行。", "explanation": "这里应该用〈推迟〉。追溯到只能指向过去的时间，不能把未来的会议往后挪。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f8ff73d8-aa3f-4a7c-8686-6aff4021dffb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12459, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "追溯到", "is_correct": true, "explanation": "正确：“往前追溯到十年前”表示回到十年前的时间点，符合句意。"}, {"text": "出发到", "is_correct": false, "explanation": "搭配：“出发”指离开某地前往别处，不能与“到十年前”这样的时间点搭配。"}, {"text": "寄托到", "is_correct": false, "explanation": "配价：“寄托”的宾语是希望或感情，不能接时间作补语。"}, {"text": "预言到", "is_correct": false, "explanation": "语义：“预言”指预先说出未来的事，与“往前”回溯过去的语义相反。"}], "explanations": {"追溯到": "正确：“往前追溯到十年前”表示回到十年前的时间点，符合句意。", "出发到": "搭配：“出发”指离开某地前往别处，不能与“到十年前”这样的时间点搭配。", "寄托到": "配价：“寄托”的宾语是希望或感情，不能接时间作补语。", "预言到": "语义：“预言”指预先说出未来的事，与“往前”回溯过去的语义相反。"}, "sentence_index": 6, "correct_answer": "追溯到"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他一生都在追溯到自由。", "explanation": "这里应该用〈追求〉。追溯到表示回溯到过去的源头，不能说追溯到某个理想或目标。"}, {"text": "工人们把货物追溯到了三楼。", "explanation": "这里应该用〈搬〉。追溯到用于时间、历史或起源，不能描述把货物搬到某层楼。"}, {"text": "我跑了一路，终于追溯到了那辆公交车。", "explanation": "这里应该用〈追上〉。追溯到表示回溯到过去的时间或源头，不能表示赶上正在前行的车辆。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f8ff73d8-aa3f-4a7c-8686-6aff4021dffb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12459, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这座庙的历史可以追溯到到宋朝。", "corrected_sentence": "这座庙的历史可以追溯到宋朝。", "error_description": "错误：“追溯到”后多加了一个“到”，补语重复，句子不合语法。正确应删去多余的“到”，即“可以追溯到宋朝”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f8ff73d8-aa3f-4a7c-8686-6aff4021dffb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12459, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这种陶器的历史可以追溯到着上个世纪。", "corrected_sentence": "这种陶器的历史可以追溯到上个世纪。", "error_description": "错误：“到”后多加了“着”，“着”表示动作持续，不能接在补语“到”之后。正确应为“可以追溯到上个世纪”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f8ff73d8-aa3f-4a7c-8686-6aff4021dffb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
