INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12461, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指自然环境中出现对人类和其他生物有害的物质，导致生态平衡被破坏的现象。", "primary_collocate": null, "pronunciation": "huán jìng wū rǎn wèn tí", "ipa": "xwan˧˥ tɕiŋ˥˩ u˥ ʐan˨˩˦ wən˥˩ tʰi˧˥", "syllable_count": 6, "sentences": [{"text": "当时，人们开始关心环境污染问题。", "target_word": "环境污染问题", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "这个城市的环境污染问题越来越严重。", "target_word": "环境污染问题", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府正在想办法解决环境污染问题。", "target_word": "环境污染问题", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工厂太多会带来环境污染问题。", "target_word": "环境污染问题", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师让我们写一篇关于环境污染问题的文章。", "target_word": "环境污染问题", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你觉得环境污染问题应该怎么解决？", "target_word": "环境污染问题", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很多国家都有环境污染问题。", "target_word": "环境污染问题", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "垃圾太多也会造成环境污染问题。", "target_word": "环境污染问题", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一直很关注环境污染问题。", "target_word": "环境污染问题", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "报纸上常常讨论环境污染问题。", "target_word": "环境污染问题", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "環境污染問題", "label": "繁体"}], "register": "中性", "sense_fingerprint": "有害物质破坏生态平衡的环境污染现象", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6a1fb72f-7f26-46aa-b253-c34484e0d5e4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12461, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "环境污染问题", "is_correct": true, "explanation": "与“关心”搭配，指自然环境中有害物质破坏生态平衡的现象，符合句意。"}, {"text": "垃圾桶", "is_correct": false, "explanation": "搭配：“关心”的对象是问题或人，“垃圾桶”是具体器物，不能说“关心垃圾桶”。"}, {"text": "书桌", "is_correct": false, "explanation": "搭配：“书桌”是家具，不是“关心”的对象。"}, {"text": "夜宵", "is_correct": false, "explanation": "语义：“夜宵”指夜里吃的小吃，与人们开始关注的环境问题无关。"}], "explanations": {"环境污染问题": "与“关心”搭配，指自然环境中有害物质破坏生态平衡的现象，符合句意。", "垃圾桶": "搭配：“关心”的对象是问题或人，“垃圾桶”是具体器物，不能说“关心垃圾桶”。", "书桌": "搭配：“书桌”是家具，不是“关心”的对象。", "夜宵": "语义：“夜宵”指夜里吃的小吃，与人们开始关注的环境问题无关。"}, "sentence_index": 0, "correct_answer": "环境污染问题"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个句子的结构有环境污染问题。", "explanation": "这里应该用〈语法问题〉。“环境污染问题”指自然环境中有害物质造成的污染，不能用来说句子结构上的毛病。"}, {"text": "他的身体有环境污染问题，最近总是发烧。", "explanation": "这里应该用〈健康问题〉。“环境污染问题”指环境中有害物质造成的污染，不能用来说人的身体状况。"}, {"text": "他的数学成绩有环境污染问题。", "explanation": "这里应该用〈错误〉。“环境污染问题”指环境中的污染现象，不能用来指学习成绩上的错误。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '69f4ea35-59be-4a4b-a754-c6218d71bbb6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12461, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "环境污染问题", "is_correct": true, "explanation": "“很多国家都有”后接的是普遍存在的社会问题，符合句意。"}, {"text": "长城", "is_correct": false, "explanation": "语义：长城主要在中国境内，“很多国家都有长城”不符合常识。"}, {"text": "长江", "is_correct": false, "explanation": "语义：长江是中国境内的河流，“很多国家都有长江”不成立。"}, {"text": "故宫", "is_correct": false, "explanation": "搭配：“故宫”是北京的专名，不能用于“很多国家都有”这种泛指。"}], "explanations": {"环境污染问题": "“很多国家都有”后接的是普遍存在的社会问题，符合句意。", "长城": "语义：长城主要在中国境内，“很多国家都有长城”不符合常识。", "长江": "语义：长江是中国境内的河流，“很多国家都有长江”不成立。", "故宫": "搭配：“故宫”是北京的专名，不能用于“很多国家都有”这种泛指。"}, "sentence_index": 6, "correct_answer": "环境污染问题"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "报纸上常常讨论这位演员的环境污染问题。", "explanation": "这里应该用〈绯闻〉。“环境污染问题”指环境中有害物质造成的污染，不能用于一位演员的私人事务。"}, {"text": "报纸上常常讨论这道数学题的环境污染问题。", "explanation": "这里应该用〈难点〉。“环境污染问题”指环境中的污染现象，不能用来指数学题的难处。"}, {"text": "报纸上常常讨论这本书的环境污染问题。", "explanation": "这里应该用〈内容〉。“环境污染问题”指环境中的污染现象，不能用来指书中的内容。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '69f4ea35-59be-4a4b-a754-c6218d71bbb6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12461, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "政府决定重点治理这条环境污染问题。", "corrected_sentence": "政府决定重点治理这个环境污染问题。", "error_description": "量词错误：“问题”应用“个”，“条”用于河流、路等细长的东西，不能用来计量“问题”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '69f4ea35-59be-4a4b-a754-c6218d71bbb6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
