INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12464, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "图案指由线条、形状、颜色等构成的、用于装饰或表示的图形。", "primary_collocate": null, "pronunciation": "tú àn", "ipa": "tʰu˧˥ an˥˩", "syllable_count": 2, "sentences": [{"text": "为了鼓励大家分类垃圾，一位设计师画了这个简单又容易认的图案。", "target_word": "图案", "complexity_tier": "T4", "sentence_source": "mined"}, {"text": "这件衣服上有一个可爱的小熊图案。", "target_word": "图案", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她喜欢买有花图案的杯子。", "target_word": "图案", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地毯上的图案是用红色和黄色画的。", "target_word": "图案", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个图案由线条和圆圈组成。", "target_word": "图案", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "设计师在盘子上画了一个新图案。", "target_word": "图案", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "墙上的图案看起来像一只鸟。", "target_word": "图案", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你想在帽子上印什么图案？", "target_word": "图案", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这块布的图案很漂亮，颜色也好看。", "target_word": "图案", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们在纸上画了很多有趣的图案。", "target_word": "图案", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "种", "label": "量词"}, {"form": "圖案", "label": "繁体"}], "register": "中性", "sense_fingerprint": "由线条、形状、颜色构成的装饰或标识图形", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6a1fb72f-7f26-46aa-b253-c34484e0d5e4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12464, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "图案", "is_correct": true, "explanation": "正确：图案指由线条、形状构成的图形，设计师画出“简单又容易认”的图形正是图案。"}, {"text": "味道", "is_correct": false, "explanation": "搭配：“画”的对象是可见的图形，味道不能被画出来。"}, {"text": "歌曲", "is_correct": false, "explanation": "语义：歌曲是声音作品，不是可以画出来的图形，与“容易认”的图形义也不搭。"}, {"text": "价格", "is_correct": false, "explanation": "语义：价格是金额，不能被画出来，也不是能被“认”出的图形。"}], "explanations": {"图案": "正确：图案指由线条、形状构成的图形，设计师画出“简单又容易认”的图形正是图案。", "味道": "搭配：“画”的对象是可见的图形，味道不能被画出来。", "歌曲": "语义：歌曲是声音作品，不是可以画出来的图形，与“容易认”的图形义也不搭。", "价格": "语义：价格是金额，不能被画出来，也不是能被“认”出的图形。"}, "sentence_index": 0, "correct_answer": "图案"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他们制定了一个新图案，准备下个月实施。", "explanation": "这里应该用〈方案〉。图案指装饰或标识性的图样，制定计划、方案时不能用图案，应说“方案”。"}, {"text": "医生在屏幕上看到了清晰的图案，判断病人的肺没有问题。", "explanation": "这里应该用〈图像〉。图像指X光、扫描等得到的影像，图案是装饰或标识性图样，不能指医学影像。"}, {"text": "他用一个新图案算出了今天的税额。", "explanation": "这里应该用〈公式〉。图案是装饰或标识性图样，不能用来计算，算税额要用“公式”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '69f4ea35-59be-4a4b-a754-c6218d71bbb6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12464, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "图案", "is_correct": true, "explanation": "正确：墙上的图案是绘制的图形，看起来像一只鸟，符合语境。"}, {"text": "声音", "is_correct": false, "explanation": "搭配：声音不能附着在墙上，也不能“看起来像一只鸟”。"}, {"text": "温度", "is_correct": false, "explanation": "语义：温度是数值，没有可以“看起来像”的形状。"}, {"text": "价钱", "is_correct": false, "explanation": "配价：“看起来像”要求有形体的主语，价钱不能充当这个主语。"}], "explanations": {"图案": "正确：墙上的图案是绘制的图形，看起来像一只鸟，符合语境。", "声音": "搭配：声音不能附着在墙上，也不能“看起来像一只鸟”。", "温度": "语义：温度是数值，没有可以“看起来像”的形状。", "价钱": "配价：“看起来像”要求有形体的主语，价钱不能充当这个主语。"}, "sentence_index": 6, "correct_answer": "图案"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这张图案显示了今年每个月的销售额。", "explanation": "这里应该用〈图表〉。图表用于展示数据，图案是装饰或标识性图样，不能用来显示销售额。"}, {"text": "工程师看了这张图案，决定加固大楼的结构。", "explanation": "这里应该用〈图纸〉。图纸用于工程设计，图案不用于技术性的结构设计。"}, {"text": "这部小说的图案很复杂，读者需要仔细推理才能看懂。", "explanation": "这里应该用〈情节〉。图案指装饰或标识性的图样，不能指小说中的故事发展，说“情节很复杂”才对。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '69f4ea35-59be-4a4b-a754-c6218d71bbb6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12464, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这条围巾上织着两只漂亮的图案。", "corrected_sentence": "这条围巾上织着两个漂亮的图案。", "error_description": "量词错误：“图案”应用“个”计量，“只”用于动物等，不能用来计量图案。正确说法是“两个漂亮的图案”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '69f4ea35-59be-4a4b-a754-c6218d71bbb6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12464, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她在本子上画了三匹漂亮的图案。", "corrected_sentence": "她在本子上画了三个漂亮的图案。", "error_description": "量词错误：“图案”应用“个”或“种”计量，“匹”用于马或布，不能用来计量图案。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '69f4ea35-59be-4a4b-a754-c6218d71bbb6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12467, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '69f4ea35-59be-4a4b-a754-c6218d71bbb6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12467, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '69f4ea35-59be-4a4b-a754-c6218d71bbb6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12467, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "指过去使用过的、已经不再新或不再常用的物品。", "primary_collocate": null, "pronunciation": "jiù wù", "ipa": "tɕjou˥˩ u˥˩", "syllable_count": 2, "sentences": [{"text": "第一个箭头是减少扔掉的东西，第二个是把旧物再用，第三个是把垃圾变成新东西。", "target_word": "旧物", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "奶奶家的阁楼里放着很多旧物。", "target_word": "旧物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我把不用的旧物送给了朋友。", "target_word": "旧物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "搬家以前，我们先整理了旧物。", "target_word": "旧物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些旧物虽然不新，但是很有用。", "target_word": "旧物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小区里有地方回收旧物。", "target_word": "旧物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他喜欢在周末去市场买旧物。", "target_word": "旧物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈用旧物做了一个漂亮的花盆。", "target_word": "旧物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件旧物是爷爷留下来的。", "target_word": "旧物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子长大了，我们把旧物捐给了需要的人。", "target_word": "旧物", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "件", "label": "量词"}, {"form": "旧物改造", "label": "复合"}, {"form": "舊物", "label": "繁体"}], "register": "通用", "sense_fingerprint": "不再新、不常用的旧东西，可整理、回收或再利用", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6a1fb72f-7f26-46aa-b253-c34484e0d5e4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12467, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "旧物", "is_correct": true, "explanation": "正确：旧物指已不新、不常用的旧东西，“把旧物再用”即重新利用，与箭头说明一致。"}, {"text": "美食", "is_correct": false, "explanation": "语义：美食是可以吃的食物，不是可以“再用”的物品。"}, {"text": "新品", "is_correct": false, "explanation": "语义：新品指新出的产品，与“再用”的旧物相反，与“减少扔掉”的语境矛盾。"}, {"text": "宠物", "is_correct": false, "explanation": "搭配：“再用”不能用于宠物，宠物是生命，不能像物品那样被再利用。"}], "explanations": {"旧物": "正确：旧物指已不新、不常用的旧东西，“把旧物再用”即重新利用，与箭头说明一致。", "美食": "语义：美食是可以吃的食物，不是可以“再用”的物品。", "新品": "语义：新品指新出的产品，与“再用”的旧物相反，与“减少扔掉”的语境矛盾。", "宠物": "搭配：“再用”不能用于宠物，宠物是生命，不能像物品那样被再利用。"}, "sentence_index": 0, "correct_answer": "旧物"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "很多旧物都来参加了我的生日聚会，我们聊了一整晚。", "explanation": "这里应该用〈老朋友〉。旧物指过去用过的物品，不能指以前认识的人，也不会来参加聚会。"}, {"text": "这次地震的旧物非常严重，很多房子都倒了。", "explanation": "这里应该用〈灾情〉。“旧物”指过去用过的物品，不能指地震造成的破坏，描述灾情应说“灾情”。"}, {"text": "我奶奶年纪大了，已经是旧物了，身体不太好。", "explanation": "这里应该用〈老人〉或〈年老〉。旧物指过去用过的东西，不能指人；说人年纪大要用“老”或“老人”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '69f4ea35-59be-4a4b-a754-c6218d71bbb6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12467, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "旧物", "is_correct": true, "explanation": "正确：旧物是过去用过、不再新的物品，“去市场买旧物”符合二手市场的语境。"}, {"text": "空气", "is_correct": false, "explanation": "搭配：“买”的对象是商品，空气不能用“买”。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气是气象状况，不是可以购买的东西。"}, {"text": "节日", "is_correct": false, "explanation": "语义：节日是时间段，不是商品，不能去市场买。"}], "explanations": {"旧物": "正确：旧物是过去用过、不再新的物品，“去市场买旧物”符合二手市场的语境。", "空气": "搭配：“买”的对象是商品，空气不能用“买”。", "天气": "语义：天气是气象状况，不是可以购买的东西。", "节日": "语义：节日是时间段，不是商品，不能去市场买。"}, "sentence_index": 6, "correct_answer": "旧物"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这次考试他犯了很多旧物。", "explanation": "这里应该用〈错误〉。旧物指过去用过的物品，不能被“犯”，犯错误应说“错误”。"}, {"text": "父亲去世后，他的旧物是我一直想继承的事业。", "explanation": "这里应该用〈事业〉。旧物指过去用过的物品，不能指需要继承的事业。"}, {"text": "妈妈的旧物是一首很好听的歌。", "explanation": "这里应该用〈歌曲〉。“旧物”指过去用过的物品，不能指一首歌，应说“歌曲”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '69f4ea35-59be-4a4b-a754-c6218d71bbb6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12467, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我在箱子里找到一条旧物。", "corrected_sentence": "我在箱子里找到一件旧物。", "error_description": "量词错误：“旧物”应用“件”计量，“条”用于细长物，不能用来计量旧物。正确说法是“一件旧物”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '69f4ea35-59be-4a4b-a754-c6218d71bbb6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12467, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那家店里有一位很漂亮的旧物。", "corrected_sentence": "那家店里有一件很漂亮的旧物。", "error_description": "量词错误：“位”只用于人，“旧物”是物品，应用“件”计量。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '69f4ea35-59be-4a4b-a754-c6218d71bbb6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12469, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'deebcdfc-2623-4b3b-a262-1127910088b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
