INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12469, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指事物具有的重大价值、意义或影响的程度。", "primary_collocate": null, "pronunciation": "zhòng yào xìng", "ipa": "ʈʂʊŋ˥˩ jɑʊ˥˩ ɕiŋ˥˩", "syllable_count": 3, "sentences": [{"text": "员工需要接受培训，了解隐私保护的重要性，并知道违反规则的后果。", "target_word": "重要性", "complexity_tier": "T4", "sentence_source": "mined"}, {"text": "虽然各国的回收系统不同，但这个标志帮助人们理解保护环境的重要性。", "target_word": "重要性", "complexity_tier": "T4", "sentence_source": "mined"}, {"text": "老师常常提醒我们睡眠的重要性。", "target_word": "重要性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "医生向大家说明了运动的重要性。", "target_word": "重要性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他终于明白了学习外语的重要性。", "target_word": "重要性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这次会议强调了团队合作的重要性。", "target_word": "重要性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子们要从小知道节约用水的重要性。", "target_word": "重要性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这件事让我认识到诚实的重要性。", "target_word": "重要性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这篇文章讲的是早餐对健康的重要性。", "target_word": "重要性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师把安全的重要性写在了黑板上。", "target_word": "重要性", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "重要性：事物的重大价值、意义或影响程度", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6b6dab98-14d7-4430-bd0f-b102915e1fde') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12469, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "重要性", "is_correct": true, "explanation": "正确：“了解……的重要性”表示理解隐私保护的价值，符合句意。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：隐私保护没有颜色，句子说的是要了解它的价值。"}, {"text": "味道", "is_correct": false, "explanation": "语义：“味道”指饮食或气味的感受，不能指隐私保护的价值。"}, {"text": "速度", "is_correct": false, "explanation": "语义：“速度”说快慢，不指隐私保护的价值或意义，句子要的是表示价值的词。"}], "explanations": {"重要性": "正确：“了解……的重要性”表示理解隐私保护的价值，符合句意。", "颜色": "语义：隐私保护没有颜色，句子说的是要了解它的价值。", "味道": "语义：“味道”指饮食或气味的感受，不能指隐私保护的价值。", "速度": "语义：“速度”说快慢，不指隐私保护的价值或意义，句子要的是表示价值的词。"}, "sentence_index": 0, "correct_answer": "重要性"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这件事的重要性很长，我们要认真对待。", "explanation": "这里应该用〈大〉。“长”说长度或时间，不能用来形容“重要性”；“重要性”说程度，应说“很大”。"}, {"text": "这件事的重要性很重，我们要认真对待。", "explanation": "这里应该用〈大〉。“重”说分量，用于有重量的东西；“重要性”说程度，不能说“很重”。"}, {"text": "这件事的重要性很贵，我们要认真对待。", "explanation": "这里应该用〈大〉。“贵”说价钱，不能用来形容“重要性”；“重要性”说程度，应说“很大”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'deebcdfc-2623-4b3b-a262-1127910088b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12469, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "重要性", "is_correct": true, "explanation": "正确：“节约用水的重要性”说的是它的价值，符合句意。"}, {"text": "形状", "is_correct": false, "explanation": "语义：“形状”指外形，与“节约用水”的价值无关。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：“年龄”指岁数，不能说“节约用水的年龄”。"}, {"text": "速度", "is_correct": false, "explanation": "语义：“速度”说快慢，不指节约用水的价值或意义，句子要的是表示价值的词。"}], "explanations": {"重要性": "正确：“节约用水的重要性”说的是它的价值，符合句意。", "形状": "语义：“形状”指外形，与“节约用水”的价值无关。", "年龄": "语义：“年龄”指岁数，不能说“节约用水的年龄”。", "速度": "语义：“速度”说快慢，不指节约用水的价值或意义，句子要的是表示价值的词。"}, "sentence_index": 6, "correct_answer": "重要性"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我的哥哥是公司的重要性。", "explanation": "这里不能指人。〈重要性〉是抽象的程度，不能用“是”把人说成它。"}, {"text": "那只猫是我们家的重要性。", "explanation": "这里不能指动物。〈重要性〉是抽象的程度，不能用来指一只猫。"}, {"text": "这所学校是城里的重要性。", "explanation": "这里不能指机构。〈重要性〉是抽象的程度，不能指具体的学校。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'deebcdfc-2623-4b3b-a262-1127910088b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12469, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "大家要认识到节约能源重要性。", "corrected_sentence": "大家要认识到节约能源的重要性。", "error_description": "结构助词错误：修饰语“节约能源”与“重要性”之间要用“的”，应说“节约能源的重要性”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'deebcdfc-2623-4b3b-a262-1127910088b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12469, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他终于明白了诚实的很重要性。", "corrected_sentence": "他终于明白了诚实的重要性。", "error_description": "程度副词位置错误：“重要性”是名词，前面不能直接加“很”；“很”只修饰形容词“重要”，应说“诚实的重要性”，不能说“诚实的很重要性”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'deebcdfc-2623-4b3b-a262-1127910088b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
