INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12470, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "用纸板制成的箱子，常用于包装或存放物品。", "primary_collocate": null, "pronunciation": "zhǐ xiāng", "ipa": "ʈʂɨ˨˩˦ ɕjɑŋ˥", "syllable_count": 2, "sentences": [{"text": "今天，我们在纸箱、塑料瓶、金属罐上都能看到这个标志。", "target_word": "纸箱", "complexity_tier": "T4", "sentence_source": "mined"}, {"text": "在桶里先放一层干的材料，比如落叶或撕碎的纸箱，这样可以防止味道太大。", "target_word": "纸箱", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "我把旧书放进了纸箱里。", "target_word": "纸箱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "搬家时，我们买了几个大纸箱。", "target_word": "纸箱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个纸箱太重了，我一个人搬不动。", "target_word": "纸箱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "快递员把一个纸箱放在门口。", "target_word": "纸箱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小猫喜欢躺在空纸箱里睡觉。", "target_word": "纸箱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "纸箱湿了以后很容易坏。", "target_word": "纸箱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用纸箱给孩子做了一辆小汽车。", "target_word": "纸箱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把用完的这个纸箱放到楼下的回收站。", "target_word": "纸箱", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "纸箱子", "label": "复合"}, {"form": "紙箱", "label": "繁体"}], "register": "中性", "sense_fingerprint": "纸板做的箱子，用来包装、存放东西", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e653b9f-1786-4a98-96fa-5c2fd7ba68c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12470, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "纸箱", "is_correct": true, "explanation": "正确：“纸箱”是可以印上标志的包装物，与“纸箱、塑料瓶、金属罐”相合。"}, {"text": "歌曲", "is_correct": false, "explanation": "语义：“歌曲”不是实物，不能在上面看到标志。"}, {"text": "小猫", "is_correct": false, "explanation": "语义：“小猫”不是包装容器，不会印有回收标志。"}, {"text": "想法", "is_correct": false, "explanation": "语义：“想法”是抽象的，不是实物，上面不能看到标志。"}], "explanations": {"纸箱": "正确：“纸箱”是可以印上标志的包装物，与“纸箱、塑料瓶、金属罐”相合。", "歌曲": "语义：“歌曲”不是实物，不能在上面看到标志。", "小猫": "语义：“小猫”不是包装容器，不会印有回收标志。", "想法": "语义：“想法”是抽象的，不是实物，上面不能看到标志。"}, "sentence_index": 0, "correct_answer": "纸箱"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "搬家时，我们买了几条大纸箱。", "explanation": "这里应该用〈个〉。“条”用于细长的物件，纸箱是立体的箱子，不用“条”计量。"}, {"text": "搬家时，我们买了几本大纸箱。", "explanation": "这里应该用〈个〉。“本”用于书籍、本子，纸箱不用“本”计量。"}, {"text": "搬家时，我们买了几台大纸箱。", "explanation": "这里应该用〈个〉。“台”用于机器、设备，纸箱不属于这一类。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f11dc1a6-578c-4e2c-94f2-1e7d320bd4a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12470, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "纸箱", "is_correct": true, "explanation": "正确：“纸箱”是能让小猫躺进去的空间，与“空”“躺在…里”相合。"}, {"text": "桌子", "is_correct": false, "explanation": "搭配：“躺在…里”要求能容纳身体的空间，“空桌子”不说“躺在里面”。"}, {"text": "水杯", "is_correct": false, "explanation": "语义：水杯太小，小猫无法躺在里面睡觉。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头是实心的，不能作为可以躺进去的空间。"}], "explanations": {"纸箱": "正确：“纸箱”是能让小猫躺进去的空间，与“空”“躺在…里”相合。", "桌子": "搭配：“躺在…里”要求能容纳身体的空间，“空桌子”不说“躺在里面”。", "水杯": "语义：水杯太小，小猫无法躺在里面睡觉。", "石头": "语义：石头是实心的，不能作为可以躺进去的空间。"}, "sentence_index": 6, "correct_answer": "纸箱"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "请把用完的一支纸箱放到楼下的回收站。", "explanation": "这里应该用〈个〉。“支”用于细长的棍状物，纸箱不用“支”计量。"}, {"text": "请把用完的一座纸箱放到楼下的回收站。", "explanation": "这里应该用〈个〉。“座”用于山、桥、建筑等大型固定物，纸箱不用“座”。"}, {"text": "请把用完的一颗纸箱放到楼下的回收站。", "explanation": "这里应该用〈个〉。“颗”用于小而圆的东西，纸箱不用“颗”计量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f11dc1a6-578c-4e2c-94f2-1e7d320bd4a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12470, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我家有一本纸箱。", "corrected_sentence": "我家有一个纸箱。", "error_description": "“本”用于书籍，纸箱的量词应为“个”，应说“一个纸箱”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f11dc1a6-578c-4e2c-94f2-1e7d320bd4a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12470, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他把旧纸箱扁压了。", "corrected_sentence": "他把旧纸箱压扁了。", "error_description": "结果补语“扁”应紧跟在动词“压”后面，说“压扁了”，不能说“扁压了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f11dc1a6-578c-4e2c-94f2-1e7d320bd4a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
