INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12471, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "金属罐指用金属材料制成的容器，通常用于密封保存液体或固体物品。", "primary_collocate": null, "pronunciation": "jīn shǔ guàn", "ipa": "tɕin˥˥ ʂu˨˩˦ kuan˥˩", "syllable_count": 3, "sentences": [{"text": "今天，我们在纸箱、塑料瓶、金属罐上都能看到这个标志。", "target_word": "金属罐", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "这个金属罐里装着饼干。", "target_word": "金属罐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把空金属罐放进回收箱。", "target_word": "金属罐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "金属罐很结实，不容易坏。", "target_word": "金属罐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用金属罐做了一个笔筒。", "target_word": "金属罐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "超市里有各种各样的金属罐。", "target_word": "金属罐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我打开金属罐，闻到了茶的香味。", "target_word": "金属罐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个旧金属罐是奶奶用过的。", "target_word": "金属罐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "金属罐放在太阳下会很热。", "target_word": "金属罐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们在河边捡到了一个金属罐。", "target_word": "金属罐", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "金屬罐", "label": "繁体"}], "register": "通用", "sense_fingerprint": "金属制成、可密封的容器，用来保存液体或固体物品", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6a1fb72f-7f26-46aa-b253-c34484e0d5e4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12471, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "金属罐", "is_correct": true, "explanation": "正确：金属罐是可回收的金属包装，与纸箱、塑料瓶并列，语义通顺。"}, {"text": "钢琴", "is_correct": false, "explanation": "语义：钢琴是乐器，不是包装容器，不能与纸箱、塑料瓶并列，也不会印有回收标志。"}, {"text": "树叶", "is_correct": false, "explanation": "语义：树叶是自然物，不是包装物，与前面的纸箱、塑料瓶不属于同一类。"}, {"text": "窗帘", "is_correct": false, "explanation": "搭配：回收标志印在包装物上，窗帘不是包装，和纸箱、塑料瓶并列不搭。"}], "explanations": {"金属罐": "正确：金属罐是可回收的金属包装，与纸箱、塑料瓶并列，语义通顺。", "钢琴": "语义：钢琴是乐器，不是包装容器，不能与纸箱、塑料瓶并列，也不会印有回收标志。", "树叶": "语义：树叶是自然物，不是包装物，与前面的纸箱、塑料瓶不属于同一类。", "窗帘": "搭配：回收标志印在包装物上，窗帘不是包装，和纸箱、塑料瓶并列不搭。"}, "sentence_index": 0, "correct_answer": "金属罐"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我透过金属罐看到了里面的糖。", "explanation": "这里应该用〈玻璃罐〉。玻璃罐透明，才能透过它看见里面的东西；金属罐不透明，看不见里面的糖。"}, {"text": "水从金属罐里一直流过去。", "explanation": "这里应该用〈金属管〉。金属管两端相通，水能从中流过；金属罐是封闭的容器，水不能从里面穿过。"}, {"text": "他推开金属罐，走进了房间。", "explanation": "这里应该用〈门〉。门可以推开通行；金属罐是用来密封保存物品的容器，不能推开走进。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '69f4ea35-59be-4a4b-a754-c6218d71bbb6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12471, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "金属罐", "is_correct": true, "explanation": "正确：打开的是装有茶叶、能散发香气的金属罐，所以能闻到茶香。"}, {"text": "手机", "is_correct": false, "explanation": "语义：手机不会散发茶香，与“闻到了茶的香味”冲突。"}, {"text": "字典", "is_correct": false, "explanation": "语义：字典是书，打开后不会散发茶香，与后半句不符。"}, {"text": "电视", "is_correct": false, "explanation": "搭配：“打开”后面要接能装东西、能散发气味的器具，电视不能与“闻到茶香”搭配。"}], "explanations": {"金属罐": "正确：打开的是装有茶叶、能散发香气的金属罐，所以能闻到茶香。", "手机": "语义：手机不会散发茶香，与“闻到了茶的香味”冲突。", "字典": "语义：字典是书，打开后不会散发茶香，与后半句不符。", "电视": "搭配：“打开”后面要接能装东西、能散发气味的器具，电视不能与“闻到茶香”搭配。"}, "sentence_index": 6, "correct_answer": "金属罐"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个金属罐可以让光慢慢照进屋子里。", "explanation": "这里应该用〈窗户〉。窗户透光，光能从中照进屋里；金属罐不透光，光照不进来。"}, {"text": "金属罐把炉子里的烟排到了屋外。", "explanation": "这里应该用〈烟囱〉。烟囱专门排出烟气；金属罐不起排烟的作用。"}, {"text": "他用金属罐当电话，打给朋友。", "explanation": "这里应该用〈手机〉。手机可以打电话；金属罐是盛装物品的容器，不能用来通话。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '69f4ea35-59be-4a4b-a754-c6218d71bbb6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12471, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妈妈把饼干装进了一张金属罐里。", "corrected_sentence": "妈妈把饼干装进了一个金属罐里。", "error_description": "量词错误：“金属罐”应用量词“个”，“张”用于纸张、桌子等扁平物，不能用来计量罐子。正确说法是“一个金属罐”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '69f4ea35-59be-4a4b-a754-c6218d71bbb6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12471, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "爸爸在厨房里找到了一本旧金属罐。", "corrected_sentence": "爸爸在厨房里找到了一个旧金属罐。", "error_description": "量词错误：“金属罐”应该用量词“个”。“本”用于书本等装订成册的东西，不能用来计量罐子。正确说法是“一个旧金属罐”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '69f4ea35-59be-4a4b-a754-c6218d71bbb6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
