INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12484, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "心里急切地希望得到或达到某个目标。", "primary_collocate": null, "pronunciation": "kě wàng", "ipa": "kʰɤ˨˩˦ wɑŋ˥˩", "syllable_count": 2, "sentences": [{"text": "孩子们渴望早点放假。", "target_word": "渴望", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从小就渴望成为一名医生。", "target_word": "渴望", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "长期住在山里的人渴望看看大城市。", "target_word": "渴望", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她渴望得到父母的理解。", "target_word": "渴望", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们渴望和平，不想再打仗。", "target_word": "渴望", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "沙漠里的人渴望下雨。", "target_word": "渴望", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我一直渴望着去海边生活。", "target_word": "渴望", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小时候，他渴望过当一名飞行员。", "target_word": "渴望", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师的一句夸奖，是每个学生都渴望的。", "target_word": "渴望", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她渴望有一个属于自己的房间。", "target_word": "渴望", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "渴望着", "label": "体标"}, {"form": "渴望过", "label": "体标"}], "register": "中性", "sense_fingerprint": "心里急切希望得到或达到某个目标", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c5d266d-7f63-4cac-bf36-2351f9160e06') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12484, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "修理", "is_correct": false, "explanation": "语义：“修理”指把坏了的东西修好，不能接“早点放假”作宾语。"}, {"text": "擦", "is_correct": false, "explanation": "搭配：“擦”的宾语是污渍或表面，不能接“早点放假”。"}, {"text": "煮", "is_correct": false, "explanation": "搭配：“煮”的宾语应是食物，“早点放假”不能被煮。"}, {"text": "渴望", "is_correct": true, "explanation": "正确：渴望指心里急切地希望得到或达到某个目标，这里说孩子们急切盼望早点放假。"}], "explanations": {"修理": "语义：“修理”指把坏了的东西修好，不能接“早点放假”作宾语。", "擦": "搭配：“擦”的宾语是污渍或表面，不能接“早点放假”。", "煮": "搭配：“煮”的宾语应是食物，“早点放假”不能被煮。", "渴望": "正确：渴望指心里急切地希望得到或达到某个目标，这里说孩子们急切盼望早点放假。"}, "sentence_index": 0, "correct_answer": "渴望"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "走了一下午的路，我渴望极了，赶紧找水喝。", "explanation": "这里应该用〈渴〉。渴望指心里急切地想得到某个目标，身体缺水要说〈渴〉。"}, {"text": "他很渴望黑夜，却一直怕黑，总是开着灯。", "explanation": "这里应该用〈害怕〉。渴望表示想得到，与“怕黑、总是开着灯”的意思相反，这里应说〈害怕〉。"}, {"text": "我渴望吃青菜，每次都得硬逼自己吃。", "explanation": "这里应该用〈讨厌〉。渴望表示急切想得到，与“硬逼自己吃”的语境相反，这里要说〈讨厌〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a0a4231-0e50-42c7-9177-91d0248c52a9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12484, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "洗", "is_correct": false, "explanation": "搭配：“洗”的宾语是衣物或身体，不能接“去海边生活”。"}, {"text": "扫", "is_correct": false, "explanation": "语义：“扫”是清除灰尘，与“去海边生活”的意思毫无关系。"}, {"text": "修补", "is_correct": false, "explanation": "语义：“修补”指修复破损的东西，不能用来指人去海边生活。"}, {"text": "渴望", "is_correct": true, "explanation": "正确：渴望表示心里急切地想得到或达到某个目标，这里说一直想去海边生活。"}], "explanations": {"洗": "搭配：“洗”的宾语是衣物或身体，不能接“去海边生活”。", "扫": "语义：“扫”是清除灰尘，与“去海边生活”的意思毫无关系。", "修补": "语义：“修补”指修复破损的东西，不能用来指人去海边生活。", "渴望": "正确：渴望表示心里急切地想得到或达到某个目标，这里说一直想去海边生活。"}, "sentence_index": 6, "correct_answer": "渴望"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他对高处感到渴望，从来不敢爬楼。", "explanation": "这里应该用〈恐惧〉。渴望表示急切想得到，对高处的畏惧要说〈恐惧〉。"}, {"text": "他很渴望当初没有好好学习。", "explanation": "这里应该用〈后悔〉。渴望表示想得到某个目标，对过去的失误要说〈后悔〉。"}, {"text": "他总是渴望困难，从不愿意面对。", "explanation": "这里应该用〈逃避〉。渴望是主动追求，躲避困难要说〈逃避〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a0a4231-0e50-42c7-9177-91d0248c52a9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12484, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我渴望了早日见到家人。", "corrected_sentence": "我渴望着早日见到家人。", "error_description": "体标错误：“渴望”表示尚未实现的心愿，后面不能直接加“了”表示完成；应当用“着”表示持续的心愿。正确说法：我渴望着早日见到家人。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a0a4231-0e50-42c7-9177-91d0248c52a9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12484, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他渴望得有一台新电脑。", "corrected_sentence": "他渴望有一台新电脑。", "error_description": "助词错误：“渴望”后面多加了“得”，应直接接“有”。正确说法：他渴望有一台新电脑。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a0a4231-0e50-42c7-9177-91d0248c52a9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
