INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12485, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指事物发生的源头或开始。", "primary_collocate": null, "pronunciation": "qǐ yuán", "ipa": "tɕʰi˨˩˦ ɥɛn˧˥", "syllable_count": 2, "sentences": [{"text": "这一设计的起源可追溯至1970年美国首届“地球日”活动，当时包装行业亟需一种公众易于识别的标识，以区分可回收材料与普通垃圾。", "target_word": "起源", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这个节日的起源可以追溯到两千年前。", "target_word": "起源", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "人们一直在研究生命的起源。", "target_word": "起源", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师给我们讲了汉字的起源。", "target_word": "起源", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "篮球运动的起源是什么？", "target_word": "起源", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书里写了春节的起源和有趣的故事。", "target_word": "起源", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "关于这个词的起源，大家有不同的看法。", "target_word": "起源", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "科学家想知道地球上水的起源。", "target_word": "起源", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "茶的起源在中国，很多人都知道。", "target_word": "起源", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我对这种音乐的起源很感兴趣。", "target_word": "起源", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "事物发生的源头或开始", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c5d266d-7f63-4cac-bf36-2351f9160e06') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12485, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "起源", "is_correct": true, "explanation": "起源（qǐ yuán）指事物发生的源头，是本题的正确答案。"}, {"text": "奇缘", "is_correct": false, "explanation": "qí（第二声）与 qǐ（第三声）声调不同，意思是奇妙的缘分，与起源不同。"}, {"text": "祈愿", "is_correct": false, "explanation": "祈愿（qíyuàn）的两个音节声调都与起源不同，意思是祈祷和希望。"}, {"text": "气源", "is_correct": false, "explanation": "qì（第四声）与 qǐ（第三声）声调不同，意思是气体的来源。"}], "explanations": {"起源": "起源（qǐ yuán）指事物发生的源头，是本题的正确答案。", "奇缘": "qí（第二声）与 qǐ（第三声）声调不同，意思是奇妙的缘分，与起源不同。", "祈愿": "祈愿（qíyuàn）的两个音节声调都与起源不同，意思是祈祷和希望。", "气源": "qì（第四声）与 qǐ（第三声）声调不同，意思是气体的来源。"}, "sentence_index": null, "correct_answer": "起源"}, "level_3": {"options": [{"text": "起源", "is_correct": true, "explanation": "起源指事物最初的来源，能与“可追溯至”搭配，填入此处正确。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：“颜色”不能被“追溯至”某个时间和某次活动，这里需要表示事物源头的词。"}, {"text": "价格", "is_correct": false, "explanation": "语义：“价格”不能追溯到某次活动，这里需要表示事物源头的词。"}, {"text": "尺寸", "is_correct": false, "explanation": "搭配：“追溯至”常与“起源”“历史”搭配，不能说“尺寸可追溯至”。"}], "explanations": {"起源": "起源指事物最初的来源，能与“可追溯至”搭配，填入此处正确。", "颜色": "语义：“颜色”不能被“追溯至”某个时间和某次活动，这里需要表示事物源头的词。", "价格": "语义：“价格”不能追溯到某次活动，这里需要表示事物源头的词。", "尺寸": "搭配：“追溯至”常与“起源”“历史”搭配，不能说“尺寸可追溯至”。"}, "sentence_index": 0, "correct_answer": "起源"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这次旅行是我一生中最难忘的起源。", "explanation": "这里应该用〈经历〉。“起源”指事物最初的来源，不指自己亲身遭遇的事，“最难忘的”应搭配“经历”。"}, {"text": "我在这个岗位积累了丰富的起源。", "explanation": "这里应该用〈经验〉。“积累”的对象是经验或知识，“起源”是事物的源头，不能被积累。"}, {"text": "我的努力终于得到了好的起源。", "explanation": "这里应该用〈结果〉。“得到”搭配的是结果或成绩，“起源”指事物的源头或开始，不能被得到。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a0a4231-0e50-42c7-9177-91d0248c52a9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12485, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "起源", "is_correct": true, "explanation": "起源指事物的源头，与“关于这个词的”搭配，表示词的来历，填入此处正确。"}, {"text": "身高", "is_correct": false, "explanation": "体貌：“身高”只用于人或动物，不能说“这个词的身高”。"}, {"text": "学历", "is_correct": false, "explanation": "配价：“学历”需要有人作为持有者，不能用于“这个词”。"}, {"text": "性格", "is_correct": false, "explanation": "语义：“性格”指人或动物的个性，不能用来说词的特点，句子不通。"}], "explanations": {"起源": "起源指事物的源头，与“关于这个词的”搭配，表示词的来历，填入此处正确。", "身高": "体貌：“身高”只用于人或动物，不能说“这个词的身高”。", "学历": "配价：“学历”需要有人作为持有者，不能用于“这个词”。", "性格": "语义：“性格”指人或动物的个性，不能用来说词的特点，句子不通。"}, "sentence_index": 6, "correct_answer": "起源"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他每月的起源都不一样。", "explanation": "这里应该用〈收入〉。“每月”和“不一样”描述的是收入，“起源”指事物的源头，不能按月计算。"}, {"text": "这件大衣的起源很便宜。", "explanation": "这里应该用〈价格〉。“便宜”描述价格，“起源”指事物的源头，不能说便宜。"}, {"text": "这台冰箱的起源很高。", "explanation": "这里应该用〈高度〉。“很高”说的是物体的高矮，“起源”指事物的源头或开始，不能用来说高矮。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a0a4231-0e50-42c7-9177-91d0248c52a9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12485, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这首歌有一条很神秘的起源。", "corrected_sentence": "这首歌有一个很神秘的起源。", "error_description": "量词错误：“起源”是抽象名词，不能用“条”（“条”多用于细长的东西），应该用“个”。正确说法：这首歌有一个很神秘的起源。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a0a4231-0e50-42c7-9177-91d0248c52a9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12485, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个节日有一只古老的起源。", "corrected_sentence": "这个节日有一个古老的起源。", "error_description": "量词错误：“起源”是抽象名词，不能用“只”（“只”多用于动物），应该用“个”。正确说法：这个节日有一个古老的起源。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a0a4231-0e50-42c7-9177-91d0248c52a9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
