INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12486, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "指能够追溯到某个时间、来源或原因的。", "primary_collocate": null, "pronunciation": "kě zhuī sù", "ipa": "kʰɤ˨˩ ʈʂueɪ˥ su˥˩", "syllable_count": 3, "sentences": [{"text": "这一设计的起源可追溯至1970年美国首届“地球日”活动，当时包装行业亟需一种公众易于识别的标识，以区分可回收材料与普通垃圾。", "target_word": "可追溯", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "首先，推动供应链透明化，建立可追溯的生产信息平台，使每一件纺织品的水足迹与污染排放数据可查可验，是实现问责制的基础。", "target_word": "可追溯", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这些牛奶的来源可追溯到农场。", "target_word": "可追溯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每个苹果都有标签，来源可追溯。", "target_word": "可追溯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店的肉都是可追溯的产品。", "target_word": "可追溯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个习惯可追溯到很多年前。", "target_word": "可追溯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件瓷器的来历可追溯到明朝。", "target_word": "可追溯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座老桥的历史可追溯到二百年前。", "target_word": "可追溯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "食品出了问题，可追溯的记录能帮我们找到原因。", "target_word": "可追溯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次事故的原因可追溯到去年的一个错误。", "target_word": "可追溯", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "不可追溯", "label": "否定形式"}], "register": "书面语", "sense_fingerprint": "能查到时间、来源或原因", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bf9d64f7-d6db-410b-8410-52799dc0c108') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12486, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "可追溯", "is_correct": true, "explanation": "正确：可追溯指能够追溯到某个时间、来源或原因，与句中“起源……至1970年”相符。"}, {"text": "可靠", "is_correct": false, "explanation": "搭配：可靠形容人或信息值得信赖，不能与“起源”及“追溯至”搭配。"}, {"text": "可疑", "is_correct": false, "explanation": "语义：可疑表示令人怀疑，与句中明确追溯到1970年的叙述相冲突。"}, {"text": "可信", "is_correct": false, "explanation": "搭配：可信用于说法或人，不用来描述设计的起源。"}], "explanations": {"可追溯": "正确：可追溯指能够追溯到某个时间、来源或原因，与句中“起源……至1970年”相符。", "可靠": "搭配：可靠形容人或信息值得信赖，不能与“起源”及“追溯至”搭配。", "可疑": "语义：可疑表示令人怀疑，与句中明确追溯到1970年的叙述相冲突。", "可信": "搭配：可信用于说法或人，不用来描述设计的起源。"}, "sentence_index": 0, "correct_answer": "可追溯"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "明天的天气可追溯。", "explanation": "这里应该用〈可预测〉。可追溯指往回能找到来源或原因，不能用于还没发生的事。"}, {"text": "远处的灯塔可追溯。", "explanation": "这里应该用〈可见〉。可追溯指能查到来源，不指肉眼能看见的事物。"}, {"text": "这个西瓜很甜，可追溯。", "explanation": "这里应该用〈好吃〉。可追溯指能查到来源或原因，不用来评价口感。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '99a869e5-d7c6-4cee-bf7b-58b3f659b231') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12486, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "可追溯", "is_correct": true, "explanation": "正确：可追溯指能追溯到某个时间或来源，与“来历……到明朝”相符。"}, {"text": "可爱", "is_correct": false, "explanation": "语义：可爱表示令人喜爱，与句中讲述瓷器来历的内容无关。"}, {"text": "可贵", "is_correct": false, "explanation": "搭配：可贵多形容精神、品质，不说来历。"}, {"text": "可怕", "is_correct": false, "explanation": "语义：可怕表示令人害怕，与句中叙述的历史来源不相容。"}], "explanations": {"可追溯": "正确：可追溯指能追溯到某个时间或来源，与“来历……到明朝”相符。", "可爱": "语义：可爱表示令人喜爱，与句中讲述瓷器来历的内容无关。", "可贵": "搭配：可贵多形容精神、品质，不说来历。", "可怕": "语义：可怕表示令人害怕，与句中叙述的历史来源不相容。"}, "sentence_index": 6, "correct_answer": "可追溯"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "明年的收成可追溯。", "explanation": "这里应该用〈可预计〉。可追溯指往回找到来源，不能用于还没到来的收成。"}, {"text": "他的笑声可追溯。", "explanation": "这里应该用〈可听见〉。可追溯指能查到来源或原因，不指声音能否被听见。"}, {"text": "春风吹过我的脸，可追溯。", "explanation": "这里应该用〈可感觉〉。可追溯指能查到来源或原因，不指微风能否被人感觉到。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '99a869e5-d7c6-4cee-bf7b-58b3f659b231') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12486, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这批药材的来源可追溯在云南。", "corrected_sentence": "这批药材的来源可追溯到云南。", "error_description": "错误：引出来源地点时应用“到”，“在”不能接在“可追溯”后。正确形式为“可追溯到云南”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '99a869e5-d7c6-4cee-bf7b-58b3f659b231') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12486, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这些蔬菜的产地可追溯了到山东。", "corrected_sentence": "这些蔬菜的产地可追溯到山东。", "error_description": "错误：“可追溯”后不能加“了”，“了”放在这里不符合语法。正确形式为“可追溯到山东”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '99a869e5-d7c6-4cee-bf7b-58b3f659b231') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
