INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12488, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指社会系统中具有相同性质或功能的各种职业、领域的总称。", "primary_collocate": null, "pronunciation": "háng yè", "ipa": "xɑŋ˧˥ jɛ˥˩", "syllable_count": 2, "sentences": [{"text": "现在互联网行业发展得很快。", "target_word": "行业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在教育行业工作了十年。", "target_word": "行业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个行业需要很多年轻人。", "target_word": "行业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你想进哪个行业工作？", "target_word": "行业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "金融是一个很重要的行业。", "target_word": "行业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "不同行业的工资差别很大。", "target_word": "行业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她换了行业，现在做设计。", "target_word": "行业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "旅游行业今年又好起来了。", "target_word": "行业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个行业的竞争非常激烈。", "target_word": "行业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医疗行业对人才要求很高。", "target_word": "行业", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "行业标准", "label": "复合"}, {"form": "行業", "label": "繁体"}], "register": "中性", "sense_fingerprint": "社会中性质相同的职业或领域的总称", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c5d266d-7f63-4cac-bf36-2351f9160e06') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12488, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "寒夜", "is_correct": false, "explanation": "hán（第二声）与 háng 的韵尾不同（n 与 ng），意思是寒冷的夜晚。"}, {"text": "行业", "is_correct": true, "explanation": "háng yè 是“行业”，指社会中同类职业或领域的总称。"}, {"text": "糖业", "is_correct": false, "explanation": "táng 与 háng 的声母不同（t 与 h），意思是制糖的行业。"}, {"text": "黄叶", "is_correct": false, "explanation": "huáng 比 háng 多一个介音 u，意思是黄色的树叶。"}], "explanations": {"寒夜": "hán（第二声）与 háng 的韵尾不同（n 与 ng），意思是寒冷的夜晚。", "行业": "háng yè 是“行业”，指社会中同类职业或领域的总称。", "糖业": "táng 与 háng 的声母不同（t 与 h），意思是制糖的行业。", "黄叶": "huáng 比 háng 多一个介音 u，意思是黄色的树叶。"}, "sentence_index": null, "correct_answer": "行业"}, "level_3": {"options": [{"text": "公园", "is_correct": false, "explanation": "语义：公园是供人游玩的场所，不是可以“发展得很快”的领域。"}, {"text": "行业", "is_correct": true, "explanation": "行业：指同类职业或领域，“互联网行业”指互联网这一领域，可以“发展得很快”。"}, {"text": "感冒", "is_correct": false, "explanation": "语义：感冒是一种疾病，不是领域，不能作为“发展得很快”的主语。"}, {"text": "眼睛", "is_correct": false, "explanation": "搭配：“互联网”不能修饰“眼睛”，这个句子说的不是身体器官。"}], "explanations": {"公园": "语义：公园是供人游玩的场所，不是可以“发展得很快”的领域。", "行业": "行业：指同类职业或领域，“互联网行业”指互联网这一领域，可以“发展得很快”。", "感冒": "语义：感冒是一种疾病，不是领域，不能作为“发展得很快”的主语。", "眼睛": "搭配：“互联网”不能修饰“眼睛”，这个句子说的不是身体器官。"}, "sentence_index": 0, "correct_answer": "行业"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的行业是医生。", "explanation": "这里应该用〈职业〉。行业指一类职业的总称，说某人具体的工作要用职业。"}, {"text": "她在语言学行业做研究。", "explanation": "这里应该用〈领域〉。学术研究的范围说领域，行业指职业所属的行当。"}, {"text": "他在公司担任一个重要的行业。", "explanation": "这里应该用〈岗位〉。岗位指具体的职位，行业指一类职业的总称，不能说“担任一个行业”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a0a4231-0e50-42c7-9177-91d0248c52a9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12488, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "天气", "is_correct": false, "explanation": "搭配：“换”不能跟“天气”搭配，“换了天气”不通。"}, {"text": "行业", "is_correct": true, "explanation": "行业：“换了行业”指换了工作领域，与后句“现在做设计”的语境相符。"}, {"text": "病毒", "is_correct": false, "explanation": "语义：病毒是一种微生物，不是工作领域，“换了病毒”与“做设计”毫不相干。"}, {"text": "节日", "is_correct": false, "explanation": "语义：节日是日子，不是可以更换的工作领域，与“做设计”不相符。"}], "explanations": {"天气": "搭配：“换”不能跟“天气”搭配，“换了天气”不通。", "行业": "行业：“换了行业”指换了工作领域，与后句“现在做设计”的语境相符。", "病毒": "语义：病毒是一种微生物，不是工作领域，“换了病毒”与“做设计”毫不相干。", "节日": "语义：节日是日子，不是可以更换的工作领域，与“做设计”不相符。"}, "sentence_index": 6, "correct_answer": "行业"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他大学学的是计算机行业。", "explanation": "这里应该用〈专业〉。学习的方向说专业，行业指就业的领域。"}, {"text": "数学是一个很重要的行业。", "explanation": "这里应该用〈学科〉。数学是学科，不是职业的领域。"}, {"text": "我们公司的行业卖得很好。", "explanation": "这里应该用〈产品〉。产品可以卖，行业指职业或领域的总称，不能说“行业卖得很好”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a0a4231-0e50-42c7-9177-91d0248c52a9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12488, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我父亲在这条行业干了二十年。", "corrected_sentence": "我父亲在这个行业干了二十年。", "error_description": "量词错误：“条”用于细长的东西，不能用来数行业；应说“这个行业”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a0a4231-0e50-42c7-9177-91d0248c52a9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12488, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这些行业们都在快速发展。", "corrected_sentence": "这些行业都在快速发展。", "error_description": "“们”只用于指人的名词，“行业”不能加“们”；应说“这些行业”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a0a4231-0e50-42c7-9177-91d0248c52a9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
