INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12492, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "用来识别、区分的标记或符号。", "primary_collocate": null, "pronunciation": "biāo shí", "ipa": "piɑʊ˥ ʂʅ˧˥", "syllable_count": 2, "sentences": [{"text": "这一设计的起源可追溯至1970年美国首届“地球日”活动，当时包装行业亟需一种公众易于识别的标识，以区分可回收材料与普通垃圾。", "target_word": "标识", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "门上有一个红色的标识。", "target_word": "标识", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "每个公司都有自己的标识。", "target_word": "标识", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "请看清地上的安全标识。", "target_word": "标识", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这个标识告诉我们这里不能停车。", "target_word": "标识", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这些瓶子上都贴着标识，不会弄错。", "target_word": "标识", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "药盒上的标识很清楚。", "target_word": "标识", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "路边的标识提醒司机慢行。", "target_word": "标识", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "商店把新的标识挂在门口。", "target_word": "标识", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个标识的颜色是绿色的，代表安全。", "target_word": "标识", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "种", "label": "量词"}, {"form": "標識", "label": "繁体"}], "register": "中性", "sense_fingerprint": "名词：用来识别、区分的标记或符号", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '98e0b363-6408-4edb-93ac-1d50e90a7dc1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12492, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "标识", "is_correct": true, "explanation": "正确答案。标识（biāo shí）指用来识别、区分的标记。"}, {"text": "表示", "is_correct": false, "explanation": "biǎo（第三声）与 biāo（第一声）声调不同，shì（第四声）与 shí（第二声）声调也不同，意思是“表明”。"}, {"text": "镖师", "is_correct": false, "explanation": "第二个音节 shī 与 shí 声调不同，意思是“护送财物的人”。"}, {"text": "漂石", "is_correct": false, "explanation": "piāo 与 biāo 声母不同，意思是“浮在水上的石头”。"}], "explanations": {"标识": "正确答案。标识（biāo shí）指用来识别、区分的标记。", "表示": "biǎo（第三声）与 biāo（第一声）声调不同，shì（第四声）与 shí（第二声）声调也不同，意思是“表明”。", "镖师": "第二个音节 shī 与 shí 声调不同，意思是“护送财物的人”。", "漂石": "piāo 与 biāo 声母不同，意思是“浮在水上的石头”。"}, "sentence_index": null, "correct_answer": "标识"}, "level_3": {"options": [{"text": "标识", "is_correct": true, "explanation": "正确答案。“公众易于识别的标识”指便于辨认的记号，与后句“以区分”相合。"}, {"text": "标点", "is_correct": false, "explanation": "语义：标点是书写符号，不能用来区分可回收材料，与语境不合。"}, {"text": "标题", "is_correct": false, "explanation": "语义：标题是文章或节目的名称，不能用来区分可回收材料。"}, {"text": "标尺", "is_correct": false, "explanation": "语义：标尺是测量长度的工具，不能与“公众易于识别”搭配。"}], "explanations": {"标识": "正确答案。“公众易于识别的标识”指便于辨认的记号，与后句“以区分”相合。", "标点": "语义：标点是书写符号，不能用来区分可回收材料，与语境不合。", "标题": "语义：标题是文章或节目的名称，不能用来区分可回收材料。", "标尺": "语义：标尺是测量长度的工具，不能与“公众易于识别”搭配。"}, "sentence_index": 0, "correct_answer": "标识"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他拿出一本标识，要求进入大楼。", "explanation": "这里应该用〈证件〉。标识是记号，不能当作可以拿出的身份凭证，进门应当出示证件。"}, {"text": "我们要用标识证明自己的年龄。", "explanation": "这里应该用〈证件〉。标识是记号，不能用来证明年龄，应当说证件。"}, {"text": "老师今天标识了我的作文，给了高分。", "explanation": "这里应该用〈批改〉。标识指记号或符号，不能用来指老师给作文打分。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04b0d076-3bc8-4549-b757-b08aa083512e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12492, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "标识", "is_correct": true, "explanation": "正确答案。“药盒上的标识很清楚”指药盒上的标记清楚，符合语境。"}, {"text": "声音", "is_correct": false, "explanation": "语义：声音不能出现在药盒上，“药盒上的声音”与语境不合。"}, {"text": "云朵", "is_correct": false, "explanation": "语义：云朵不会贴在药盒上，与语境不合。"}, {"text": "海浪", "is_correct": false, "explanation": "语义：海浪不会出现在药盒上，与语境不合。"}], "explanations": {"标识": "正确答案。“药盒上的标识很清楚”指药盒上的标记清楚，符合语境。", "声音": "语义：声音不能出现在药盒上，“药盒上的声音”与语境不合。", "云朵": "语义：云朵不会贴在药盒上，与语境不合。", "海浪": "语义：海浪不会出现在药盒上，与语境不合。"}, "sentence_index": 6, "correct_answer": "标识"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这台机器的标识很高，所以质量很好。", "explanation": "这里应该用〈标准〉。标识指记号，不能用来说机器的水平高低，应说标准。"}, {"text": "他把标识写成了一首诗，念给大家听。", "explanation": "这里应该用〈作品〉。标识指记号，不能当作诗歌这类作品。"}, {"text": "这次比赛的标识很高，大家都很失望。", "explanation": "这里应该用〈分数〉。标识指记号，不能用来说比赛成绩的高低。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04b0d076-3bc8-4549-b757-b08aa083512e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12492, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "路口立了一只黄色的标识，提醒行人注意。", "corrected_sentence": "路口立了一个黄色的标识，提醒行人注意。", "error_description": "错误形式：“一只标识”。正确形式：“一个标识”。〈只〉用于动物或成对的物品，标识应当用〈个〉。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04b0d076-3bc8-4549-b757-b08aa083512e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12492, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们在门口点了一个标识，让大家看到。", "corrected_sentence": "我们在门口挂了一个标识，让大家看到。", "error_description": "错误形式：“点了一个标识”。正确形式：“挂了一个标识”。标识是挂在门口的记号，“点”不能搭配标识。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04b0d076-3bc8-4549-b757-b08aa083512e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
