INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12493, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "辨别不同之处，使事物之间不混淆。", "primary_collocate": null, "pronunciation": "qū fēn", "ipa": "tɕʰy˥ fən˥", "syllable_count": 2, "sentences": [{"text": "这一设计的起源可追溯至1970年美国首届“地球日”活动，当时包装行业亟需一种公众易于识别的标识，以区分可回收材料与普通垃圾。", "target_word": "区分", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "双胞胎长得很像，很难区分。", "target_word": "区分", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们用不同的颜色来区分它们。", "target_word": "区分", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你能区分这两种茶吗？", "target_word": "区分", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "老师教孩子区分大小。", "target_word": "区分", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这两个词的意思很接近，不容易区分。", "target_word": "区分", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "要学会区分真话和假话。", "target_word": "区分", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "地图上用线条区分不同的路。", "target_word": "区分", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这两种颜色太接近，不好区分。", "target_word": "区分", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "工厂里的工人用标签区分不同的零件。", "target_word": "区分", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "區分", "label": "繁体"}, {"form": "区分了", "label": "体标"}, {"form": "区分过", "label": "体标"}, {"form": "区分度", "label": "复合"}], "register": "中性", "sense_fingerprint": "动词：辨别不同之处，使事物之间不混淆", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '98e0b363-6408-4edb-93ac-1d50e90a7dc1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12493, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "组合", "is_correct": false, "explanation": "语义：“组合”是把东西合在一起，与“以…标识”要辨明材料种类的目的相反。"}, {"text": "区分", "is_correct": true, "explanation": "“区分”指辨别可回收材料与普通垃圾的不同之处，与句意相符。"}, {"text": "打扮", "is_correct": false, "explanation": "搭配：“打扮”用于人或外表的修饰，不能用来处理“可回收材料”。"}, {"text": "分配", "is_correct": false, "explanation": "配价：“分配”需要接收对象（分配给谁），句中没有这样的对象。"}], "explanations": {"组合": "语义：“组合”是把东西合在一起，与“以…标识”要辨明材料种类的目的相反。", "区分": "“区分”指辨别可回收材料与普通垃圾的不同之处，与句意相符。", "打扮": "搭配：“打扮”用于人或外表的修饰，不能用来处理“可回收材料”。", "分配": "配价：“分配”需要接收对象（分配给谁），句中没有这样的对象。"}, "sentence_index": 0, "correct_answer": "区分"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我一眼就区分了他。", "explanation": "这里应该用〈认出〉。区分指辨别两种或多种事物的不同之处，只针对一个人时用“认出”。"}, {"text": "我区分了两家公司的价格。", "explanation": "这里应该用〈比较〉。区分指辨别不同之处，衡量价格的高低要用“比较”。"}, {"text": "我终于区分了丢失的钥匙。", "explanation": "这里应该用〈找到〉。区分是辨别事物的不同，寻回丢失的东西要用“找到”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04b0d076-3bc8-4549-b757-b08aa083512e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12493, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "翻译", "is_correct": false, "explanation": "搭配：“翻译”的对象是语言文字，不能与“真话、假话”搭配。"}, {"text": "编造", "is_correct": false, "explanation": "语义：“编造”是捏造，与“要学会…真话和假话”要分辨真伪的语境相反。"}, {"text": "区分", "is_correct": true, "explanation": "“区分”指辨别真话与假话的不同，与句意相符。"}, {"text": "复制", "is_correct": false, "explanation": "搭配：“复制”用于具体物件或文本，不能用于“真话、假话”。"}], "explanations": {"翻译": "搭配：“翻译”的对象是语言文字，不能与“真话、假话”搭配。", "编造": "语义：“编造”是捏造，与“要学会…真话和假话”要分辨真伪的语境相反。", "区分": "“区分”指辨别真话与假话的不同，与句意相符。", "复制": "搭配：“复制”用于具体物件或文本，不能用于“真话、假话”。"}, "sentence_index": 6, "correct_answer": "区分"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "工人区分了零件的数量。", "explanation": "这里应该用〈清点〉。区分是辨别不同之处，数清零件的数目要用“清点”。"}, {"text": "工人区分了零件的温度。", "explanation": "这里应该用〈测量〉。区分指辨别不同之处，测取温度的数值要用“测量”。"}, {"text": "工人区分了零件的油污。", "explanation": "这里应该用〈清洗〉。区分是辨别不同之处，去除油污要用“清洗”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04b0d076-3bc8-4549-b757-b08aa083512e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12493, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这两种颜色很像，但我能区分很清楚。", "corrected_sentence": "这两种颜色很像，但我能区分得很清楚。", "error_description": "错误形式：“区分很清楚”；正确形式：“区分得很清楚”。“很清楚”作补语时须用结构助词“得”与动词相连。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04b0d076-3bc8-4549-b757-b08aa083512e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12493, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这种药和那种药的味道很像，但老中医能区分很清楚。", "corrected_sentence": "这种药和那种药的味道很像，但老中医能区分得很清楚。", "error_description": "错误形式：“能区分很清楚”；正确形式：“能区分得很清楚”。“很清楚”作补语时须用结构助词“得”与动词相连。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04b0d076-3bc8-4549-b757-b08aa083512e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
