INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12496, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "指年龄不大，处于生命早期阶段。", "primary_collocate": null, "pronunciation": "nián qīng", "ipa": "njɛn˧˥ tɕʰiŋ˥", "syllable_count": 2, "sentences": [{"text": "他看起来很年轻。", "target_word": "年轻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位老师很年轻，才二十五岁。", "target_word": "年轻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "年轻的时候，我常常去爬山。", "target_word": "年轻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈五十岁了，但是看着很年轻。", "target_word": "年轻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司里的人都很年轻。", "target_word": "年轻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她比我年轻三岁。", "target_word": "年轻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "年轻的医生走进了房间。", "target_word": "年轻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷说他年轻时住在乡下。", "target_word": "年轻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你还年轻，应该多学一点。", "target_word": "年轻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个年轻的老板喜欢跑步。", "target_word": "年轻", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "年轻人", "label": "复合"}, {"form": "年轻化", "label": "复合"}], "register": "中性", "sense_fingerprint": "年轻|年龄不大，处于生命早期", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '98e0b363-6408-4edb-93ac-1d50e90a7dc1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12496, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "年轻", "is_correct": true, "explanation": "正确答案：“他看起来很年轻”指外貌显得年纪小，符合语境。"}, {"text": "漫长", "is_correct": false, "explanation": "语义：“漫长”形容时间或路程，不能形容人看起来的样子。"}, {"text": "狭窄", "is_correct": false, "explanation": "搭配：“狭窄”多用于空间或道路，不说人看起来狭窄。"}, {"text": "潮湿", "is_correct": false, "explanation": "语义：“潮湿”形容环境或物体，不能用来形容人的样子。"}], "explanations": {"年轻": "正确答案：“他看起来很年轻”指外貌显得年纪小，符合语境。", "漫长": "语义：“漫长”形容时间或路程，不能形容人看起来的样子。", "狭窄": "搭配：“狭窄”多用于空间或道路，不说人看起来狭窄。", "潮湿": "语义：“潮湿”形容环境或物体，不能用来形容人的样子。"}, "sentence_index": 0, "correct_answer": "年轻"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这台电脑很年轻，刚买了一个月。", "explanation": "这里应该用〈新〉。年轻多指人或动物的年龄，电脑刚买不说年轻，应说新。"}, {"text": "这盘青菜很年轻，炒起来很脆。", "explanation": "这里应该用〈嫩〉。青菜没有年龄，形容蔬菜鲜嫩要用嫩。"}, {"text": "这把椅子很年轻，用了十年。", "explanation": "这里应该用〈旧〉。椅子不会有年龄，说用了很久要用旧。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04b0d076-3bc8-4549-b757-b08aa083512e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12496, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "年轻", "is_correct": true, "explanation": "正确答案：“年轻的医生”指年纪不大的医生，符合语境。"}, {"text": "陡峭", "is_correct": false, "explanation": "搭配：“陡峭”形容山坡等地形，不能形容医生。"}, {"text": "辽阔", "is_correct": false, "explanation": "语义：“辽阔”形容土地或天空，与医生无关。"}, {"text": "透明", "is_correct": false, "explanation": "语义：“透明”指能看透，不能用来形容医生。"}], "explanations": {"年轻": "正确答案：“年轻的医生”指年纪不大的医生，符合语境。", "陡峭": "搭配：“陡峭”形容山坡等地形，不能形容医生。", "辽阔": "语义：“辽阔”形容土地或天空，与医生无关。", "透明": "语义：“透明”指能看透，不能用来形容医生。"}, "sentence_index": 6, "correct_answer": "年轻"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这里的空气很年轻，早晨很舒服。", "explanation": "这里应该用〈清新〉。空气没有年龄，形容空气清爽要用清新。"}, {"text": "这块面包很年轻，刚出炉。", "explanation": "这里应该用〈新鲜〉。面包没有年龄，形容食物刚做好要用新鲜。"}, {"text": "这座房子很年轻，建了三十年。", "explanation": "这里应该用〈陈旧〉。房子不是生命体，说建成已久要用陈旧。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04b0d076-3bc8-4549-b757-b08aa083512e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12496, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他比哥哥年轻过两岁。", "corrected_sentence": "他比哥哥年轻两岁。", "error_description": "比较句“A比B＋形容词＋数量”说明差距时，形容词后不能加“过”。应去掉“过”，说“他比哥哥年轻两岁”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04b0d076-3bc8-4549-b757-b08aa083512e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12496, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "年轻地护士走进了病房。", "corrected_sentence": "年轻的护士走进了病房。", "error_description": "“年轻”修饰名词“护士”，应用“的”。“地”用来修饰动词，此处应改为“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04b0d076-3bc8-4549-b757-b08aa083512e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
