INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12497, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "指几何上没有厚度、没有高低起伏的二维表面。", "primary_collocate": null, "pronunciation": "píng miàn", "ipa": "pʰiŋ˧˥ mjɛn˥˩", "syllable_count": 2, "sentences": [{"text": "黑板经过打磨，表面非常光滑，几乎可以看作一个完美的平面，写在上面的字迹也格外清楚。", "target_word": "平面", "complexity_tier": "T5", "sentence_source": "generated"}, {"text": "纸是平面的，球不是平面的。", "target_word": "平面", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "数学课上，老师讲了平面和立体的不同。", "target_word": "平面", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "两条直线可以在同一个平面上。", "target_word": "平面", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "不在一条线上的三个点，能决定一个平面。", "target_word": "平面", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "地图把地球画在平面上，所以会有一些变形。", "target_word": "平面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "球的表面不是平面，而是曲面。", "target_word": "平面", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们先学平面，再学立体。", "target_word": "平面", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "在平面上，两条线要么相交，要么平行。", "target_word": "平面", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他用尺子在平面上画了一个三角形。", "target_word": "平面", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "平面图", "label": "复合"}, {"form": "平面设计", "label": "复合"}], "register": "中性", "sense_fingerprint": "平面：几何上没有厚度的二维表面", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '642832d6-af4f-4008-8f4d-ac33a85c01e4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12497, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "平面", "is_correct": true, "explanation": "平面：没有高低起伏的平坦表面，与“表面非常光滑”“完美”的描述相符。"}, {"text": "曲面", "is_correct": false, "explanation": "语义：黑板是平的，不是曲面，与“完美的……”所描述的平整表面不符。"}, {"text": "斜坡", "is_correct": false, "explanation": "语义：斜坡是倾斜的坡面，黑板并不倾斜。"}, {"text": "球面", "is_correct": false, "explanation": "语义：球面是弯曲的，与黑板平整的表面不符。"}], "explanations": {"平面": "平面：没有高低起伏的平坦表面，与“表面非常光滑”“完美”的描述相符。", "曲面": "语义：黑板是平的，不是曲面，与“完美的……”所描述的平整表面不符。", "斜坡": "语义：斜坡是倾斜的坡面，黑板并不倾斜。", "球面": "语义：球面是弯曲的，与黑板平整的表面不符。"}, "sentence_index": 0, "correct_answer": "平面"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这颗苹果的平面上有一层蜡。", "explanation": "这里应该用〈表面〉。平面指平坦的面，苹果是圆的，没有平面；说物体外层时用“表面”。"}, {"text": "这次改革要从制度平面入手。", "explanation": "这里应该用〈层面〉。平面指平平的面，说事情的方面或角度时要用“层面”。"}, {"text": "这张纸上有一条平面。", "explanation": "这里应该用〈个〉。平面是抽象的几何面，量词用“个”，不用“条”（“条”多用于细长的东西）。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0250f2ac-1a0a-446f-9ecf-9aba6be4380b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12497, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "平面", "is_correct": true, "explanation": "平面：几何上平坦的二维面，与“而是曲面”形成对照。"}, {"text": "平原", "is_correct": false, "explanation": "语义：平原是地表地形，不能用来指球的表面。"}, {"text": "方块", "is_correct": false, "explanation": "语义：方块是有棱有角的块状物，球的表面不是方块，与“而是曲面”的对照不成立。"}, {"text": "角度", "is_correct": false, "explanation": "搭配：“角度”多与测量、视角搭配，不与“球的表面”对举。"}], "explanations": {"平面": "平面：几何上平坦的二维面，与“而是曲面”形成对照。", "平原": "语义：平原是地表地形，不能用来指球的表面。", "方块": "语义：方块是有棱有角的块状物，球的表面不是方块，与“而是曲面”的对照不成立。", "角度": "搭配：“角度”多与测量、视角搭配，不与“球的表面”对举。"}, "sentence_index": 6, "correct_answer": "平面"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个西瓜的平面很厚。", "explanation": "这里应该用〈表层〉。平面指平坦的面，西瓜是圆的，没有平面；只说外层时用“表层”。"}, {"text": "这件衣服的平面很好看，颜色也很配。", "explanation": "这里应该用〈外观〉。平面指没有高低起伏的表面，说衣服的样子好不好看要用“外观”。"}, {"text": "桌上放着一座平面。", "explanation": "这里应该用〈个〉。平面用量词“个”，“座”多用于山、桥、建筑等大型物体。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0250f2ac-1a0a-446f-9ecf-9aba6be4380b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12497, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "老师在黑板上画了一根平面。", "corrected_sentence": "老师在黑板上画了一个平面。", "error_description": "量词错误：“平面”应用量词“个”，不能用“根”（“根”用于细长的东西）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0250f2ac-1a0a-446f-9ecf-9aba6be4380b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12497, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他在本子上画了一只平面。", "corrected_sentence": "他在本子上画了一个平面。", "error_description": "量词错误：“平面”应用“个”，不能用“只”（“只”用于动物或成对器物中的一个）。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0250f2ac-1a0a-446f-9ecf-9aba6be4380b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
