INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12498, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指在会议或讨论中提出供大家审议、讨论或表决的建议或方案。", "primary_collocate": null, "pronunciation": "tí àn", "ipa": "tʰi˧˥ an˥˩", "syllable_count": 2, "sentences": [{"text": "这位年轻设计师在评审会上提交的提案，经过三轮投票后最终胜出。", "target_word": "提案", "complexity_tier": "T5", "sentence_source": "generated"}, {"text": "会上有人提出了一份新提案。", "target_word": "提案", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "大家投票通过了这项提案。", "target_word": "提案", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "代表们对这份提案提出了意见。", "target_word": "提案", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这份提案没有得到多数人的支持。", "target_word": "提案", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "会议结束前，大家要表决这项提案。", "target_word": "提案", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他在董事会上提交了环保提案。", "target_word": "提案", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "委员会认真讨论了这个提案，最后决定修改。", "target_word": "提案", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "提案还没有通过，所以大家要继续讨论。", "target_word": "提案", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的提案得到了校长的同意。", "target_word": "提案", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "份", "label": "量词"}, {"form": "项", "label": "量词"}, {"form": "提案人", "label": "复合"}], "register": "正式", "sense_fingerprint": "提案：会议上供审议表决的正式建议", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '642832d6-af4f-4008-8f4d-ac33a85c01e4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12498, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "提案", "is_correct": true, "explanation": "提案：会议上提交审议的正式方案，与“评审会上提交”“投票后胜出”相符。"}, {"text": "提问", "is_correct": false, "explanation": "语义：提问是问题，不是提交审议的方案，不能“胜出”。"}, {"text": "感想", "is_correct": false, "explanation": "语义：感想是个人心得，不是提交审议的方案，不能“胜出”。"}, {"text": "脾气", "is_correct": false, "explanation": "搭配：“脾气”不能与“胜出”搭配。"}], "explanations": {"提案": "提案：会议上提交审议的正式方案，与“评审会上提交”“投票后胜出”相符。", "提问": "语义：提问是问题，不是提交审议的方案，不能“胜出”。", "感想": "语义：感想是个人心得，不是提交审议的方案，不能“胜出”。", "脾气": "搭配：“脾气”不能与“胜出”搭配。"}, "sentence_index": 0, "correct_answer": "提案"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "小王提案去爬山。", "explanation": "这里应该用〈提议〉。提案指会议上正式提交的议案，这里说的是随口提出的建议，用“提议”。"}, {"text": "他在公园里向陌生人提案，请对方帮忙拍照。", "explanation": "这里应该用〈请求〉。提案指会议上提交的议案，向陌生人请求帮忙要用“请求”。"}, {"text": "他向会议交了一把提案。", "explanation": "这里应该用〈份〉。提案用“份”或“项”计量，“把”多用于有柄的器具。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0250f2ac-1a0a-446f-9ecf-9aba6be4380b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12498, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "提案", "is_correct": true, "explanation": "提案：董事会上提交审议的正式方案，与“提交”相符。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色不能被提交。"}, {"text": "温度", "is_correct": false, "explanation": "语义：温度不是可以提交的方案。"}, {"text": "心情", "is_correct": false, "explanation": "搭配：“心情”不能与“提交”搭配。"}], "explanations": {"提案": "提案：董事会上提交审议的正式方案，与“提交”相符。", "颜色": "语义：颜色不能被提交。", "温度": "语义：温度不是可以提交的方案。", "心情": "搭配：“心情”不能与“提交”搭配。"}, "sentence_index": 6, "correct_answer": "提案"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我提案明天请假。", "explanation": "这里应该用〈申请〉。提案指会议上正式提交的议案，向人请假要说“申请”。"}, {"text": "她交了一根提案。", "explanation": "这里应该用〈份〉。提案用“份”计量，“根”用于细长的东西。"}, {"text": "妈妈给我讲了一个睡前提案。", "explanation": "这里应该用〈故事〉。提案是会议上提交审议的议案，睡前讲的是故事，不是议案。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0250f2ac-1a0a-446f-9ecf-9aba6be4380b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12498, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "大家讨论了一只新提案。", "corrected_sentence": "大家讨论了一项新提案。", "error_description": "量词错误：“提案”应用“项”或“份”，不能用“只”（“只”用于动物或成对器物中的一个）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0250f2ac-1a0a-446f-9ecf-9aba6be4380b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12498, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她在会上提交了一颗提案。", "corrected_sentence": "她在会上提交了一份提案。", "error_description": "量词错误：“提案”应用“份”，不能用“颗”（“颗”用于小而圆的东西）。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0250f2ac-1a0a-446f-9ecf-9aba6be4380b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
