INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12499, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "在比赛或竞争中取得胜利", "primary_collocate": null, "pronunciation": "shèng chū", "ipa": "ʂɤŋ˥˩ ʈʂʰu˥", "syllable_count": 2, "sentences": [{"text": "经过公开征集，年轻平面设计师的提案最终胜出：三条首尾相连的箭头构成莫比乌斯环的变体，既暗示物质的无限循环，又通过动态线条传递持续运动的能量感。", "target_word": "胜出", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "小王在决赛中胜出。", "target_word": "胜出", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "两队比赛很激烈，最后红队胜出。", "target_word": "胜出", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他在选举中胜出，成为新市长。", "target_word": "胜出", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "经过三轮比赛，她终于胜出了。", "target_word": "胜出", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家公司在竞争中胜出，拿到了合同。", "target_word": "胜出", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "谁能在这场辩论赛中胜出，还很难说。", "target_word": "胜出", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他靠着稳定的发挥，在比赛里胜出。", "target_word": "胜出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "三位候选人中，只有一位能够胜出。", "target_word": "胜出", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他曾经在全国大赛中胜出过。", "target_word": "胜出", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "胜出了", "label": "体标"}, {"form": "胜出过", "label": "体标"}, {"form": "勝出", "label": "繁体"}], "register": "书面", "sense_fingerprint": "胜出：在比赛或竞争中取得胜利", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '642832d6-af4f-4008-8f4d-ac33a85c01e4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12499, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "胜出", "is_correct": true, "explanation": "与听到的读音一致，是正确答案。"}, {"text": "生出", "is_correct": false, "explanation": "shēng（第一声）与 shèng（第四声）声调不同，意思是长出、产生。"}, {"text": "省出", "is_correct": false, "explanation": "shěng（第三声）与 shèng（第四声）声调不同，意思是节省后留下。"}, {"text": "渗出", "is_correct": false, "explanation": "shèn 与 shèng 韵母不同（-n 与 -ng），意思是液体慢慢透出。"}], "explanations": {"胜出": "与听到的读音一致，是正确答案。", "生出": "shēng（第一声）与 shèng（第四声）声调不同，意思是长出、产生。", "省出": "shěng（第三声）与 shèng（第四声）声调不同，意思是节省后留下。", "渗出": "shèn 与 shèng 韵母不同（-n 与 -ng），意思是液体慢慢透出。"}, "sentence_index": null, "correct_answer": "胜出"}, "level_3": {"options": [{"text": "胜出", "is_correct": true, "explanation": "正确：经过公开征集之后，提案最终获胜。"}, {"text": "落选", "is_correct": false, "explanation": "语义：落选指没有被选中，与“经过公开征集”后的入选结果相反，也与后文对提案的正面描述冲突。"}, {"text": "败北", "is_correct": false, "explanation": "语义：败北表示战败，与提案最终入选并被详细介绍的结果相反。"}, {"text": "退出", "is_correct": false, "explanation": "语义：退出指主动离开，提案「最终退出」之后却详细描述其设计，前后矛盾。"}], "explanations": {"胜出": "正确：经过公开征集之后，提案最终获胜。", "落选": "语义：落选指没有被选中，与“经过公开征集”后的入选结果相反，也与后文对提案的正面描述冲突。", "败北": "语义：败北表示战败，与提案最终入选并被详细介绍的结果相反。", "退出": "语义：退出指主动离开，提案「最终退出」之后却详细描述其设计，前后矛盾。"}, "sentence_index": 0, "correct_answer": "胜出"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这把锁终于胜出了。", "explanation": "这里应该用〈打开〉。胜出指在比赛或竞争中取得胜利，锁被打开不是竞争的结果。"}, {"text": "这次手术终于胜出了。", "explanation": "这里应该用〈成功〉。胜出指在比赛或竞争中取得胜利，手术成功不涉及竞争的胜负。"}, {"text": "伤口终于胜出了。", "explanation": "这里应该用〈愈合〉。胜出指在比赛或竞争中取得胜利，伤口愈合不是竞争的结果。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0250f2ac-1a0a-446f-9ecf-9aba6be4380b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12499, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "胜出", "is_correct": true, "explanation": "正确：「还很难说」之前的主语是能在比赛中获胜的人，应填入表示获胜的「胜出」。"}, {"text": "跳舞", "is_correct": false, "explanation": "语义：跳舞与辩论赛的语境不合，辩论赛中不能跳舞。"}, {"text": "增长", "is_correct": false, "explanation": "搭配：增长说的是数量或程度，不能用来说比赛的胜负。"}, {"text": "出拳", "is_correct": false, "explanation": "语义：出拳是一种肢体动作，与辩论赛的语境不合。"}], "explanations": {"胜出": "正确：「还很难说」之前的主语是能在比赛中获胜的人，应填入表示获胜的「胜出」。", "跳舞": "语义：跳舞与辩论赛的语境不合，辩论赛中不能跳舞。", "增长": "搭配：增长说的是数量或程度，不能用来说比赛的胜负。", "出拳": "语义：出拳是一种肢体动作，与辩论赛的语境不合。"}, "sentence_index": 6, "correct_answer": "胜出"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "杯子里的水终于胜出了。", "explanation": "这里应该用〈蒸发〉。胜出指在比赛或竞争中取得胜利，水蒸发不是竞争的结果。"}, {"text": "河面终于胜出了。", "explanation": "这里应该用〈结冰〉。胜出指在比赛或竞争中取得胜利，河面结冰不是竞争的结果。"}, {"text": "屋里的灰尘终于胜出了。", "explanation": "这里应该用〈散去〉。胜出指在比赛或竞争中取得胜利，灰尘散去不涉及竞争的胜负。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0250f2ac-1a0a-446f-9ecf-9aba6be4380b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12499, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他在初赛中被胜出，进入了决赛。", "corrected_sentence": "他在初赛中胜出，进入了决赛。", "error_description": "错误形式「被胜出」，正确形式「胜出」。胜出是不及物动词，不能加「被」构成被动式。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0250f2ac-1a0a-446f-9ecf-9aba6be4380b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12499, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "红队在最后一局中很胜出了，赢得了比赛。", "corrected_sentence": "红队在最后一局中胜出了，赢得了比赛。", "error_description": "错误形式「很胜出」，正确形式「胜出」。胜出是动作动词，不能用程度副词「很」修饰。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0250f2ac-1a0a-446f-9ecf-9aba6be4380b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
