INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12500, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "property", "definition": "指事物前后连接，形成一个连续的整体。", "primary_collocate": null, "pronunciation": "shǒu wěi xiāng lián", "ipa": "ʂoʊ̯˨˩ weɪ̯˨˩ ɕjɑŋ˥ ljɛn˧˥", "syllable_count": 4, "sentences": [{"text": "经过公开征集，年轻平面设计师的提案最终胜出：三条首尾相连的箭头构成莫比乌斯环的变体，既暗示物质的无限循环，又通过动态线条传递持续运动的能量感。", "target_word": "首尾相连", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这些车厢首尾相连，像一条长龙。", "target_word": "首尾相连", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "三个圆圈首尾相连，组成了一个图案。", "target_word": "首尾相连", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "首尾相连的铁链挂在墙上。", "target_word": "首尾相连", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "桌上的纸条首尾相连，围成了一圈。", "target_word": "首尾相连", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们首尾相连，排成了一条长队。", "target_word": "首尾相连", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条项链由很多小珠子首尾相连而成。", "target_word": "首尾相连", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这几座桥首尾相连，一直通到对岸。", "target_word": "首尾相连", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把几张纸首尾相连地贴在一起。", "target_word": "首尾相连", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "图中的箭头首尾相连，表示事情不断循环。", "target_word": "首尾相连", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "首尾相連", "label": "繁体"}], "register": "中性", "sense_fingerprint": "事物前后相接，连成一个连续的整体", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '642832d6-af4f-4008-8f4d-ac33a85c01e4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12500, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "首尾相连", "is_correct": true, "explanation": "正确：箭头的尾与头相接，才能构成莫比乌斯环。"}, {"text": "平行", "is_correct": false, "explanation": "语义：平行的箭头彼此不接，不能构成闭合的环。"}, {"text": "分散", "is_correct": false, "explanation": "语义：分散的箭头彼此分开，与「构成莫比乌斯环」不符。"}, {"text": "笔直", "is_correct": false, "explanation": "体貌：笔直只描写线条形状，没有说明两端相接，无法构成环。"}], "explanations": {"首尾相连": "正确：箭头的尾与头相接，才能构成莫比乌斯环。", "平行": "语义：平行的箭头彼此不接，不能构成闭合的环。", "分散": "语义：分散的箭头彼此分开，与「构成莫比乌斯环」不符。", "笔直": "体貌：笔直只描写线条形状，没有说明两端相接，无法构成环。"}, "sentence_index": 0, "correct_answer": "首尾相连"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这块大石头首尾相连，很结实。", "explanation": "这里应该用〈完整〉。首尾相连指两个以上事物的头尾相接，一整块石头不存在头尾相接。"}, {"text": "这座塔的两侧首尾相连，很高大。", "explanation": "这里应该用〈对称〉。首尾相连指事物头尾接合，不用来说两侧的形状。"}, {"text": "这张床首尾相连，睡起来很舒服。", "explanation": "这里应该用〈柔软〉。首尾相连指多个事物头尾接合，一张床不存在这种接合。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0250f2ac-1a0a-446f-9ecf-9aba6be4380b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12500, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "首尾相连", "is_correct": true, "explanation": "正确：珠子一颗接一颗地串起来，形成完整的项链。"}, {"text": "零散", "is_correct": false, "explanation": "语义：零散指分散、不成整体，与「由很多小珠子串起来」不符。"}, {"text": "光滑", "is_correct": false, "explanation": "体貌：光滑描写表面质感，与珠子的串接方式无关。"}, {"text": "破碎", "is_correct": false, "explanation": "语义：破碎指碎裂，与项链的完整串接相反。"}], "explanations": {"首尾相连": "正确：珠子一颗接一颗地串起来，形成完整的项链。", "零散": "语义：零散指分散、不成整体，与「由很多小珠子串起来」不符。", "光滑": "体貌：光滑描写表面质感，与珠子的串接方式无关。", "破碎": "语义：破碎指碎裂，与项链的完整串接相反。"}, "sentence_index": 6, "correct_answer": "首尾相连"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这座房子首尾相连，很气派。", "explanation": "这里应该用〈宏伟〉。首尾相连指事物的头尾接合，单独一座房子不存在这种接合。"}, {"text": "这碗汤首尾相连，很香。", "explanation": "这里应该用〈鲜美〉。首尾相连指多个事物头尾接合，一碗汤不存在这种接合。"}, {"text": "这把椅子首尾相连，坐着很稳。", "explanation": "这里应该用〈结实〉。首尾相连要求两个以上事物头尾相接，一把椅子不存在这种接合。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0250f2ac-1a0a-446f-9ecf-9aba6be4380b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12500, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "几根绳子首尾相连了一个圈。", "corrected_sentence": "几根绳子首尾相连成一个圈。", "error_description": "错误形式「首尾相连了一个圈」，正确形式「首尾相连成一个圈」。「成」是结果补语，表示连接后形成的结果，不能用「了」代替。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0250f2ac-1a0a-446f-9ecf-9aba6be4380b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12500, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "几个圆环了首尾相连，像一条长链。", "corrected_sentence": "几个圆环首尾相连，像一条长链。", "error_description": "错误形式「了首尾相连」，正确形式「首尾相连」。「了」是体标，不能放在「首尾相连」之前，这里应直接说「首尾相连」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0250f2ac-1a0a-446f-9ecf-9aba6be4380b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
