INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12504, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0250f2ac-1a0a-446f-9ecf-9aba6be4380b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12504, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "变体指同一事物在形式、内容等方面的变异形态。", "primary_collocate": null, "pronunciation": "biàn tǐ", "ipa": "pjɛn˥˩ tʰi˨˩", "syllable_count": 2, "sentences": [{"text": "经过公开征集，年轻平面设计师的提案最终胜出：三条首尾相连的箭头构成莫比乌斯环的变体，既暗示物质的无限循环，又通过动态线条传递持续运动的能量感。", "target_word": "变体", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "如今，在碳中和议程与循环经济政策的推动下，其象征意义仍在持续重构——新一代变体设计开始融入生物降解指示、碳足迹数据乃至动态二维码，预示着静态符号向智能信息接口的演进。", "target_word": "变体", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这个字有两种变体。", "target_word": "变体", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这种病毒出现了新的变体。", "target_word": "变体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这首歌是老歌的一个变体。", "target_word": "变体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个故事有很多变体。", "target_word": "变体", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他设计了这个标志的变体。", "target_word": "变体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们公司用了这个图案的变体。", "target_word": "变体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个词的变体在南方很常见。", "target_word": "变体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新变体比原来的病毒传得快。", "target_word": "变体", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一种变体", "label": "量词"}, {"form": "變體", "label": "繁体"}], "register": "中性", "sense_fingerprint": "同一事物在形式或内容上产生变异的形态", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '642832d6-af4f-4008-8f4d-ac33a85c01e4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12504, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "变体", "is_correct": true, "explanation": "“莫比乌斯环的变体”指同一图形在形式上的变异形态，符合句意。"}, {"text": "歌", "is_correct": false, "explanation": "语义：“莫比乌斯环的歌”说不通，歌不是图形的形式。"}, {"text": "床", "is_correct": false, "explanation": "语义：床与几何图形的形式变异无关，句意不通。"}, {"text": "汤", "is_correct": false, "explanation": "搭配：“莫比乌斯环的”后面不能接“汤”这类食物。"}], "explanations": {"变体": "“莫比乌斯环的变体”指同一图形在形式上的变异形态，符合句意。", "歌": "语义：“莫比乌斯环的歌”说不通，歌不是图形的形式。", "床": "语义：床与几何图形的形式变异无关，句意不通。", "汤": "搭配：“莫比乌斯环的”后面不能接“汤”这类食物。"}, "sentence_index": 0, "correct_answer": "变体"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "今年夏天的天气变体很大。", "explanation": "这里应该用〈变化〉。变体指同一事物形式上的变异形态，不指天气的变动过程。"}, {"text": "这个月的物价变体很厉害。", "explanation": "这里应该用〈波动〉。变体指同一事物形式上的变异形态，不指物价的起伏。"}, {"text": "这种病毒很快就变体了。", "explanation": "这里应该用〈变异〉。变体是名词，不能作动词谓语，动词要说“变异”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0250f2ac-1a0a-446f-9ecf-9aba6be4380b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12504, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "变体", "is_correct": true, "explanation": "“他设计了这个标志的变体”，指标志在形式上的变异形态，符合句意。"}, {"text": "雨", "is_correct": false, "explanation": "语义：“设计了……的雨”说不通，雨不是可以设计的对象。"}, {"text": "病", "is_correct": false, "explanation": "搭配：“设计”的对象是图形、作品，不能说“设计……的病”。"}, {"text": "雾", "is_correct": false, "explanation": "语义：雾不是标志，“标志的雾”说不通。"}], "explanations": {"变体": "“他设计了这个标志的变体”，指标志在形式上的变异形态，符合句意。", "雨": "语义：“设计了……的雨”说不通，雨不是可以设计的对象。", "病": "搭配：“设计”的对象是图形、作品，不能说“设计……的病”。", "雾": "语义：雾不是标志，“标志的雾”说不通。"}, "sentence_index": 6, "correct_answer": "变体"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的性格有了很大的变体。", "explanation": "这里应该用〈转变〉。变体指形式上的变异形态，不用来说性格的转变过程。"}, {"text": "这个金属雕塑因为高温变体了。", "explanation": "这里应该用〈变形〉。变体是名词，不能作动词谓语，动词要说“变形”。"}, {"text": "这次考试的成绩变体很大。", "explanation": "这里应该用〈变化〉。变体指同一事物的变异形态，不指成绩的升降。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0250f2ac-1a0a-446f-9ecf-9aba6be4380b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12504, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他找到了一只变体。", "corrected_sentence": "他找到了一种变体。", "error_description": "量词错误：“只”多用于动物或成对物件中的一个，变体应用“种”。正确说法是“一种变体”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0250f2ac-1a0a-446f-9ecf-9aba6be4380b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12504, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个标志有一条变体。", "corrected_sentence": "这个标志有一种变体。", "error_description": "量词错误：“条”用于线状或条状的东西，变体应用“种”。正确说法是“一种变体”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0250f2ac-1a0a-446f-9ecf-9aba6be4380b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
