INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12505, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "可以被回收和重复使用的物理材料", "primary_collocate": null, "pronunciation": "wù zhì", "ipa": "u⁵¹ ʈʂʅ⁵¹", "syllable_count": 2, "sentences": [{"text": "经过公开征集，年轻平面设计师的提案最终胜出：三条首尾相连的箭头构成莫比乌斯环的变体，既暗示物质的无限循环，又通过动态线条传递持续运动的能量感。", "target_word": "物质", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "废旧电池中的有用物质可以回收再利用。", "target_word": "物质", "complexity_tier": "T3", "furigana": "fèi jiù diàn chí zhōng de yǒu yòng wù zhì kě yǐ huí shōu zài lì yòng", "sentence_source": "generated"}, {"text": "这些有机物质经过处理后可以重复使用。", "target_word": "物质", "complexity_tier": "T3", "furigana": "zhè xiē yǒu jī wù zhì jīng guò chǔ lǐ hòu kě yǐ chóng fù shǐ yòng", "sentence_source": "generated"}, {"text": "工厂把回收的有用物质加工成新产品。", "target_word": "物质", "complexity_tier": "T3", "furigana": "gōng chǎng bǎ huí shōu de yǒu yòng wù zhì jiā gōng chéng xīn chǎn pǐn", "sentence_source": "generated"}, {"text": "这些物质不能直接丢进垃圾桶。", "target_word": "物质", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "废纸中的纤维物质可以回收再利用。", "target_word": "物质", "complexity_tier": "T3", "furigana": "fèi zhǐ zhōng de xiān wéi wù zhì kě yǐ huí shōu zài lì yòng", "sentence_source": "generated"}, {"text": "回收站收集各种可以再用的物质。", "target_word": "物质", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把能回收的物质放进蓝色箱子。", "target_word": "物质", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种有用物质用完后还能重新利用。", "target_word": "物质", "complexity_tier": "T3", "furigana": "zhè zhǒng yǒu yòng wù zhì yòng wán hòu hái néng chóng xīn lì yòng", "sentence_source": "generated"}, {"text": "旧衣服中的纤维物质也可以重新利用。", "target_word": "物质", "complexity_tier": "T3", "furigana": "jiù yī fu zhōng de xiān wéi wù zhì yě kě yǐ chóng xīn lì yòng", "sentence_source": "generated"}], "morphological_forms": [{"form": "物質", "label": "繁体"}], "register": "中性", "sense_fingerprint": "可回收、可重复使用的物理材料", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3c7f2601-5d41-4e78-8d42-413e02a40644') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12505, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "物质", "is_correct": true, "explanation": "物质（wù zhì）指可以被回收和重复使用的物理材料。"}, {"text": "务实", "is_correct": false, "explanation": "务实（wù shí）与物质（wù zhì）的第二音节声母不同（shí 为 sh，zhì 为 zh），意思是注重实际。"}, {"text": "误植", "is_correct": false, "explanation": "误植（wù zhí）第二音节 zhí 为第二声，与 zhì（第四声）声调不同，意思是排版时出现的错字。"}, {"text": "无知", "is_correct": false, "explanation": "无知（wú zhī）第一音节 wú 为第二声，与 wù（第四声）声调不同，意思是缺乏知识。"}, {"text": "误事", "is_correct": false, "explanation": "误事（wù shì）第二音节 shì 与 zhì 声母不同（sh 与 zh），意思是耽误事情。"}], "explanations": {"物质": "物质（wù zhì）指可以被回收和重复使用的物理材料。", "务实": "务实（wù shí）与物质（wù zhì）的第二音节声母不同（shí 为 sh，zhì 为 zh），意思是注重实际。", "误植": "误植（wù zhí）第二音节 zhí 为第二声，与 zhì（第四声）声调不同，意思是排版时出现的错字。", "无知": "无知（wú zhī）第一音节 wú 为第二声，与 wù（第四声）声调不同，意思是缺乏知识。", "误事": "误事（wù shì）第二音节 shì 与 zhì 声母不同（sh 与 zh），意思是耽误事情。"}, "sentence_index": null, "correct_answer": "物质"}, "level_3": {"options": [{"text": "物质", "is_correct": true, "explanation": "物质：指可回收、可重复使用的物理材料，与“无限循环”的语境相合。"}, {"text": "价格", "is_correct": false, "explanation": "语义：价格与莫比乌斯环所暗示的循环无关，句子说的是材料的循环。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：“循环”一般不与“颜色”搭配，颜色也不能被“暗示”为无限循环。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：桌子是具体家具，不能作为抽象循环的对象。"}], "explanations": {"物质": "物质：指可回收、可重复使用的物理材料，与“无限循环”的语境相合。", "价格": "语义：价格与莫比乌斯环所暗示的循环无关，句子说的是材料的循环。", "颜色": "搭配：“循环”一般不与“颜色”搭配，颜色也不能被“暗示”为无限循环。", "桌子": "语义：桌子是具体家具，不能作为抽象循环的对象。"}, "sentence_index": 0, "correct_answer": "物质"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这件衣服的物质很好，穿起来很舒服。", "explanation": "这里应该用〈质地〉。“物质”指可回收利用的物理材料，这里用来说衣服面料的好坏，是误用的义项；说布料好坏要用“质地”。"}, {"text": "他不追求物质，只关心精神生活。", "explanation": "这里应该用〈财富〉。「物质」在这里指物质财富，不是可回收利用的材料。"}, {"text": "这只物质可以回收再利用。", "explanation": "这里应该用〈种〉。“物质”是一类材料，量词用“种”；“只”多用于动物或成对物品中的单个。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51d8e2bc-0184-4abe-ade1-561b8f69190c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12505, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "物质", "is_correct": true, "explanation": "物质（wù zhì）指可以被回收和重复使用的物理材料。"}, {"text": "武士", "is_correct": false, "explanation": "武士（wǔ shì）第一音节为第三声，第二音节声母为 sh（zhì 为 zh），意思是古代的战士。"}, {"text": "污渍", "is_correct": false, "explanation": "污渍（wū zì）第一音节为第一声，第二音节声母为 z（zhì 为 zh），意思是污迹。"}, {"text": "五指", "is_correct": false, "explanation": "五指（wǔ zhǐ）的声母和韵母都与物质（wù zhì）相同，但两个音节的声调不同（第三声对第四声），意思是五根手指。"}], "explanations": {"物质": "物质（wù zhì）指可以被回收和重复使用的物理材料。", "武士": "武士（wǔ shì）第一音节为第三声，第二音节声母为 sh（zhì 为 zh），意思是古代的战士。", "污渍": "污渍（wū zì）第一音节为第一声，第二音节声母为 z（zhì 为 zh），意思是污迹。", "五指": "五指（wǔ zhǐ）的声母和韵母都与物质（wù zhì）相同，但两个音节的声调不同（第三声对第四声），意思是五根手指。"}, "sentence_index": null, "correct_answer": "物质"}, "level_3": {"options": [{"text": "物质", "is_correct": true, "explanation": "物质：指可回收、可重复使用的物理材料，与“可以再用”相合。"}, {"text": "空气", "is_correct": false, "explanation": "语义：空气无法被回收站收集，也不是可以再用的物品。"}, {"text": "食品", "is_correct": false, "explanation": "语义：食品吃掉后就没有了，不能“再用”。"}, {"text": "时光", "is_correct": false, "explanation": "搭配：“收集”一般搭配具体物品，不说收集“时光”。"}], "explanations": {"物质": "物质：指可回收、可重复使用的物理材料，与“可以再用”相合。", "空气": "语义：空气无法被回收站收集，也不是可以再用的物品。", "食品": "语义：食品吃掉后就没有了，不能“再用”。", "时光": "搭配：“收集”一般搭配具体物品，不说收集“时光”。"}, "sentence_index": 6, "correct_answer": "物质"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他家境不好，物质条件很差，只好靠亲戚接济。", "explanation": "这里应该用〈经济条件〉。「物质条件」指生活的经济状况，不是可回收利用的材料。"}, {"text": "设计师用回收的旧布做物质，设计了一批包包。", "explanation": "这里应该用〈素材〉。“物质”指可回收利用的物理材料，用旧布做成包包的原料要说“素材”，不能说“做物质”。"}, {"text": "这条物质很旧，可以回收。", "explanation": "这里应该用〈种〉。“条”多用于细长的物件，“物质”是一类材料，量词用“种”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51d8e2bc-0184-4abe-ade1-561b8f69190c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12505, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "回收中心把收来的三只物质分开存放。", "corrected_sentence": "回收中心把收来的三种物质分开存放。", "error_description": "量词错误：“物质”指一类材料，应该用量词“种”，不能用“只”。正确说法是“三种物质”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51d8e2bc-0184-4abe-ade1-561b8f69190c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12505, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们以前回收着这种物质。", "corrected_sentence": "我们以前回收过这种物质。", "error_description": "体标错误：“以前”指过去的经历，表示曾经做过某事应用“过”，不能用表示持续的“着”。正确说法是“回收过这种物质”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51d8e2bc-0184-4abe-ade1-561b8f69190c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12506, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51d8e2bc-0184-4abe-ade1-561b8f69190c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12506, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51d8e2bc-0184-4abe-ade1-561b8f69190c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12506, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "指绘画、图形或物体表面细长而连续的痕迹或轮廓。", "primary_collocate": null, "pronunciation": "xiàn tiáo", "ipa": "ɕjɛn⁵¹ tʰjɑʊ³⁵", "syllable_count": 2, "sentences": [{"text": "经过公开征集，年轻平面设计师的提案最终胜出：三条首尾相连的箭头构成莫比乌斯环的变体，既暗示物质的无限循环，又通过动态线条传递持续运动的能量感。", "target_word": "线条", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "这幅画的线条很简单。", "target_word": "线条", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她用黑笔画出了清楚的线条。", "target_word": "线条", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这辆车的线条很漂亮。", "target_word": "线条", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说画人像时线条要流畅。", "target_word": "线条", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "墙上有一些弯弯的线条。", "target_word": "线条", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件衣服的线条让她显得很高。", "target_word": "线条", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子在纸上画了很多线条。", "target_word": "线条", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座楼的线条很直，看起来很现代。", "target_word": "线条", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "画家用细细的线条画出了山。", "target_word": "线条", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "線條", "label": "繁体"}], "register": "中性", "sense_fingerprint": "绘画、图形或物体表面细长连续的痕迹或轮廓", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3c7f2601-5d41-4e78-8d42-413e02a40644') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12506, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "线条", "is_correct": true, "explanation": "线条：指画面或物体表面细长连续的轮廓，与“动态”搭配，可以传递运动感。"}, {"text": "味道", "is_correct": false, "explanation": "语义：味道属于味觉，不能通过动态的设计来传递。"}, {"text": "面容", "is_correct": false, "explanation": "体貌：“面容”指人的脸，不能用于设计中的线条。"}, {"text": "温度", "is_correct": false, "explanation": "语义：温度是感觉的量，不能被画成可见的动态线条。"}], "explanations": {"线条": "线条：指画面或物体表面细长连续的轮廓，与“动态”搭配，可以传递运动感。", "味道": "语义：味道属于味觉，不能通过动态的设计来传递。", "面容": "体貌：“面容”指人的脸，不能用于设计中的线条。", "温度": "语义：温度是感觉的量，不能被画成可见的动态线条。"}, "sentence_index": 0, "correct_answer": "线条"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这根线条很长，可以拿来缝衣服。", "explanation": "这里应该用〈线〉。“线条”指画出或设计出的线，缝衣服的实物线要用“线”。"}, {"text": "这条公交线条很长，途经很多站。", "explanation": "这里应该用〈线路〉。“线条”指画面或物体表面的线痕，公交的走向要用“线路”。"}, {"text": "墙上有一座线条，很漂亮。", "explanation": "这里量词用错了，应该用〈条〉。线条是细长的痕迹，量词用“条”；“座”多用于山、楼、桥等大型物体。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51d8e2bc-0184-4abe-ade1-561b8f69190c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12506, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "线条", "is_correct": true, "explanation": "线条：指衣服的轮廓或设计线条，与“让她显得很高”的语境相合。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：衣服没有年龄，不能让人显得很高。"}, {"text": "名字", "is_correct": false, "explanation": "语义：衣服的名字不会让人显得很高。"}, {"text": "身高", "is_correct": false, "explanation": "搭配：“身高”只用于人或动物，不能说衣服的身高。"}], "explanations": {"线条": "线条：指衣服的轮廓或设计线条，与“让她显得很高”的语境相合。", "年龄": "语义：衣服没有年龄，不能让人显得很高。", "名字": "语义：衣服的名字不会让人显得很高。", "身高": "搭配：“身高”只用于人或动物，不能说衣服的身高。"}, "sentence_index": 6, "correct_answer": "线条"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "墙上拉着几根线条，通着电。", "explanation": "这里应该用〈电线〉。“线条”指画出或设计出的线痕，墙上通电的实物线要用“电线”。"}, {"text": "画家用细细的一块线条画出了山。", "explanation": "这里量词用错了，应该用〈条〉。“块”用于成块的东西，线条是细长的，应该用“条”。"}, {"text": "这条地铁线条明年开通。", "explanation": "这里应该用〈线路〉。“线条”指画面或物体表面的线痕，地铁的路线要用“线路”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51d8e2bc-0184-4abe-ade1-561b8f69190c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12506, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这幅素描里有三只线条很有力。", "corrected_sentence": "这幅素描里有三根线条很有力。", "error_description": "量词错误：“线条”是细长的痕迹，应该用量词“根”或“条”，不能用“只”。正确说法是“三根线条”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51d8e2bc-0184-4abe-ade1-561b8f69190c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12506, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "画家以前过画这样的线条。", "corrected_sentence": "画家以前画过这样的线条。", "error_description": "“过”的位置错误：动态助词“过”应紧跟动词，应说“画过”，不能放在动词之前。正确说法是“画过这样的线条”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51d8e2bc-0184-4abe-ade1-561b8f69190c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
