INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12509, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "形容事物非常细致、巧妙，达到很高的水平。", "primary_collocate": null, "pronunciation": "jīng miào", "ipa": "tɕiŋ˥ miaʊ˥˩", "syllable_count": 2, "sentences": [{"text": "在极端干旱的环境中，水资源的稀缺性催生了人类文明最为精妙的生存智慧。", "target_word": "精妙", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "此设计之精妙在于其多层次的象征意义——几何结构本身即是一种无需语言解释的全球通用语，而绿色的选择则强化了其与自然、生态的关联。", "target_word": "精妙", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这座古桥的设计非常精妙。", "target_word": "精妙", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他下棋的手法很精妙，我看不懂。", "target_word": "精妙", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这幅画的构思精妙，大家都夸它。", "target_word": "精妙", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "魔术师的手法精妙，观众根本看不出来。", "target_word": "精妙", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个钟表里的机关十分精妙。", "target_word": "精妙", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他用了一个精妙的办法解决问题。", "target_word": "精妙", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这首诗的用词精妙，读起来很美。", "target_word": "精妙", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师讲得很精妙，我一下子就懂了。", "target_word": "精妙", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "形容设计、手法、构思等细致巧妙、水平很高", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0c3d54eb-37c5-4193-8809-1266ef82ae7d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12509, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "笨重", "is_correct": false, "explanation": "搭配：“笨重”形容物体沉、不灵活，不能用来说“智慧”。"}, {"text": "鲜艳", "is_correct": false, "explanation": "体貌：“鲜艳”形容颜色，智慧没有颜色可言。"}, {"text": "任性", "is_correct": false, "explanation": "语义：“任性”形容人不听别人的，与人类文明中的生存智慧无关。"}, {"text": "精妙", "is_correct": true, "explanation": "“精妙”说智慧细致巧妙、水平很高，与句中“催生了……生存智慧”的语境相符。"}], "explanations": {"笨重": "搭配：“笨重”形容物体沉、不灵活，不能用来说“智慧”。", "鲜艳": "体貌：“鲜艳”形容颜色，智慧没有颜色可言。", "任性": "语义：“任性”形容人不听别人的，与人类文明中的生存智慧无关。", "精妙": "“精妙”说智慧细致巧妙、水平很高，与句中“催生了……生存智慧”的语境相符。"}, "sentence_index": 0, "correct_answer": "精妙"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个孩子很精妙，老师经常表扬他。", "explanation": "这里应该用〈聪明〉。精妙说手法、设计等巧妙，形容人机灵要用〈聪明〉。"}, {"text": "这根绳子很精妙，有三米长。", "explanation": "这里应该用〈长〉。精妙形容手法、构思的巧妙，不能用来说长度；说绳子有多长要用〈长〉。"}, {"text": "她很精妙，大家都愿意和她做朋友。", "explanation": "这里应该用〈善良〉。精妙不用于评价人的品性，说她心地好要用〈善良〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3d501c33-c21b-43f8-9ac6-864766fdbc5b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12509, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "温柔", "is_correct": false, "explanation": "搭配：“温柔”形容人的性情，不能用来形容机关。"}, {"text": "伤心", "is_correct": false, "explanation": "语义：“伤心”指人的情绪，机关没有感情，与句意不合。"}, {"text": "绿油油", "is_correct": false, "explanation": "体貌：“绿油油”形容颜色，不能用来描述机关的精巧程度。"}, {"text": "精妙", "is_correct": true, "explanation": "“精妙”说机关设计细致、巧妙，与句中“十分”所表示的程度评价相符。"}], "explanations": {"温柔": "搭配：“温柔”形容人的性情，不能用来形容机关。", "伤心": "语义：“伤心”指人的情绪，机关没有感情，与句意不合。", "绿油油": "体貌：“绿油油”形容颜色，不能用来描述机关的精巧程度。", "精妙": "“精妙”说机关设计细致、巧妙，与句中“十分”所表示的程度评价相符。"}, "sentence_index": 6, "correct_answer": "精妙"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的嗓门很精妙，隔壁都听得到。", "explanation": "这里应该用〈响亮〉。精妙说手法、构思，不能形容声音的大小；说嗓门大要用〈响亮〉。"}, {"text": "那个小伙子个子很精妙。", "explanation": "这里应该用〈高大〉。精妙形容巧妙的构思或手法，不能形容身材；形容个子高要用〈高大〉。"}, {"text": "这家店今天很精妙，没有几个客人。", "explanation": "这里应该用〈冷清〉。精妙不能描述店里人多人少；说店里人少要用〈冷清〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3d501c33-c21b-43f8-9ac6-864766fdbc5b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12509, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个办法比那个很精妙，大家都选它。", "corrected_sentence": "这个办法比那个精妙，大家都选它。", "error_description": "比较句中“比”后面不能再加“很”，“很”表示程度，与比较句的结构冲突；应去掉“很”，说“比那个精妙”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3d501c33-c21b-43f8-9ac6-864766fdbc5b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12509, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这位师傅把这只木鸟雕很精妙。", "corrected_sentence": "这位师傅把这只木鸟雕得很精妙。", "error_description": "表示程度的补语要用“动词+得+形容词”，应说“雕得很精妙”；“雕很精妙”漏掉了“得”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3d501c33-c21b-43f8-9ac6-864766fdbc5b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
