INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12511, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "指一种可以在全球多个国家和地区使用的通信服务或产品。", "primary_collocate": null, "pronunciation": "quán qiú tōng", "ipa": "tɕʰɥɛn˧˥ tɕʰjoʊ˧˥ tʰʊŋ˥", "syllable_count": 3, "sentences": [{"text": "经常出差的人一般会选择全球通，这样在多个国家都能保持联系。", "target_word": "全球通", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我用的是全球通，出国也能打电话。", "target_word": "全球通", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我办了全球通，出国也能用。", "target_word": "全球通", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "全球通在很多国家都能用。", "target_word": "全球通", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "去美国旅游前，他办了全球通。", "target_word": "全球通", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "爸爸用了十年全球通，一直没换号码。", "target_word": "全球通", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "全球通的信号很好。", "target_word": "全球通", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "你的手机是全球通吗？", "target_word": "全球通", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "朋友在国外工作，所以选了全球通。", "target_word": "全球通", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我打了很多国际电话，全球通的费用很高。", "target_word": "全球通", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "能在许多国家和地区使用的手机通信服务，常指办理或使用的这项服务", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3c7f2601-5d41-4e78-8d42-413e02a40644') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12511, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "全球通", "is_correct": true, "explanation": "正确：「全球通」指可在多个国家使用的通信服务，句中指选用的这项服务。"}, {"text": "固定电话", "is_correct": false, "explanation": "语义：固定电话装在固定地点，不能随人在多个国家使用，与句意不符。"}, {"text": "传呼机", "is_correct": false, "explanation": "语义：传呼机只能在有限范围内接收呼叫，无法在多个国家保持联系。"}, {"text": "雨伞", "is_correct": false, "explanation": "语义：雨伞与通信无关，选它无法保持联系。"}], "explanations": {"全球通": "正确：「全球通」指可在多个国家使用的通信服务，句中指选用的这项服务。", "固定电话": "语义：固定电话装在固定地点，不能随人在多个国家使用，与句意不符。", "传呼机": "语义：传呼机只能在有限范围内接收呼叫，无法在多个国家保持联系。", "雨伞": "语义：雨伞与通信无关，选它无法保持联系。"}, "sentence_index": 0, "correct_answer": "全球通"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我每天在全球通里吃早饭。", "explanation": "这里应该用〈厨房〉。全球通是通信服务，不是地点，「在……里」只能用于场所，不能用来表示吃饭的地方。"}, {"text": "这个全球通很宽，可以坐。", "explanation": "这里应该用〈沙发〉。全球通是通信服务，不能被形容为宽大、可以坐的家具。"}, {"text": "我昨天喝了一杯全球通。", "explanation": "这里应该用〈饮料〉。全球通是通信服务，不是饮料，不能用「喝」来搭配。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51d8e2bc-0184-4abe-ade1-561b8f69190c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12511, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "全球通", "is_correct": true, "explanation": "正确：「全球通」是一种通信服务，在句中作主语，表示它的信号很好。"}, {"text": "网速", "is_correct": false, "explanation": "搭配：「信号」与「网速」搭配不当，句中不说「网速的信号」。"}, {"text": "雨伞", "is_correct": false, "explanation": "语义：雨伞不是通信服务，不会有信号，与句子的主语不符。"}, {"text": "闹钟", "is_correct": false, "explanation": "语义：闹钟不是通信服务，说它的信号很好与事实不符。"}], "explanations": {"全球通": "正确：「全球通」是一种通信服务，在句中作主语，表示它的信号很好。", "网速": "搭配：「信号」与「网速」搭配不当，句中不说「网速的信号」。", "雨伞": "语义：雨伞不是通信服务，不会有信号，与句子的主语不符。", "闹钟": "语义：闹钟不是通信服务，说它的信号很好与事实不符。"}, "sentence_index": 6, "correct_answer": "全球通"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他在全球通上班。", "explanation": "这里应该用〈公司〉。「上班」要求工作场所，全球通是通信服务，不是地点。"}, {"text": "这道菜的全球通很好。", "explanation": "这里应该用〈味道〉。「很好」评价的是菜的口感，全球通是服务，不能用来评价菜。"}, {"text": "全球通今天特别温柔。", "explanation": "这里应该用〈人〉。「温柔」形容人的性情，全球通是服务，不能用来形容。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51d8e2bc-0184-4abe-ade1-561b8f69190c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12511, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我上周办了一台全球通，出国也能用。", "corrected_sentence": "我上周办了一张全球通，出国也能用。", "error_description": "「全球通」指通信服务，办理的是号卡，此处应用量词「张」，不能用「台」（机器）。应改为「一张全球通」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51d8e2bc-0184-4abe-ade1-561b8f69190c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12511, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他去美国前了办一张全球通，在那边很方便。", "corrected_sentence": "他去美国前办了一张全球通，在那边很方便。", "error_description": "「了」应放在动词「办」之后，表示动作完成，不能放在动词前面。应改为「办了一张全球通」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51d8e2bc-0184-4abe-ade1-561b8f69190c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
