INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12512, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指用词或措辞，即说话或写作时选择的词语。", "primary_collocate": null, "pronunciation": "yòng yǔ", "ipa": "jʊŋ˥˩ y˨˩˦", "syllable_count": 2, "sentences": [{"text": "这份学术报告的用语过于晦涩，普通读者难以理解。", "target_word": "用语", "complexity_tier": "T5", "sentence_source": "generated"}, {"text": "写信的时候，用语要有礼貌。", "target_word": "用语", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这篇文章的用语很准确。", "target_word": "用语", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "老师说，我们的用语要简单清楚。", "target_word": "用语", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的用语很客气，大家都喜欢。", "target_word": "用语", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "合同里的用语必须准确。", "target_word": "用语", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "新闻的用语要简单。", "target_word": "用语", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "请注意你的用语。", "target_word": "用语", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "法律文件的用语比日常说话更正式。", "target_word": "用语", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子的用语有时很可爱。", "target_word": "用语", "complexity_tier": "T1", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "说话或写作时所选用的词语和措辞，常评价是否准确、礼貌或正式", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3c7f2601-5d41-4e78-8d42-413e02a40644') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12512, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "用语", "is_correct": true, "explanation": "正确：用语 yòng yǔ，指说话或写作时选用的词语。"}, {"text": "用于", "is_correct": false, "explanation": "yú（第二声）与 yǔ（第三声）声调不同，yòng yú 意思是“用在……上”，不指选用的词语。"}, {"text": "用以", "is_correct": false, "explanation": "yǐ 与 yǔ 韵母不同（i 与 ü），意思是“用来”，表示目的，不是词语。"}, {"text": "勇于", "is_correct": false, "explanation": "yǒng 与 yòng 声调不同，yú 与 yǔ 声调也不同，意思是“敢于”，不是选用的词。"}], "explanations": {"用语": "正确：用语 yòng yǔ，指说话或写作时选用的词语。", "用于": "yú（第二声）与 yǔ（第三声）声调不同，yòng yú 意思是“用在……上”，不指选用的词语。", "用以": "yǐ 与 yǔ 韵母不同（i 与 ü），意思是“用来”，表示目的，不是词语。", "勇于": "yǒng 与 yòng 声调不同，yú 与 yǔ 声调也不同，意思是“敢于”，不是选用的词。"}, "sentence_index": null, "correct_answer": "用语"}, "level_3": {"options": [{"text": "用语", "is_correct": true, "explanation": "正确：指报告所用的词语；“晦涩”形容的正是用词难懂。"}, {"text": "口音", "is_correct": false, "explanation": "语义：口音指发音的腔调，不能用来说明报告用词的难懂程度。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气指气候状况，与报告的用词无关。"}, {"text": "身材", "is_correct": false, "explanation": "体貌：身材指人的体型，不能用来形容报告的用词。"}], "explanations": {"用语": "正确：指报告所用的词语；“晦涩”形容的正是用词难懂。", "口音": "语义：口音指发音的腔调，不能用来说明报告用词的难懂程度。", "天气": "语义：天气指气候状况，与报告的用词无关。", "身材": "体貌：身材指人的体型，不能用来形容报告的用词。"}, "sentence_index": 0, "correct_answer": "用语"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的用语很大。", "explanation": "这里应该用〈词汇量〉。用语指选用的词语，不指数量，不能说“用语很大”。"}, {"text": "这件衣服的用语很便宜。", "explanation": "这里应该用〈价格〉。用语指说话或写作时选用的词语，不指价钱，不能说“很便宜”。"}, {"text": "这幅画的用语很鲜艳。", "explanation": "这里应该用〈颜色〉。用语指选词，不能用来形容颜色鲜艳，应说“颜色很鲜艳”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51d8e2bc-0184-4abe-ade1-561b8f69190c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12512, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "用语", "is_correct": true, "explanation": "正确：指新闻所用的词语，要求简单。"}, {"text": "价格", "is_correct": false, "explanation": "语义：价格是金钱数额，不是可以“要简单”的表达方式。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色指色彩，不能用来说明新闻的表达要求。"}, {"text": "时间", "is_correct": false, "explanation": "搭配：“简单”修饰表达或文字，不能说“时间要简单”。"}], "explanations": {"用语": "正确：指新闻所用的词语，要求简单。", "价格": "语义：价格是金钱数额，不是可以“要简单”的表达方式。", "颜色": "语义：颜色指色彩，不能用来说明新闻的表达要求。", "时间": "搭配：“简单”修饰表达或文字，不能说“时间要简单”。"}, "sentence_index": 6, "correct_answer": "用语"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这台冰箱的用语很省电。", "explanation": "这里应该用〈耗电量〉。用语指选用的词语，不指耗电多少，不能说“很省电”。"}, {"text": "这道菜的用语很咸。", "explanation": "这里应该用〈味道〉。用语指选用的词语，不指味道，不能说“很咸”。"}, {"text": "这双鞋的用语很合脚。", "explanation": "这里应该用〈大小〉。用语指选用的词语，不能说鞋“合脚”，应说“这双鞋的大小很合脚”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51d8e2bc-0184-4abe-ade1-561b8f69190c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12512, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他用了一只礼貌的用语。", "corrected_sentence": "他用了一句礼貌的用语。", "error_description": "量词错误：“用语”是词语，应用“句”，不能用“只”（“只”多用于动物等）。正确说法是“一句礼貌的用语”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51d8e2bc-0184-4abe-ade1-561b8f69190c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12512, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她换了一只更礼貌的用语。", "corrected_sentence": "她换了一个更礼貌的用语。", "error_description": "量词错误：“用语”不用“只”（“只”多用于动物等），应用“个”。正确说法是“一个更礼貌的用语”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51d8e2bc-0184-4abe-ade1-561b8f69190c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
