INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12515, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "首先提出并号召他人参与的主张或行动。", "primary_collocate": null, "pronunciation": "chàng yì", "ipa": "ʈʂʰɑŋ˥˩ i˥˩", "syllable_count": 2, "sentences": [{"text": "尽管该标志最初仅为美国国内倡议服务，但其形式上的高度抽象性使其迅速跨越国界。", "target_word": "倡议", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "从城市规划的宏观视角审视，可持续性已从道德倡议转化为经济理性。", "target_word": "倡议", "complexity_tier": "T4", "sentence_source": "mined"}, {"text": "学校发出倡议，请同学们少用塑料袋。", "target_word": "倡议", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "市民积极响应保护河流的倡议。", "target_word": "倡议", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这项倡议得到了许多国家的支持。", "target_word": "倡议", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "联合国提出了一项新的环保倡议。", "target_word": "倡议", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司接受了员工提出的节能倡议。", "target_word": "倡议", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的倡议让大家开始重视健康。", "target_word": "倡议", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们都支持这个倡议。", "target_word": "倡议", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "社区发起了垃圾分类的倡议。", "target_word": "倡议", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "倡议书", "label": "复合"}, {"form": "倡议者", "label": "复合"}], "register": "书面", "sense_fingerprint": "率先提出并号召他人参与的主张或行动", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bf9d64f7-d6db-410b-8410-52799dc0c108') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12515, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "倡议", "is_correct": true, "explanation": "正确：倡议指首先建议或发起某种主张、行动。"}, {"text": "抗议", "is_correct": false, "explanation": "kàng 与 chàng 声母不同（k 与 ch），意思是抗议。"}, {"text": "长椅", "is_correct": false, "explanation": "cháng（第二声）与 chàng（第四声）声调不同，yǐ 与 yì 声调也不同，意思是长椅。"}, {"text": "长衣", "is_correct": false, "explanation": "cháng 与 chàng 声调不同，yī 与 yì 声调也不同，意思是长衣服。"}], "explanations": {"倡议": "正确：倡议指首先建议或发起某种主张、行动。", "抗议": "kàng 与 chàng 声母不同（k 与 ch），意思是抗议。", "长椅": "cháng（第二声）与 chàng（第四声）声调不同，yǐ 与 yì 声调也不同，意思是长椅。", "长衣": "cháng 与 chàng 声调不同，yī 与 yì 声调也不同，意思是长衣服。"}, "sentence_index": null, "correct_answer": "倡议"}, "level_3": {"options": [{"text": "倡议", "is_correct": true, "explanation": "正确：倡议指首先提出的主张或行动，与“为美国国内……服务”相符。"}, {"text": "海外", "is_correct": false, "explanation": "语义：海外指国外，与句中的“美国国内”正好相反。"}, {"text": "迅速", "is_correct": false, "explanation": "词性：“迅速”是形容词/副词，不能放在“国内”之后作“服务”的对象。"}, {"text": "国境", "is_correct": false, "explanation": "搭配：国境指国家边界，不能与“服务”搭配。"}], "explanations": {"倡议": "正确：倡议指首先提出的主张或行动，与“为美国国内……服务”相符。", "海外": "语义：海外指国外，与句中的“美国国内”正好相反。", "迅速": "词性：“迅速”是形容词/副词，不能放在“国内”之后作“服务”的对象。", "国境": "搭配：国境指国家边界，不能与“服务”搭配。"}, "sentence_index": 0, "correct_answer": "倡议"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这次调查的倡议显示，大多数学生都喜欢体育。", "explanation": "这里应该用〈结论〉。倡议指提出主张或发起行动，不指调查得出的结果。"}, {"text": "这家公司去年倡议了两款新手机。", "explanation": "这里应该用〈推出〉。倡议指提出主张或号召，不指公司把产品投放市场。"}, {"text": "我的倡议预测明天会下雨。", "explanation": "这里应该用〈预报〉。倡议指提出主张或号召，不用来说对天气的推断。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '99a869e5-d7c6-4cee-bf7b-58b3f659b231') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12515, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "倡议", "is_correct": true, "explanation": "正确：倡议指首先提出的主张或行动，与“公司接受了员工提出的……”的语境相符。"}, {"text": "嘲讽", "is_correct": false, "explanation": "语义：嘲讽指讥笑讽刺，与员工主动提出节能主张的语境不符。"}, {"text": "命令", "is_correct": false, "explanation": "语义：命令由上级发出，员工不能向公司下达命令，与句意不符。"}, {"text": "裁决", "is_correct": false, "explanation": "语义：裁决指裁定是非，与员工提出节能主张的语境不符。"}], "explanations": {"倡议": "正确：倡议指首先提出的主张或行动，与“公司接受了员工提出的……”的语境相符。", "嘲讽": "语义：嘲讽指讥笑讽刺，与员工主动提出节能主张的语境不符。", "命令": "语义：命令由上级发出，员工不能向公司下达命令，与句意不符。", "裁决": "语义：裁决指裁定是非，与员工提出节能主张的语境不符。"}, "sentence_index": 6, "correct_answer": "倡议"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "学校做出了一个倡议，全体学生都必须遵守。", "explanation": "这里应该用〈决定〉。倡议是号召他人自愿参与的主张，不带强制性，不能要求全体遵守。"}, {"text": "公司制定了一个倡议，下个月开始执行。", "explanation": "这里应该用〈计划〉。倡议是号召性的主张，不是按期执行的安排。"}, {"text": "老师发了一个倡议，要求大家周一交作业。", "explanation": "这里应该用〈通知〉。倡议用于号召自愿参与，不用于布置具体任务。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '99a869e5-d7c6-4cee-bf7b-58b3f659b231') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12515, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "社区发起了一只垃圾分类的倡议。", "corrected_sentence": "社区发起了一项垃圾分类的倡议。", "error_description": "错误：“只”用于动物或成对的物品，倡议的量词是“项”。正确形式为“一项垃圾分类的倡议”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '99a869e5-d7c6-4cee-bf7b-58b3f659b231') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12515, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "大家响应了环保组织的一把节水倡议。", "corrected_sentence": "大家响应了环保组织的一项节水倡议。", "error_description": "错误：“把”用于有柄的器物，倡议的量词应为“项”。正确形式为“一项节水倡议”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '99a869e5-d7c6-4cee-bf7b-58b3f659b231') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12517, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "规律", "is_correct": false, "explanation": "无关：规律指事物发展中稳定的联系，与抽象性的任何义项都不构成反义。"}, {"text": "具体性", "is_correct": true, "explanation": "反义：具体性指事物可以看见、触摸、感受的特点，与抽象性相对。"}, {"text": "程序", "is_correct": false, "explanation": "无关：程序指做事的先后步骤，不是抽象性的对立面。"}, {"text": "效率", "is_correct": false, "explanation": "无关：效率指单位时间内的产出，与抽象性没有反义关系。"}], "correct_answer": "具体性", "explanations": {"规律": "无关：规律指事物发展中稳定的联系，与抽象性的任何义项都不构成反义。", "具体性": "反义：具体性指事物可以看见、触摸、感受的特点，与抽象性相对。", "程序": "无关：程序指做事的先后步骤，不是抽象性的对立面。", "效率": "无关：效率指单位时间内的产出，与抽象性没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '212e2189-3a9b-4783-aacf-18bf5e476a5c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12517, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "矿石", "is_correct": false, "explanation": "无关：矿石指天然形成的矿物，与抽象性没有反义关系。"}, {"text": "厨房", "is_correct": false, "explanation": "无关：厨房是做饭的地方，与抽象性无关。"}, {"text": "具体性", "is_correct": true, "explanation": "反义：具体性指事物可以看见、触摸、感受的特点，与抽象性相对。"}, {"text": "电压", "is_correct": false, "explanation": "无关：电压是电路中的物理量，与抽象性无关。"}], "correct_answer": "具体性", "explanations": {"矿石": "无关：矿石指天然形成的矿物，与抽象性没有反义关系。", "厨房": "无关：厨房是做饭的地方，与抽象性无关。", "具体性": "反义：具体性指事物可以看见、触摸、感受的特点，与抽象性相对。", "电压": "无关：电压是电路中的物理量，与抽象性无关。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '212e2189-3a9b-4783-aacf-18bf5e476a5c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12517, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "property", "definition": "指事物中那些看不见、摸不着，但能通过思考来理解和把握的特点或性质，比如‘正义’、‘美丽’的概念。", "primary_collocate": null, "pronunciation": "chōu xiàng xìng", "ipa": "ʈʂʰoʊ˥ ɕjɑŋ˥˩ ɕiŋ˥˩", "syllable_count": 3, "sentences": [{"text": "尽管该标志最初仅为美国国内倡议服务，但其形式上的高度抽象性使其迅速跨越国界。", "target_word": "抽象性", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "数学语言的抽象性很强，初学者常常觉得难懂。", "target_word": "抽象性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "“自由”这个词的抽象性，让孩子很难理解。", "target_word": "抽象性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "哲学讨论的抽象性，来自它研究的是看不见的道理。", "target_word": "抽象性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师用图片降低了这个概念的抽象性。", "target_word": "抽象性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "法律条文的抽象性使普通人不容易读懂。", "target_word": "抽象性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了克服抽象性，作者举了很多生活中的例子。", "target_word": "抽象性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "因为抽象性强，这个理论需要用例子来说明。", "target_word": "抽象性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "语言学家认为，“时间”一词有很强的抽象性。", "target_word": "抽象性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这篇文章的抽象性很高，不是人人都能读懂。", "target_word": "抽象性", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "抽象性|看不见摸不着、靠思考把握的概念特点", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ce3cdbb2-6def-43dc-9a20-b31c9024b160') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12517, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "抽象性", "is_correct": true, "explanation": "正确。抽象性指看不见、摸不着、需靠思考把握的特点，“形式上的高度抽象性”使标志能脱离具体国家，因而迅速跨越国界。"}, {"text": "封闭性", "is_correct": false, "explanation": "语义：封闭性指不对外开放，与“迅速跨越国界”正相反，句子说不通。"}, {"text": "地域性", "is_correct": false, "explanation": "语义：地域性使事物局限于一个地方，与“跨越国界”矛盾。"}, {"text": "私密性", "is_correct": false, "explanation": "搭配：“私密性”多用于隐私、空间，不用来形容标志的形式或传播。"}], "explanations": {"抽象性": "正确。抽象性指看不见、摸不着、需靠思考把握的特点，“形式上的高度抽象性”使标志能脱离具体国家，因而迅速跨越国界。", "封闭性": "语义：封闭性指不对外开放，与“迅速跨越国界”正相反，句子说不通。", "地域性": "语义：地域性使事物局限于一个地方，与“跨越国界”矛盾。", "私密性": "搭配：“私密性”多用于隐私、空间，不用来形容标志的形式或传播。"}, "sentence_index": 0, "correct_answer": "抽象性"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这幅地图的抽象性很高，每条路和每栋楼都标得清清楚楚。", "explanation": "这里应该用〈具体性〉。地图标注的是看得见的路与楼，应说具体性高；抽象性指看不见、摸不着的概念特点。"}, {"text": "这个理论的抽象性很强，初学者一看就懂。", "explanation": "这里应该用〈通俗〉。通俗指浅显易懂；抽象性指不依赖具体形象的特点，与“一看就懂”相矛盾。"}, {"text": "这幅画的抽象性很强，一眼就能看出画的是谁。", "explanation": "这里应该用〈生动〉。生动指鲜明有画面感；抽象性指看不见、摸不着的特点，画中人物能一眼认出，与之相矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '212e2189-3a9b-4783-aacf-18bf5e476a5c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12517, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "抽象性", "is_correct": true, "explanation": "正确。抽象性是需要克服的理解障碍，“为了克服”正好接它。"}, {"text": "优越性", "is_correct": false, "explanation": "语义：优越性是优点，不是需要克服的困难，“克服优越性”说不通。"}, {"text": "便利性", "is_correct": false, "explanation": "语义：便利性是好处，人们不会想去克服它，句子说不通。"}, {"text": "美感", "is_correct": false, "explanation": "搭配：“克服”多接困难、障碍，不与“美感”搭配。"}], "explanations": {"抽象性": "正确。抽象性是需要克服的理解障碍，“为了克服”正好接它。", "优越性": "语义：优越性是优点，不是需要克服的困难，“克服优越性”说不通。", "便利性": "语义：便利性是好处，人们不会想去克服它，句子说不通。", "美感": "搭配：“克服”多接困难、障碍，不与“美感”搭配。"}, "sentence_index": 6, "correct_answer": "抽象性"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这部小说的抽象性很强，读者仿佛看到了人物。", "explanation": "这里应该用〈形象性〉。形象性指能让人想象出具体的样子，与“仿佛看到了人物”相符；抽象性不依赖具体形象，说不通。"}, {"text": "这张图表的抽象性很强，一眼就能看懂。", "explanation": "这里应该用〈直观性〉。直观性指一眼就能理解，抽象性与“一眼就能看懂”相矛盾。"}, {"text": "这种农具的抽象性很强，农民每天都在用。", "explanation": "这里应该用〈实用性〉。实用性指能直接用于生产生活；抽象性指看不见、摸不着的特点，农具是实物，与“每天都在用”不符。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '212e2189-3a9b-4783-aacf-18bf5e476a5c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12517, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这门课有一只很强的抽象性，学生常常需要反复练习。", "corrected_sentence": "这门课有一种很强的抽象性，学生常常需要反复练习。", "error_description": "“抽象性”前的量词用错：“只”多用于动物或成对物品之一，应改为“种”，即“一种很强的抽象性”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '212e2189-3a9b-4783-aacf-18bf5e476a5c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12517, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这套理论的抽象性高很，需要慢慢理解。", "corrected_sentence": "这套理论的抽象性很高，需要慢慢理解。", "error_description": "语序错误：程度副词“很”应放在形容词“高”前，应说“抽象性很高”，不能说“高很”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '212e2189-3a9b-4783-aacf-18bf5e476a5c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
