INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12523, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "工序", "is_correct": false, "explanation": "无关：工序指生产中的一道道步骤，与趋同没有反义关系。"}, {"text": "途径", "is_correct": false, "explanation": "无关：途径指到达目的的路线或方法，与趋同无关。"}, {"text": "氛围", "is_correct": false, "explanation": "无关：氛围指周围的气氛，与趋同无关。"}, {"text": "趋异", "is_correct": true, "explanation": "反义：趋异指事物朝不同方向发展，与趋同相对。"}], "correct_answer": "趋异", "explanations": {"工序": "无关：工序指生产中的一道道步骤，与趋同没有反义关系。", "途径": "无关：途径指到达目的的路线或方法，与趋同无关。", "氛围": "无关：氛围指周围的气氛，与趋同无关。", "趋异": "反义：趋异指事物朝不同方向发展，与趋同相对。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '212e2189-3a9b-4783-aacf-18bf5e476a5c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12523, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "abstract", "definition": "指不同的事物或现象向相同的方向发展或演变。", "primary_collocate": null, "pronunciation": "qū tóng", "ipa": "tɕʰy˥ tʰʊŋ˧˥", "syllable_count": 2, "sentences": [{"text": "至1980年代，随着跨国供应链的扩展与环保法规的趋同，这一标志已出现在欧洲、东亚及南美洲的各类包装物上，演变为事实上的国际惯例。", "target_word": "趋同", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "两国的饮食习惯出现了趋同。", "target_word": "趋同", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "全球化让各国的文化出现趋同的现象。", "target_word": "趋同", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手机的外形设计越来越趋同。", "target_word": "趋同", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "专家认为，城市建设的趋同会让城市失去特点。", "target_word": "趋同", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "市场竞争使不同企业的产品趋同。", "target_word": "趋同", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两种语言在长期接触中，语法出现了趋同。", "target_word": "趋同", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经济发展水平的趋同，有利于地区合作。", "target_word": "趋同", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学者发现，不同地区的教育标准正在趋同。", "target_word": "趋同", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "各大银行的服务正在走向趋同。", "target_word": "趋同", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "趨同", "label": "繁体"}, {"form": "趋同化", "label": "复合"}, {"form": "趋同性", "label": "复合"}], "register": "书面", "sense_fingerprint": "趋同|不同的事物或现象向相同方向发展演变", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ce3cdbb2-6def-43dc-9a20-b31c9024b160') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12523, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "趋同", "is_correct": true, "explanation": "正确。趋同指不同事物向相同方向发展，与句中“演变为国际惯例”吻合。"}, {"text": "分裂", "is_correct": false, "explanation": "语义：分裂与“扩展”和“国际惯例”的走向相反，句子说不通。"}, {"text": "隔离", "is_correct": false, "explanation": "语义：隔离会阻断传播，与标志出现在各地、成为惯例相矛盾。"}, {"text": "垄断", "is_correct": false, "explanation": "搭配：“法规”不与“垄断”搭配，且垄断不能形成国际惯例。"}], "explanations": {"趋同": "正确。趋同指不同事物向相同方向发展，与句中“演变为国际惯例”吻合。", "分裂": "语义：分裂与“扩展”和“国际惯例”的走向相反，句子说不通。", "隔离": "语义：隔离会阻断传播，与标志出现在各地、成为惯例相矛盾。", "垄断": "搭配：“法规”不与“垄断”搭配，且垄断不能形成国际惯例。"}, "sentence_index": 0, "correct_answer": "趋同"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这几家工厂趋同复工，市场一下子热闹起来。", "explanation": "这里应该用〈同时〉。同时指在同一时间发生；趋同强调不同事物逐渐靠拢的过程，不能用来描述同一时间的复工。"}, {"text": "双胞胎的脸型很趋同，连家人都难分辨。", "explanation": "这里应该用〈相似〉。趋同指不同事物朝同一方向靠拢的过程，描述已经很像的状态用相似。"}, {"text": "他的性格越来越趋同。", "explanation": "这里应该用〈变化〉。趋同需要两个以上不同的事物朝同一方向靠拢，只说一个人的性格，不能用趋同。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '212e2189-3a9b-4783-aacf-18bf5e476a5c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12523, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "趋同", "is_correct": true, "explanation": "正确。两种语言长期接触后，语法向相同方向靠拢，正是“趋同”的意思。"}, {"text": "寿命", "is_correct": false, "explanation": "搭配：“寿命”指存在的时间，语法不说“出现了寿命”。"}, {"text": "价格", "is_correct": false, "explanation": "语义：价格是商品的钱数，语法没有价格，句子说不通。"}, {"text": "重量", "is_correct": false, "explanation": "语义：重量是物体的属性，语法不具有重量，句子说不通。"}], "explanations": {"趋同": "正确。两种语言长期接触后，语法向相同方向靠拢，正是“趋同”的意思。", "寿命": "搭配：“寿命”指存在的时间，语法不说“出现了寿命”。", "价格": "语义：价格是商品的钱数，语法没有价格，句子说不通。", "重量": "语义：重量是物体的属性，语法不具有重量，句子说不通。"}, "sentence_index": 6, "correct_answer": "趋同"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "两家公司合作多年，技术终于趋同成一体。", "explanation": "这里应该用〈融合〉。融合指合为一体；趋同只指朝相同方向靠拢，不能说“成一体”。"}, {"text": "两家商店的销量瞬间趋同，老板们都很焦急。", "explanation": "这里应该用〈同步〉。趋同指逐渐靠拢的过程，不能与“瞬间”搭配；同时发生的变化应说〈同步〉。"}, {"text": "我的爱好越来越趋同。", "explanation": "这里应该用〈改变〉。趋同需要多个不同事物靠拢，单独一个人的爱好不能用趋同。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '212e2189-3a9b-4783-aacf-18bf5e476a5c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12523, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这两家公司的价格越来越被趋同，消费者很难选择。", "corrected_sentence": "这两家公司的价格越来越趋同，消费者很难选择。", "error_description": "“趋同”是不及物动词，不能用“被”字句表示被动。应去掉“被”，说“价格越来越趋同”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '212e2189-3a9b-4783-aacf-18bf5e476a5c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12523, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这套标准逐渐趋同国际水平，企业更容易合作。", "corrected_sentence": "这套标准逐渐趋同于国际水平，企业更容易合作。", "error_description": "介词“于”漏掉：“趋同”后要接“于”，应说“趋同于国际水平”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '212e2189-3a9b-4783-aacf-18bf5e476a5c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
