INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12524, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "用于包装商品或物品的材料或容器，如纸箱、塑料袋等。", "primary_collocate": null, "pronunciation": "bāo zhuāng wù", "ipa": "pɑʊ˥ ʈʂwɑŋ˥ u˥˩", "syllable_count": 3, "sentences": [{"text": "至1980年代，随着跨国供应链的扩展与环保法规的趋同，这一标志已出现在欧洲、东亚及南美洲的各类包装物上，演变为事实上的国际惯例。", "target_word": "包装物", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "这些包装物可以回收再用。", "target_word": "包装物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "快递员把包装物放进了垃圾桶。", "target_word": "包装物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "商店要求顾客少用塑料包装物。", "target_word": "包装物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种包装物是纸做的，对环境好。", "target_word": "包装物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "拆开包裹后，请把包装物扔到回收箱里。", "target_word": "包装物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "食品的包装物上要写清生产日期。", "target_word": "包装物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "过多的包装物会增加垃圾。", "target_word": "包装物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我把旧包装物留着，搬家时还能用。", "target_word": "包装物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工厂每年生产大量的包装物。", "target_word": "包装物", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "包裝物", "label": "繁体"}], "register": "中性", "sense_fingerprint": "包装物|用来包装商品的材料或容器，如纸箱、塑料袋", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ce3cdbb2-6def-43dc-9a20-b31c9024b160') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12524, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "包装物", "is_correct": true, "explanation": "正确：“包装物”指包装商品用的材料或容器，标志可以印在上面。"}, {"text": "人物", "is_correct": false, "explanation": "语义：“人物”指人，标志不会印在人身上，与商品包装的语境不符。"}, {"text": "植物", "is_correct": false, "explanation": "语义：标志印在植物上不合常理，句中指的是商品的包装。"}, {"text": "天空", "is_correct": false, "explanation": "搭配：“各类天空上”不能这样说，天空不是可以印标志的物体。"}], "explanations": {"包装物": "正确：“包装物”指包装商品用的材料或容器，标志可以印在上面。", "人物": "语义：“人物”指人，标志不会印在人身上，与商品包装的语境不符。", "植物": "语义：标志印在植物上不合常理，句中指的是商品的包装。", "天空": "搭配：“各类天空上”不能这样说，天空不是可以印标志的物体。"}, "sentence_index": 0, "correct_answer": "包装物"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个人的包装物很好。", "explanation": "这里应该用〈外表〉。包装物指包装商品用的材料或容器，不能用来说人的外表。"}, {"text": "他开着一个包装物去上班。", "explanation": "这里应该用〈汽车〉。包装物是包装商品的材料或容器，不能用来开，“开”的对象应是车辆。"}, {"text": "他是一个会包装物的人。", "explanation": "这里应该用〈包装〉作动词。包装物是名词，指物品，不能用作“包装”这个动作。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '212e2189-3a9b-4783-aacf-18bf5e476a5c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12524, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "包装物", "is_correct": true, "explanation": "正确：食品包装上写生产日期是常见的做法，“包装物”指包装用的材料或容器。"}, {"text": "人", "is_correct": false, "explanation": "语义：“食品的人”说不通，人不是印写生产日期的物品。"}, {"text": "厨房", "is_correct": false, "explanation": "语义：厨房是房间，不是可以写生产日期的物体。"}, {"text": "河流", "is_correct": false, "explanation": "搭配：“食品的河流”不能这样说，河流与“食品”没有搭配关系。"}], "explanations": {"包装物": "正确：食品包装上写生产日期是常见的做法，“包装物”指包装用的材料或容器。", "人": "语义：“食品的人”说不通，人不是印写生产日期的物品。", "厨房": "语义：厨房是房间，不是可以写生产日期的物体。", "河流": "搭配：“食品的河流”不能这样说，河流与“食品”没有搭配关系。"}, "sentence_index": 6, "correct_answer": "包装物"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我每天喝大量的包装物。", "explanation": "这里应该用〈饮料〉。包装物是装东西的材料或容器，不能用来喝；“喝”的对象应是饮料。"}, {"text": "他每天穿不同的包装物。", "explanation": "这里应该用〈衣服〉。包装物不能穿在身上；“穿”的对象应是衣服。"}, {"text": "他每天吃很多包装物。", "explanation": "这里应该用〈食物〉。包装物是包裹商品的材料，不能用来吃；“吃”的对象应是食物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '212e2189-3a9b-4783-aacf-18bf5e476a5c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12524, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "工厂换了一只新的包装物。", "corrected_sentence": "工厂换了一种新的包装物。", "error_description": "量词错误：“包装物”应搭配“种”或“个”，“只”用于动物或成对物品中的一件，不能用于包装物。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '212e2189-3a9b-4783-aacf-18bf5e476a5c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12524, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这些包装物都堆很整齐。", "corrected_sentence": "这些包装物都堆得很整齐。", "error_description": "补语前漏了“得”：“堆”后的补语要用“堆得很整齐”，不能直接说“堆很整齐”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '212e2189-3a9b-4783-aacf-18bf5e476a5c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
