INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12525, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "用来表示所说的话是真实的，相当于‘实际上’。", "primary_collocate": null, "pronunciation": "shì shí shàng", "ipa": "ʂɻ̩˥˩ ʂɻ̩˧˥ ʂɑŋ˥˩", "syllable_count": 3, "sentences": [{"text": "至1980年代，随着跨国供应链的扩展与环保法规的趋同，这一标志已出现在欧洲、东亚及南美洲的各类包装物上，事实上已演变为国际惯例。", "target_word": "事实上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条路看着很远，事实上走十分钟就到了。", "target_word": "事实上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说得对，事实上我们真的没有认真复习。", "target_word": "事实上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很多人觉得汉字难，事实上只要多写就能记住。", "target_word": "事实上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家都以为他不懂，事实上他比谁都清楚。", "target_word": "事实上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "外面看着很旧，事实上这房子刚盖好两年。", "target_word": "事实上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你以为他不知道？事实上他早就听说了。", "target_word": "事实上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "人人都说这里安全，事实上也确实没出过事。", "target_word": "事实上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他嘴上说不喜欢，事实上天天都在用这个手机。", "target_word": "事实上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "事实上，这家公司去年就已经搬到上海了。", "target_word": "事实上", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "强调所说的内容是实际情况，相当于“实际上”", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ce3cdbb2-6def-43dc-9a20-b31c9024b160') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12525, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "事实上", "is_correct": true, "explanation": "正确：“事实上”引出已经发生的实际情况，与“已演变为国际惯例”吻合。"}, {"text": "短暂", "is_correct": false, "explanation": "语义：“短暂”指持续时间不长，与“惯例”需要长期稳定的意思相矛盾。"}, {"text": "个人", "is_correct": false, "explanation": "语义：“个人”指单独的人，与“国际”相矛盾。"}, {"text": "喜欢", "is_correct": false, "explanation": "搭配：“喜欢”不能用来说明惯例的演变，句子说不通。"}], "explanations": {"事实上": "正确：“事实上”引出已经发生的实际情况，与“已演变为国际惯例”吻合。", "短暂": "语义：“短暂”指持续时间不长，与“惯例”需要长期稳定的意思相矛盾。", "个人": "语义：“个人”指单独的人，与“国际”相矛盾。", "喜欢": "搭配：“喜欢”不能用来说明惯例的演变，句子说不通。"}, "sentence_index": 0, "correct_answer": "事实上"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "请大家事实上保持安静。", "explanation": "这里不能用〈事实上〉。“事实上”表示所说的是真实情况（相当于〈实际上〉），不能用在要求别人做事的句子里，这里应去掉“事实上”。"}, {"text": "如果明天下雨，事实上我们就不去了。", "explanation": "这里不能用〈事实上〉。“事实上”表示已经存在或已经确定的真实情况（相当于〈实际上〉），而假设句陈述的不是真实情况，应去掉“事实上”。"}, {"text": "他事实上地说出了那天发生的事。", "explanation": "这里应该用〈如实〉。“事实上”是表示“实际上”的插入性副词，不能加“地”描写动作方式；按真实情况说应用“如实地”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '212e2189-3a9b-4783-aacf-18bf5e476a5c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12525, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "事实上", "is_correct": true, "explanation": "正确：“事实上”引出真实情况，与“你以为他不知道”形成对比，后面说他早就听说了。"}, {"text": "突然", "is_correct": false, "explanation": "语义：“突然”指忽然发生，与“早就”表示很久以前已经发生的意思相矛盾。"}, {"text": "偶尔", "is_correct": false, "explanation": "语义：“偶尔”指不常发生，与“早就”表示已经发生相矛盾。"}, {"text": "赶紧", "is_correct": false, "explanation": "搭配：“赶紧”表示急忙去做，与“早就”表示已经发生的意思不能搭配。"}], "explanations": {"事实上": "正确：“事实上”引出真实情况，与“你以为他不知道”形成对比，后面说他早就听说了。", "突然": "语义：“突然”指忽然发生，与“早就”表示很久以前已经发生的意思相矛盾。", "偶尔": "语义：“偶尔”指不常发生，与“早就”表示已经发生相矛盾。", "赶紧": "搭配：“赶紧”表示急忙去做，与“早就”表示已经发生的意思不能搭配。"}, "sentence_index": 6, "correct_answer": "事实上"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们事实上先吃饭，再去看电影。", "explanation": "这里不能用〈事实上〉。“事实上”只表示所说的是真实情况（相当于〈实际上〉），不表示动作的先后，应去掉“事实上”。"}, {"text": "我希望事实上明天不要下雨。", "explanation": "这里不能用〈事实上〉。“事实上”陈述已有的真实情况，不能用在表示愿望的句子里，应去掉。"}, {"text": "请你事实上地填写这张表。", "explanation": "这里应该用〈如实〉。要求按真实情况做事用“如实地”；“事实上”只用来引出实际情况，不修饰动作方式。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '212e2189-3a9b-4783-aacf-18bf5e476a5c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12525, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这种做法很事实上已成为标准。", "corrected_sentence": "这种做法事实上已成为标准。", "error_description": "“事实上”是副词，不能与程度副词“很”叠用，应去掉“很”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '212e2189-3a9b-4783-aacf-18bf5e476a5c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12525, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老板说没人加班，很事实上大家都在加班。", "corrected_sentence": "老板说没人加班，事实上大家都在加班。", "error_description": "“事实上”是副词，不能被程度副词“很”修饰，应去掉“很”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '212e2189-3a9b-4783-aacf-18bf5e476a5c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
