INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12527, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指将事物根据特定地区的文化、语言、习惯等进行调整，使其更容易被当地人接受和使用。", "primary_collocate": null, "pronunciation": "běn tǔ huà", "ipa": "pən˨˩˦ tʰu˨˩˦ xua˥˩", "syllable_count": 3, "sentences": [{"text": "值得注意的是，其普及过程并非线性推进，而是伴随着各国本土化调整：例如在某些文化语境中，箭头形态被微调以避免宗教联想；而在另一些地区，则附加数字编码系统以细化分类标准。", "target_word": "本土化", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这家公司很重视产品的本土化。", "target_word": "本土化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这款游戏的本土化做得很好。", "target_word": "本土化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电影的本土化让更多观众看懂了故事。", "target_word": "本土化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "快餐店的本土化，就是菜单加入当地口味。", "target_word": "本土化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "软件本土化需要翻译，还要符合当地习惯。", "target_word": "本土化", "complexity_tier": "T3", "furigana": "běntǔhuà", "sentence_source": "generated"}, {"text": "他研究外国连锁店在中国的本土化。", "target_word": "本土化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家公司的本土化过程用了三年。", "target_word": "本土化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "本土化是外国品牌成功的重要一步。", "target_word": "本土化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个品牌的本土化已经完成了。", "target_word": "本土化", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "本土化策略", "label": "复合"}], "register": "中性", "sense_fingerprint": "本土化|名词|外来事物按当地文化习惯调整的过程", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '05657b60-f4ba-43e6-a05f-48f26d97bd9f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12527, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "本土化", "is_correct": true, "explanation": "正确：本土化指按当地文化、习惯调整事物，句中的例子（箭头形态、宗教联想）正是文化层面的调整。"}, {"text": "商业化", "is_correct": false, "explanation": "语义：句中的例子讲的是文化语境中的调整，不是商业化。"}, {"text": "工业化", "is_correct": false, "explanation": "语义：句中强调的是文化与分类标准，不涉及生产方式的工业化。"}, {"text": "城镇化", "is_correct": false, "explanation": "语义：句中的例子与城镇发展无关，“城镇化调整”无法解释后面的宗教联想例子。"}], "explanations": {"本土化": "正确：本土化指按当地文化、习惯调整事物，句中的例子（箭头形态、宗教联想）正是文化层面的调整。", "商业化": "语义：句中的例子讲的是文化语境中的调整，不是商业化。", "工业化": "语义：句中强调的是文化与分类标准，不涉及生产方式的工业化。", "城镇化": "语义：句中的例子与城镇发展无关，“城镇化调整”无法解释后面的宗教联想例子。"}, "sentence_index": 0, "correct_answer": "本土化"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这座老城的本土化越来越明显，街上全是咖啡馆。", "explanation": "这里应该用〈西化〉。本土化指使事物适应当地，街上全是咖啡馆说明的是外来风格增多，要用西化。"}, {"text": "这家餐厅把菜单全换成了英文，本土化得很彻底。", "explanation": "这里应该用〈国际化〉。本土化指适应当地，菜单全换成英文是面向外国顾客，要用国际化。"}, {"text": "这座山的本土化让它的海拔升高了一百米。", "explanation": "这里应该用〈隆起〉。本土化指使事物适应当地的文化习惯，山体海拔升高是地壳运动，要用隆起。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2df51fa8-9f4e-4e02-8622-3dbc11859208') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12527, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "本土化", "is_correct": true, "explanation": "正确：本土化指使外国事物适应中国的情况，“外国连锁店在中国的本土化”符合这一意思。"}, {"text": "老龄化", "is_correct": false, "explanation": "语义：老龄化指人口年龄结构的变化，不能用来说连锁店。"}, {"text": "脱水", "is_correct": false, "explanation": "语义：脱水指去除水分，与研究连锁店无关，句中说不通。"}, {"text": "学术化", "is_correct": false, "explanation": "搭配：学术化多用于研究方法或领域，不说“连锁店的学术化”。"}], "explanations": {"本土化": "正确：本土化指使外国事物适应中国的情况，“外国连锁店在中国的本土化”符合这一意思。", "老龄化": "语义：老龄化指人口年龄结构的变化，不能用来说连锁店。", "脱水": "语义：脱水指去除水分，与研究连锁店无关，句中说不通。", "学术化": "搭配：学术化多用于研究方法或领域，不说“连锁店的学术化”。"}, "sentence_index": 6, "correct_answer": "本土化"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家公司正在推进本土化，把中国的工厂全部关闭了。", "explanation": "这里应该用〈撤出〉。本土化指适应当地、扎根当地，关闭中国的工厂是撤出，要用撤出。"}, {"text": "这个小镇正在推进本土化，新楼越来越多。", "explanation": "这里应该用〈城市化〉。本土化讲的是适应当地，新楼增多、人口聚集是城市化的过程。"}, {"text": "这家公司的业务本土化了，在十个国家全都停业了。", "explanation": "这里应该用〈退出〉。本土化强调适应当地、扎根当地，在十个国家全部停业是退出市场，要用退出。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2df51fa8-9f4e-4e02-8622-3dbc11859208') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12527, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只本土化很成功。", "corrected_sentence": "这次本土化很成功。", "error_description": "错误：量词用了“只”。正确：应用“次”。本土化指一个过程，过程用“次”计量；“只”用于动物或成对的东西，不能用于本土化。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2df51fa8-9f4e-4e02-8622-3dbc11859208') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12527, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这家公司的本土化了很有必要。", "corrected_sentence": "这家公司的本土化很有必要。", "error_description": "错误：“本土化”后面多了“了”。正确：去掉“了”。作名词的“本土化”表示过程，后面不能直接加“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2df51fa8-9f4e-4e02-8622-3dbc11859208') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
