INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12530, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2df51fa8-9f4e-4e02-8622-3dbc11859208') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12530, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "由当前事物想到与之相关的其他事物或想法。", "primary_collocate": null, "pronunciation": "lián xiǎng", "ipa": "lien˧˥ ɕiɑŋ˨˩˦", "syllable_count": 2, "sentences": [{"text": "看到红叶，我联想到了秋天。", "target_word": "联想", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这首歌让他联想到小时候的家。", "target_word": "联想", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "闻到咖啡香，她会联想到那家小店。", "target_word": "联想", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听到“海”这个字，你会联想到什么？", "target_word": "联想", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师让学生看图片，再由图片联想到一个故事。", "target_word": "联想", "complexity_tier": "T3", "furigana": "lǎo shī ràng xué shēng kàn tú piàn, zài yóu tú piàn lián xiǎng dào yí gè gù shi.", "sentence_source": "generated"}, {"text": "看着旧照片，奶奶联想起年轻的日子。", "target_word": "联想", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个名字让人联想到一种水果。", "target_word": "联想", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子看见云，联想到一只大白兔。", "target_word": "联想", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一提到北京，我就联想到长城。", "target_word": "联想", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他看到那辆旧车，联想到了爷爷。", "target_word": "联想", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "联想了", "label": "体标"}, {"form": "联想过", "label": "体标"}, {"form": "聯想", "label": "繁体"}], "register": "中性", "sense_fingerprint": "联想|动词|由眼前事物想到相关的其他事物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '05657b60-f4ba-43e6-a05f-48f26d97bd9f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12530, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "联想", "is_correct": true, "explanation": "“联想”指由眼前的红叶想到相关的秋天，与句中“看到红叶”的语境吻合。"}, {"text": "摘", "is_correct": false, "explanation": "搭配：“摘”的宾语须是可摘取的具体物件，“秋天”不能被摘到。"}, {"text": "搬", "is_correct": false, "explanation": "语义：“搬”指移动具体的东西，不能用来指向时间。"}, {"text": "思忖", "is_correct": false, "explanation": "语域：“思忖”偏书面，后面通常接一段思考的内容，用在这样的口语叙述里不协调。"}], "explanations": {"联想": "“联想”指由眼前的红叶想到相关的秋天，与句中“看到红叶”的语境吻合。", "摘": "搭配：“摘”的宾语须是可摘取的具体物件，“秋天”不能被摘到。", "搬": "语义：“搬”指移动具体的东西，不能用来指向时间。", "思忖": "语域：“思忖”偏书面，后面通常接一段思考的内容，用在这样的口语叙述里不协调。"}, "sentence_index": 0, "correct_answer": "联想"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈联想了一碗面条，给我们做晚饭。", "explanation": "这里应该用〈煮〉。联想是想到别的事物，不能用来做饭，煮面要用煮。"}, {"text": "工人们一起联想了那座老桥，然后把它拆掉了。", "explanation": "这里应该用〈拆除〉。联想是想到别的事物，不能用来拆桥，拆除建筑要用拆除。"}, {"text": "我联想他明天一定会来。", "explanation": "这里应该用〈猜测〉。联想不能用来对将要发生的事作判断，对将来的事作猜测要用猜测。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2df51fa8-9f4e-4e02-8622-3dbc11859208') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12530, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "联想", "is_correct": true, "explanation": "“联想”指由“这个名字”引出想到的事物，与句中“让人”的语境相符。"}, {"text": "品尝", "is_correct": false, "explanation": "搭配：“品尝”的对象是食物或味道，“名字”不能被品尝。"}, {"text": "嗅", "is_correct": false, "explanation": "语义：“嗅”是用鼻子闻气味，名字没有气味，句中说不通。"}, {"text": "揣度", "is_correct": false, "explanation": "语域：“揣度”是书面词，要接一个判断性的内容，与这里的叙述不协调。"}], "explanations": {"联想": "“联想”指由“这个名字”引出想到的事物，与句中“让人”的语境相符。", "品尝": "搭配：“品尝”的对象是食物或味道，“名字”不能被品尝。", "嗅": "语义：“嗅”是用鼻子闻气味，名字没有气味，句中说不通。", "揣度": "语域：“揣度”是书面词，要接一个判断性的内容，与这里的叙述不协调。"}, "sentence_index": 6, "correct_answer": "联想"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他常常联想远方的妈妈，一有空就飞去看她。", "explanation": "这里应该用〈探望〉。联想是想到别的事物，不能表示专程去看望亲人，那要用探望。"}, {"text": "作家正在联想新书的封面，请画家帮忙画。", "explanation": "这里应该用〈设计〉。联想是想到别的事物，不能用来表示请人画封面，设计封面要用设计。"}, {"text": "警察用卷尺联想凶手的身高。", "explanation": "这里应该用〈测量〉。联想是由事物想到相关的事，不能用卷尺量取身高；量出身高要用测量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2df51fa8-9f4e-4e02-8622-3dbc11859208') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12530, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "听见雨声，我联想在了夏天的池塘。", "corrected_sentence": "听见雨声，我联想到了夏天的池塘。", "error_description": "错误：“联想在”；正确：“联想到”。“联想”后面要用介词“到”引出被想到的事物，不能用“在”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2df51fa8-9f4e-4e02-8622-3dbc11859208') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12530, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "看到那只小狗，我联想了我的童年。", "corrected_sentence": "看到那只小狗，我联想到了我的童年。", "error_description": "错误：缺少介词“到”。正确：“联想”后面要用“到”引出被想到的事物，应说“联想到了我的童年”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2df51fa8-9f4e-4e02-8622-3dbc11859208') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12531, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2df51fa8-9f4e-4e02-8622-3dbc11859208') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12531, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2df51fa8-9f4e-4e02-8622-3dbc11859208') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12531, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "指在主要或基本内容之外，另外加上、补充或附带提供的东西或行为。", "primary_collocate": null, "pronunciation": "fù jiā", "ipa": "fu˥˩ tɕja˥", "syllable_count": 2, "sentences": [{"text": "合同里除了价格，还附加了一个条件。", "target_word": "附加", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老板在工资之外，没有附加任何要求。", "target_word": "附加", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家店在价格之外，另外附加了送货费。", "target_word": "附加", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "信写完以后，他又附加了一句说明。", "target_word": "附加", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他同意帮忙，但是另外附加了两个条件。", "target_word": "附加", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师在作业后面附加了一道难题。", "target_word": "附加", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "买机票时，不要再附加别的服务了。", "target_word": "附加", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们把这条规定附加在合同的最后。", "target_word": "附加", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "银行在这项服务上附加过很多限制。", "target_word": "附加", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在邮件正文之外，又附加了一张照片。", "target_word": "附加", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "附加了", "label": "体标"}, {"form": "附加过", "label": "体标"}, {"form": "附加条件", "label": "复合"}, {"form": "附加费", "label": "复合"}], "register": "书面", "sense_fingerprint": "附加：在主要内容之外另加条件、说明或费用", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '05657b60-f4ba-43e6-a05f-48f26d97bd9f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12531, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "附加", "is_correct": true, "explanation": "“附加”表示在价格之外另加一个条件，与句中“除了价格，还”相合。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”的宾语须是食物，条件不能被吃。"}, {"text": "吐", "is_correct": false, "explanation": "语义：“吐”指把东西从口中排出，与条件无关，句中说不通。"}, {"text": "赐予", "is_correct": false, "explanation": "语域：“赐予”带有上对下施予的书面色彩，用在合同条款中语体不合。"}], "explanations": {"附加": "“附加”表示在价格之外另加一个条件，与句中“除了价格，还”相合。", "吃": "搭配：“吃”的宾语须是食物，条件不能被吃。", "吐": "语义：“吐”指把东西从口中排出，与条件无关，句中说不通。", "赐予": "语域：“赐予”带有上对下施予的书面色彩，用在合同条款中语体不合。"}, "sentence_index": 0, "correct_answer": "附加"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个月我的体重附加了三公斤。", "explanation": "这里应该用〈增加〉。附加用于在主要内容之外另加条件、说明等，体重、人数等数量的增长要用增加。"}, {"text": "他在汤里附加了一点盐。", "explanation": "这里应该用〈添加〉。附加强调另外附带上去的东西，把调料放进食物里要用添加。"}, {"text": "两国附加了外交关系。", "explanation": "这里应该用〈建立〉。附加不用于关系，两国之间确立外交关系要用建立。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2df51fa8-9f4e-4e02-8622-3dbc11859208') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12531, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "附加", "is_correct": true, "explanation": "“附加”表示在主要服务之外再加上别的服务，与“不要再”的语境相符。"}, {"text": "喝", "is_correct": false, "explanation": "搭配：“喝”的宾语须是饮品，服务不能被喝。"}, {"text": "摔", "is_correct": false, "explanation": "语义：“摔”指使物体猛然落下，服务不能被摔。"}, {"text": "哭", "is_correct": false, "explanation": "配价：“哭”是不及物动词，不能带“服务”这样的宾语。"}], "explanations": {"附加": "“附加”表示在主要服务之外再加上别的服务，与“不要再”的语境相符。", "喝": "搭配：“喝”的宾语须是饮品，服务不能被喝。", "摔": "语义：“摔”指使物体猛然落下，服务不能被摔。", "哭": "配价：“哭”是不及物动词，不能带“服务”这样的宾语。"}, "sentence_index": 6, "correct_answer": "附加"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我的英语水平附加了很多。", "explanation": "这里应该用〈提高〉。附加用于另外加上条件或内容，水平、质量的上升要用提高。"}, {"text": "这一局他们附加了胜利。", "explanation": "这里应该用〈赢得〉。附加表示另外加上东西，取得胜利要用赢得。"}, {"text": "今天的气温附加了五度。", "explanation": "这里应该用〈升高〉。附加用于另外加上条件、说明等，气温上升要用升高。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2df51fa8-9f4e-4e02-8622-3dbc11859208') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12531, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他把一条注释附加译文后面。", "corrected_sentence": "他把一条注释附加在译文后面。", "error_description": "错误：“附加译文后面”；正确：“附加在译文后面”。“附加”后面要用介词“在”引出附加的位置，不能省略。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2df51fa8-9f4e-4e02-8622-3dbc11859208') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12531, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们附加了过一项说明。", "corrected_sentence": "他们附加过一项说明。", "error_description": "错误：“附加了过”；正确：“附加过”。“了”表示完成，“过”表示经历，两者不能同时用在同一个动词后面。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2df51fa8-9f4e-4e02-8622-3dbc11859208') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
