INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12532, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "将信息转换为数字形式的过程或系统。", "primary_collocate": null, "pronunciation": "shù zì biān mǎ", "ipa": "ʂu˥˩ tsɨ˥˩ pjɛn˥ ma˨˩˦", "syllable_count": 4, "sentences": [{"text": "值得注意的是，其普及过程并非线性推进，而是伴随着各国本土化调整：例如在某些文化语境中，箭头形态被微调以避免宗教联想；而在另一些地区，则附加数字编码系统以细化分类标准。", "target_word": "数字编码", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "数字编码可以把声音变成电脑能读的信息。", "target_word": "数字编码", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这套系统用数字编码保存所有的图片。", "target_word": "数字编码", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "数字编码让信息传得更快。", "target_word": "数字编码", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学生们在课上学习数字编码的基本过程。", "target_word": "数字编码", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工程师正在设计一种新的数字编码系统。", "target_word": "数字编码", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手机里的音乐都经过数字编码。", "target_word": "数字编码", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "没有数字编码，电脑就无法处理照片。", "target_word": "数字编码", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他研究的是文字怎么变成数字编码。", "target_word": "数字编码", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "数字编码的好处是保存时不容易出错。", "target_word": "数字编码", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "数字编码系统", "label": "复合"}, {"form": "數字編碼", "label": "繁体"}], "register": "中性", "sense_fingerprint": "数字编码：把信息转换成数字形式的过程或系统", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '05657b60-f4ba-43e6-a05f-48f26d97bd9f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12532, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "数字编码", "is_correct": true, "explanation": "正确：数字编码指把信息转换为数字形式的系统，与“附加……系统以细化分类标准”的语境相符。"}, {"text": "修辞手法", "is_correct": false, "explanation": "搭配：“修辞手法”是表达方式，不能说“附加修辞手法系统”。"}, {"text": "地壳运动", "is_correct": false, "explanation": "语义：地壳运动是地质现象，与信息的分类标准无关。"}, {"text": "烹饪技术", "is_correct": false, "explanation": "语义：烹饪技术属于饮食领域，不能用来细化分类标准。"}], "explanations": {"数字编码": "正确：数字编码指把信息转换为数字形式的系统，与“附加……系统以细化分类标准”的语境相符。", "修辞手法": "搭配：“修辞手法”是表达方式，不能说“附加修辞手法系统”。", "地壳运动": "语义：地壳运动是地质现象，与信息的分类标准无关。", "烹饪技术": "语义：烹饪技术属于饮食领域，不能用来细化分类标准。"}, "sentence_index": 0, "correct_answer": "数字编码"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我用数字编码切开了苹果。", "explanation": "这里应该用〈刀〉。数字编码是把信息转换成数字的方法，不能用来切东西；切苹果要用〈刀〉。"}, {"text": "我们用数字编码拍了一张照片。", "explanation": "这里应该用〈相机〉。数字编码是信息的数字表示方法，不能用来拍照；拍照要用〈相机〉。"}, {"text": "我用数字编码浇了花。", "explanation": "这里应该用〈水壶〉。数字编码不能用来浇水；浇花要用〈水壶〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2df51fa8-9f4e-4e02-8622-3dbc11859208') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12532, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "数字编码", "is_correct": true, "explanation": "正确：音乐要转换成数字格式才能存进手机，“经过数字编码”正合语境。"}, {"text": "地震", "is_correct": false, "explanation": "语义：地震是自然灾害，不能用来处理音乐。"}, {"text": "台风", "is_correct": false, "explanation": "语义：台风是天气现象，与音乐的处理无关。"}, {"text": "感冒", "is_correct": false, "explanation": "搭配：“经过”后接的是处理方式，不能说“经过感冒”。"}], "explanations": {"数字编码": "正确：音乐要转换成数字格式才能存进手机，“经过数字编码”正合语境。", "地震": "语义：地震是自然灾害，不能用来处理音乐。", "台风": "语义：台风是天气现象，与音乐的处理无关。", "感冒": "搭配：“经过”后接的是处理方式，不能说“经过感冒”。"}, "sentence_index": 6, "correct_answer": "数字编码"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他用数字编码把日记烧掉了。", "explanation": "这里应该用〈火〉。数字编码是信息的数字表示方法，不能用来烧东西；烧掉日记要用〈火〉。"}, {"text": "她用数字编码把衣服洗干净了。", "explanation": "这里应该用〈洗衣机〉。数字编码是信息的数字表示方法，不能洗衣服；洗衣服要用〈洗衣机〉。"}, {"text": "工匠把木头数字编码成了佛像。", "explanation": "这里应该用〈雕刻〉。数字编码是把信息转为数字的方法，不能把实物雕成作品；雕佛像要用〈雕刻〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2df51fa8-9f4e-4e02-8622-3dbc11859208') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12532, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们学习了一只数字编码。", "corrected_sentence": "我们学习了一种数字编码。", "error_description": "量词错：数字编码应用量词“种”，不用“只”。正确说法是“一种数字编码”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2df51fa8-9f4e-4e02-8622-3dbc11859208') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12532, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们用一把数字编码保存照片。", "corrected_sentence": "我们用一种数字编码保存照片。", "error_description": "量词错：数字编码应用量词“种”，“把”用于有柄的器具，不能用于数字编码。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2df51fa8-9f4e-4e02-8622-3dbc11859208') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
