INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12537, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指语言符号（如词语、句子）所表达的意义或内容。", "primary_collocate": null, "pronunciation": "yǔ yì", "ipa": "y˨˩˦ i˥˩", "syllable_count": 2, "sentences": [{"text": "这个标志的语义随时代慢慢发生了变化。", "target_word": "语义", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这两个句子的语义不一样。", "target_word": "语义", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "翻译时，不但要看词，还要看语义。", "target_word": "语义", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个词的语义很广。", "target_word": "语义", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他分析了这句话的语义。", "target_word": "语义", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "机器很难完全明白人话的语义。", "target_word": "语义", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个句子语法对，但语义不通。", "target_word": "语义", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师问我们这个成语的语义是什么。", "target_word": "语义", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "同一个词，在不同句子里语义可能不同。", "target_word": "语义", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "语义清楚，别人才听得懂。", "target_word": "语义", "complexity_tier": "T1", "sentence_source": "generated"}], "morphological_forms": [{"form": "語義", "label": "繁体"}, {"form": "语义学", "label": "复合"}, {"form": "语义场", "label": "复合"}], "register": "书面", "sense_fingerprint": "语言符号所表达的意义或内容", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '08c39e3c-4375-4f78-8873-c3b87ac6f5e8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12537, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "语义", "is_correct": true, "explanation": "正确答案：语义（yǔ yì）。"}, {"text": "语气", "is_correct": false, "explanation": "qì（第四声）与 yì（第四声）声母不同，意思是语气。"}, {"text": "雨衣", "is_correct": false, "explanation": "yī（第一声）与 yì（第四声）声调不同，意思是雨衣。"}, {"text": "雨季", "is_correct": false, "explanation": "jì 与 yì 声母不同，意思是雨季。"}, {"text": "语系", "is_correct": false, "explanation": "xì 与 yì 声母不同，意思是语系。"}], "explanations": {"语义": "正确答案：语义（yǔ yì）。", "语气": "qì（第四声）与 yì（第四声）声母不同，意思是语气。", "雨衣": "yī（第一声）与 yì（第四声）声调不同，意思是雨衣。", "雨季": "jì 与 yì 声母不同，意思是雨季。", "语系": "xì 与 yì 声母不同，意思是语系。"}, "sentence_index": null, "correct_answer": "语义"}, "level_3": {"options": [{"text": "语义", "is_correct": true, "explanation": "正确：“语义”指意义，“标志的语义”随时代而变，符合句意。"}, {"text": "体育", "is_correct": false, "explanation": "语义：“体育”不能表示标志的意义，句中说的是意义的变化。"}, {"text": "赛车", "is_correct": false, "explanation": "语义：“赛车”不能表示标志的意义，与句意无关。"}, {"text": "牧业", "is_correct": false, "explanation": "搭配：“标志的牧业”不成立，牧业不是意义变化的对象。"}], "explanations": {"语义": "正确：“语义”指意义，“标志的语义”随时代而变，符合句意。", "体育": "语义：“体育”不能表示标志的意义，句中说的是意义的变化。", "赛车": "语义：“赛车”不能表示标志的意义，与句意无关。", "牧业": "搭配：“标志的牧业”不成立，牧业不是意义变化的对象。"}, "sentence_index": 0, "correct_answer": "语义"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的语义很丰富。", "explanation": "这里应该用〈情感〉。语义指词语或句子的意思，人的情感丰富不说语义。"}, {"text": "这个字的语义很好听。", "explanation": "这里应该用〈语音〉。语义是意思，“好听”形容声音，应说〈语音〉。"}, {"text": "今天的语义很好。", "explanation": "这里应该用〈天气〉。语义是意思，不能用来形容天气的好坏。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a006eb5-8ab0-4166-b354-14c01c2e7e95') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12537, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "语义", "is_correct": true, "explanation": "正确：语义指语言的意义，与“语法对”形成对比。"}, {"text": "语法", "is_correct": false, "explanation": "语义：题干说“语法对”，再说“语法不通”自相矛盾。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色不属于句子的意义，“不通”无法用来修饰颜色。"}, {"text": "发音", "is_correct": false, "explanation": "搭配：“发音不通”不成搭配，不能说发音不通。"}], "explanations": {"语义": "正确：语义指语言的意义，与“语法对”形成对比。", "语法": "语义：题干说“语法对”，再说“语法不通”自相矛盾。", "颜色": "语义：颜色不属于句子的意义，“不通”无法用来修饰颜色。", "发音": "搭配：“发音不通”不成搭配，不能说发音不通。"}, "sentence_index": 6, "correct_answer": "语义"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这座山的语义很高。", "explanation": "这里应该用〈海拔〉。语义指意思，山的高度要说〈海拔〉。"}, {"text": "这件衣服的语义很合身。", "explanation": "这里应该用〈尺码〉。语义指意思，衣服合不合身说的是〈尺码〉。"}, {"text": "这块地的语义很肥沃。", "explanation": "这里应该用〈土壤〉。语义指意思，土地肥沃要说〈土壤〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a006eb5-8ab0-4166-b354-14c01c2e7e95') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12537, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个复合词的语义很容易吃。", "corrected_sentence": "这个复合词的语义很容易懂。", "error_description": "“语义”要用“懂”“理解”一类动词来说明，不能用“吃”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a006eb5-8ab0-4166-b354-14c01c2e7e95') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12537, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老师把这个词的语义解释。", "corrected_sentence": "老师把这个词的语义解释清楚。", "error_description": "“把”字句的动词不能单独结尾，后面要有补语，应说“把这个词的语义解释清楚”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a006eb5-8ab0-4166-b354-14c01c2e7e95') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
