INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12539, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用旧材料制造新产品的过程", "primary_collocate": null, "pronunciation": "zài shēng", "ipa": "tsaɪ̯˥˩ ʂɤŋ˥", "syllable_count": 2, "sentences": [{"text": "它不再仅指向物理层面的材料再生，更被赋予伦理与政治维度——消费者通过识别此符号，参与一场隐性的公民实践，表达对过度生产模式的反思。", "target_word": "再生", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "其本质在于将有机物质通过微生物的代谢作用，转化为富含腐殖质的稳定有机肥，从而实现食物残渣的闭环再生。", "target_word": "再生", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "旧塑料经过处理可以再生，变成新的瓶子。", "target_word": "再生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "废纸再生需要很多水和电。", "target_word": "再生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家工厂专门做废金属的再生。", "target_word": "再生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "玻璃可以反复再生，质量不会变差。", "target_word": "再生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "旧衣服再生以后，能做成新的布。", "target_word": "再生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "城市里的废料再生，能减少很多垃圾。", "target_word": "再生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种材料再生的成本很低。", "target_word": "再生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "旧轮胎再生后可以铺在操场上。", "target_word": "再生", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "再生纸", "label": "复合"}, {"form": "再生塑料", "label": "复合"}], "register": "中性", "sense_fingerprint": "旧材料经过加工，重新制成新产品", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f3c9b1ce-420a-4bbc-97dd-366c624344ba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12539, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "再生", "is_correct": true, "explanation": "正确答案：再生（zài shēng），指用旧材料制造新产品。"}, {"text": "再争", "is_correct": false, "explanation": "zhēng 与 shēng 声母不同（zh／sh），意思是争取，不是再生。"}, {"text": "再称", "is_correct": false, "explanation": "chēng 与 shēng 声母不同（ch／sh），意思是再称一次重量。"}, {"text": "再深", "is_correct": false, "explanation": "shēn 与 shēng 韵尾不同（n／ng），意思是再深一些。"}, {"text": "再省", "is_correct": false, "explanation": "shěng（第三声）与 shēng（第一声）声调不同，意思是再节省。"}, {"text": "再胜", "is_correct": false, "explanation": "shèng（第四声）与 shēng（第一声）声调不同，意思是再次获胜。"}], "explanations": {"再生": "正确答案：再生（zài shēng），指用旧材料制造新产品。", "再争": "zhēng 与 shēng 声母不同（zh／sh），意思是争取，不是再生。", "再称": "chēng 与 shēng 声母不同（ch／sh），意思是再称一次重量。", "再深": "shēn 与 shēng 韵尾不同（n／ng），意思是再深一些。", "再省": "shěng（第三声）与 shēng（第一声）声调不同，意思是再节省。", "再胜": "shèng（第四声）与 shēng（第一声）声调不同，意思是再次获胜。"}, "sentence_index": null, "correct_answer": "再生"}, "level_3": {"options": [{"text": "再生", "is_correct": true, "explanation": "正确：“材料再生”指旧材料加工后重新成为可用材料，与前文的伦理与政治语境相符。"}, {"text": "销毁", "is_correct": false, "explanation": "语义：销毁是彻底毁掉，与“赋予伦理维度”所指的再利用意义相反。"}, {"text": "填埋", "is_correct": false, "explanation": "语义：填埋是丢弃处理，与消费者识别符号、参与公民实践的语境不符。"}, {"text": "报废", "is_correct": false, "explanation": "语义：报废指物品失去使用价值而作废，与句中材料被重新利用、反思过度生产的语境不符。"}], "explanations": {"再生": "正确：“材料再生”指旧材料加工后重新成为可用材料，与前文的伦理与政治语境相符。", "销毁": "语义：销毁是彻底毁掉，与“赋予伦理维度”所指的再利用意义相反。", "填埋": "语义：填埋是丢弃处理，与消费者识别符号、参与公民实践的语境不符。", "报废": "语义：报废指物品失去使用价值而作废，与句中材料被重新利用、反思过度生产的语境不符。"}, "sentence_index": 0, "correct_answer": "再生"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈把脏衣服再生干净了。", "explanation": "这里应该用〈清洗〉。再生指旧材料加工成新产品，把脏衣服洗干净要用“清洗”，不能说“再生”。"}, {"text": "工人正在再生这套房子。", "explanation": "这里应该用〈装修〉。再生指旧材料加工成新产品，房子要“装修”，不能说“再生”。"}, {"text": "医生正在再生这位病人。", "explanation": "这里应该用〈治疗〉。再生指旧材料加工成新产品，对病人要“治疗”，不能说“再生”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '65de5bc4-b62f-4ec2-9482-df726991680b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12539, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "再生", "is_correct": true, "explanation": "正确答案：再生（zài shēng），指用旧材料制造新产品。"}, {"text": "再扔", "is_correct": false, "explanation": "rēng 与 shēng 声母不同（r／sh），意思是再扔掉。"}, {"text": "再伸", "is_correct": false, "explanation": "shēn 与 shēng 韵尾不同（n／ng），意思是再伸展。"}, {"text": "再盛", "is_correct": false, "explanation": "shèng（第四声）与 shēng（第一声）声调不同，意思是再盛一碗饭。"}], "explanations": {"再生": "正确答案：再生（zài shēng），指用旧材料制造新产品。", "再扔": "rēng 与 shēng 声母不同（r／sh），意思是再扔掉。", "再伸": "shēn 与 shēng 韵尾不同（n／ng），意思是再伸展。", "再盛": "shèng（第四声）与 shēng（第一声）声调不同，意思是再盛一碗饭。"}, "sentence_index": null, "correct_answer": "再生"}, "level_3": {"options": [{"text": "再生", "is_correct": true, "explanation": "正确：旧衣服经加工重新成为材料，才能做成新的布，符合“再生”的意思。"}, {"text": "销毁", "is_correct": false, "explanation": "语义：销毁是彻底毁掉，与“能做成新的布”的结果矛盾。"}, {"text": "丢弃", "is_correct": false, "explanation": "语义：丢弃是扔掉，与“能做成新的布”的结果矛盾。"}, {"text": "烧毁", "is_correct": false, "explanation": "语义：烧毁会把衣服烧成灰，无法再做成布。"}], "explanations": {"再生": "正确：旧衣服经加工重新成为材料，才能做成新的布，符合“再生”的意思。", "销毁": "语义：销毁是彻底毁掉，与“能做成新的布”的结果矛盾。", "丢弃": "语义：丢弃是扔掉，与“能做成新的布”的结果矛盾。", "烧毁": "语义：烧毁会把衣服烧成灰，无法再做成布。"}, "sentence_index": 6, "correct_answer": "再生"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的计划很快就再生了。", "explanation": "这里应该用〈恢复〉。再生指旧材料加工成新产品，计划重新开始要说“恢复”，不能说“再生”。"}, {"text": "这幅古画经过修复，基本再生了。", "explanation": "这里应该用〈复原〉。再生是把旧材料制成新产品，古画受损后要“复原”，不能说“再生”。"}, {"text": "这条漏水的管子已经自己再生好了。", "explanation": "这里应该用〈修补〉。再生指旧材料加工成新产品，漏水的管子要“修补”，不能说“再生”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '65de5bc4-b62f-4ec2-9482-df726991680b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12539, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这种旧瓶子再生了新的杯子。", "corrected_sentence": "这种旧瓶子再生成了新的杯子。", "error_description": "“再生”后漏掉了结果补语“成”。表示加工成某种新物品，要说“再生成”，直接接宾语“新的杯子”不自然。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '65de5bc4-b62f-4ec2-9482-df726991680b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12539, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这批旧纸还没再生了，先放在仓库里。", "corrected_sentence": "这批旧纸还没再生，先放在仓库里。", "error_description": "“了”用错了位置：“还没”表示尚未发生，否定结构中动词后不能加“了”，应说“这批旧纸还没再生”，不能说“还没再生了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '65de5bc4-b62f-4ec2-9482-df726991680b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
