INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12543, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "指对某个问题或话题进行深入的研究和讨论，以寻求理解或解决方案。", "primary_collocate": null, "pronunciation": "tàn tǎo", "ipa": "tʰan˥˩ tʰɑʊ̯˨˩˦", "syllable_count": 2, "sentences": [{"text": "专家们在会上探讨了环境保护的问题。", "target_word": "探讨", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们需要深入探讨这个问题。", "target_word": "探讨", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这篇文章探讨了城市交通的未来。", "target_word": "探讨", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学者们正在探讨语言学习的方法。", "target_word": "探讨", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "课上，老师和学生一起探讨人生的意义。", "target_word": "探讨", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这本书探讨的是中国家庭的变化。", "target_word": "探讨", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们花了三个小时探讨公司的发展方向。", "target_word": "探讨", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个问题值得我们认真探讨。", "target_word": "探讨", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "大会将探讨教育改革的新办法。", "target_word": "探讨", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "研究人员探讨了睡眠和健康的关系。", "target_word": "探讨", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "探讨了", "label": "体标"}, {"form": "探讨过", "label": "体标"}], "register": "书面", "sense_fingerprint": "对问题或话题进行深入的研究和讨论", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '08c39e3c-4375-4f78-8873-c3b87ac6f5e8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12543, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "探讨", "is_correct": true, "explanation": "正确：「探讨」指深入研究讨论问题，与“环境保护的问题”搭配。"}, {"text": "修理", "is_correct": false, "explanation": "语义：“修理”针对器物，不能用来处理“环境保护的问题”。"}, {"text": "搬", "is_correct": false, "explanation": "配价：“搬”的宾语应是具体物品，不能搬“问题”。"}, {"text": "砍", "is_correct": false, "explanation": "语义：“砍”是用刀斧切断，与会上讨论问题的意思不符。"}], "explanations": {"探讨": "正确：「探讨」指深入研究讨论问题，与“环境保护的问题”搭配。", "修理": "语义：“修理”针对器物，不能用来处理“环境保护的问题”。", "搬": "配价：“搬”的宾语应是具体物品，不能搬“问题”。", "砍": "语义：“砍”是用刀斧切断，与会上讨论问题的意思不符。"}, "sentence_index": 0, "correct_answer": "探讨"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "医生正在探讨病人的身体。", "explanation": "这里应该用〈检查〉。探讨用于问题和话题，不能用于具体的人身体。"}, {"text": "工人们正在探讨地下的矿藏。", "explanation": "这里应该用〈挖掘〉。探讨针对抽象的问题，不能用于开采具体的矿藏。"}, {"text": "我们每天探讨教室。", "explanation": "这里应该用〈打扫〉。探讨的对象是问题或话题，不能是教室这样的场所。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a006eb5-8ab0-4166-b354-14c01c2e7e95') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12543, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "探讨", "is_correct": true, "explanation": "正确：「探讨」指深入研究讨论问题，与“公司的发展方向”搭配。"}, {"text": "喝", "is_correct": false, "explanation": "语义：“喝”针对饮品，不能用于“发展方向”。"}, {"text": "擦", "is_correct": false, "explanation": "语义：“擦”是抹去物体表面的动作，不能擦“发展方向”。"}, {"text": "拆", "is_correct": false, "explanation": "配价：“拆”要求具体的宾语，不能拆“发展方向”。"}], "explanations": {"探讨": "正确：「探讨」指深入研究讨论问题，与“公司的发展方向”搭配。", "喝": "语义：“喝”针对饮品，不能用于“发展方向”。", "擦": "语义：“擦”是抹去物体表面的动作，不能擦“发展方向”。", "拆": "配价：“拆”要求具体的宾语，不能拆“发展方向”。"}, "sentence_index": 6, "correct_answer": "探讨"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他用探讨的力气推开了窗户。", "explanation": "这里应该用〈用力〉。探讨指对问题的讨论，不能拿来形容“力气”。"}, {"text": "老师探讨了那个学生。", "explanation": "这里应该用〈批评〉。探讨的对象是问题或话题，不能是人。"}, {"text": "他用拳头探讨桌子。", "explanation": "这里应该用〈敲〉。探讨是对话题的交流，不能用拳头作用于具体的物体。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a006eb5-8ab0-4166-b354-14c01c2e7e95') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12543, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们探讨了很深入。", "corrected_sentence": "我们探讨得很深入。", "error_description": "“探讨”后接程度补语要用“得”，不能用“了”。应说“探讨得很深入”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a006eb5-8ab0-4166-b354-14c01c2e7e95') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12543, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们明天探讨了这个方案。", "corrected_sentence": "我们明天探讨这个方案。", "error_description": "“明天”表示将来，“探讨”后不能加表示完成的“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a006eb5-8ab0-4166-b354-14c01c2e7e95') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
