INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12545, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "效力指事物或行为所产生的积极作用或效果。", "primary_collocate": null, "pronunciation": "xiào lì", "ipa": "ɕjaʊ˥˩ li˥˩", "syllable_count": 2, "sentences": [{"text": "这种药的效力很强，吃一次就够了。", "target_word": "效力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "过了一年，这瓶药已经没有效力了。", "target_word": "效力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "广告的效力很大，很多人都去买了。", "target_word": "效力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生说这种疫苗的效力不太好。", "target_word": "效力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种清洁剂的效力能保持一个月。", "target_word": "效力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天气太热，药的效力会变弱。", "target_word": "效力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种杀虫剂的效力很强，蚊子都不见了。", "target_word": "效力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师想知道这种新药有没有效力。", "target_word": "效力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "药放太久，效力会慢慢变小。", "target_word": "效力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我不信这种保健品有什么效力。", "target_word": "效力", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "药、方法等事物产生的积极作用或效果", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ef6af6ef-c707-4f59-9d9e-398da924d540') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12545, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "效力", "is_correct": true, "explanation": "效力指事物产生的积极作用，即正确答案。"}, {"text": "效率", "is_correct": false, "explanation": "lǜ（第四声）与 lì（第四声）韵母不同（ü 与 i），意思是效率（单位时间内的工作量）。"}, {"text": "效益", "is_correct": false, "explanation": "yì 与 lì 声母不同（零声母与 l），意思是效益（经济上的收益）。"}, {"text": "小利", "is_correct": false, "explanation": "xiǎo（第三声）与 xiào（第四声）声调不同，意思是小利（微小的好处）。"}, {"text": "下力", "is_correct": false, "explanation": "xià 与 xiào 韵母不同（ia 与 iao），意思是下力（用力气）。"}], "explanations": {"效力": "效力指事物产生的积极作用，即正确答案。", "效率": "lǜ（第四声）与 lì（第四声）韵母不同（ü 与 i），意思是效率（单位时间内的工作量）。", "效益": "yì 与 lì 声母不同（零声母与 l），意思是效益（经济上的收益）。", "小利": "xiǎo（第三声）与 xiào（第四声）声调不同，意思是小利（微小的好处）。", "下力": "xià 与 xiào 韵母不同（ia 与 iao），意思是下力（用力气）。"}, "sentence_index": null, "correct_answer": "效力"}, "level_3": {"options": [{"text": "效力", "is_correct": true, "explanation": "效力指药物等产生的作用，“很强”形容作用的大小，与语境相符。"}, {"text": "价格", "is_correct": false, "explanation": "搭配：“强”形容力量或作用，不能形容价格，这里应说“价格高”。"}, {"text": "数量", "is_correct": false, "explanation": "搭配：“很强”不用于形容数量，数量多应说“很多”或“很大”。"}, {"text": "包装", "is_correct": false, "explanation": "语义：包装指外面的包裹，与药的作用无关，“很强”说的是药效。"}], "explanations": {"效力": "效力指药物等产生的作用，“很强”形容作用的大小，与语境相符。", "价格": "搭配：“强”形容力量或作用，不能形容价格，这里应说“价格高”。", "数量": "搭配：“很强”不用于形容数量，数量多应说“很多”或“很大”。", "包装": "语义：包装指外面的包裹，与药的作用无关，“很强”说的是药效。"}, "sentence_index": 0, "correct_answer": "效力"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这台机器每小时的效力是五百个，一天就能做完一万个。", "explanation": "这里应该用〈产量〉。产量指生产的数量，可以计件；效力指事物产生的作用，不能用件数来表示。"}, {"text": "这家工厂去年的效力是三百万，利润增加了一倍。", "explanation": "这里应该用〈效益〉。效益指经济上的收益；效力指事物产生的作用，不能用金额来表示。"}, {"text": "这位新员工的效力很强，三天就学会了所有的操作。", "explanation": "这里应该用〈能力〉。能力指做事的本领，用于人；效力指事物产生的作用，不用来形容人的本领。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70862c4f-9612-4d02-b2b4-d21b6887d210') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12545, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "效力", "is_correct": true, "explanation": "效力指事物产生的积极作用，即正确答案。"}, {"text": "笑料", "is_correct": false, "explanation": "liào（第四声）与 lì（第四声）韵母不同（iao 与 i），意思是笑料（引人发笑的材料）。"}, {"text": "小吏", "is_correct": false, "explanation": "xiǎo（第三声）与 xiào（第四声）声调不同，意思是小吏（级别低的官员）。"}, {"text": "小粒", "is_correct": false, "explanation": "xiǎo（第三声）与 xiào（第四声）声调不同，意思是小粒（细小的颗粒）。"}], "explanations": {"效力": "效力指事物产生的积极作用，即正确答案。", "笑料": "liào（第四声）与 lì（第四声）韵母不同（iao 与 i），意思是笑料（引人发笑的材料）。", "小吏": "xiǎo（第三声）与 xiào（第四声）声调不同，意思是小吏（级别低的官员）。", "小粒": "xiǎo（第三声）与 xiào（第四声）声调不同，意思是小粒（细小的颗粒）。"}, "sentence_index": null, "correct_answer": "效力"}, "level_3": {"options": [{"text": "效力", "is_correct": true, "explanation": "效力指杀虫剂产生的作用，“很强”和“蚊子都不见了”都指向药效。"}, {"text": "重量", "is_correct": false, "explanation": "搭配：“强”不能形容重量，重量大应说“重”。"}, {"text": "名字", "is_correct": false, "explanation": "语义：名字只是称呼，与“蚊子都不见了”的杀虫作用无关。"}, {"text": "年龄", "is_correct": false, "explanation": "搭配：“强”形容力量，不能用来形容年龄，年龄应说“大”或“小”。"}], "explanations": {"效力": "效力指杀虫剂产生的作用，“很强”和“蚊子都不见了”都指向药效。", "重量": "搭配：“强”不能形容重量，重量大应说“重”。", "名字": "语义：名字只是称呼，与“蚊子都不见了”的杀虫作用无关。", "年龄": "搭配：“强”形容力量，不能用来形容年龄，年龄应说“大”或“小”。"}, "sentence_index": 6, "correct_answer": "效力"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他用尽全身的效力推开了门。", "explanation": "这里应该用〈力气〉。力气指人的体力，用于推、举等动作；效力指事物产生的作用，不能用来说人的体力。"}, {"text": "这套新系统每天的效力是两千份，比旧的多一倍。", "explanation": "这里应该用〈处理量〉。处理量指系统能处理的数量；效力指事物产生的作用，不能用份数来表示。"}, {"text": "他很愿意为客人效力，每天都帮客人搬行李。", "explanation": "这里应该用〈服务〉。服务指为别人做事，用于人；本题所教的效力是名词，指事物产生的作用，不用来说帮人做事。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70862c4f-9612-4d02-b2b4-d21b6887d210') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12545, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这种喷雾很效力强，能保持一个星期。", "corrected_sentence": "这种喷雾的效力强，能保持一个星期。", "error_description": "“效力”是名词，前面不能直接加副词“很”修饰；应在“效力”前用“的”连接，说“的效力强”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70862c4f-9612-4d02-b2b4-d21b6887d210') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12545, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这种药不有效力，我们不要再买了。", "corrected_sentence": "这种药没有效力，我们不要再买了。", "error_description": "“有”的否定要用“没”，不用“不”；应说“没有效力”，不说“不有效力”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70862c4f-9612-4d02-b2b4-d21b6887d210') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
