INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12546, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "物质在环境中被分解并重新利用的过程", "primary_collocate": null, "pronunciation": "dài xiè", "ipa": "taɪ̯⁵¹ ɕjɛ⁵¹", "syllable_count": 2, "sentences": [{"text": "学术界亦开始探讨其作为“视觉修辞”的效力：一方面，它成功将复杂的资源代谢过程简化为可被大众认知的符号；另一方面，批评者指出，这种美学化的呈现可能遮蔽回收系统的实际局限，例如某些塑料的低再利用率或全球废料贸易中的不平等结构。", "target_word": "代谢", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这标志着材料科学正从“制造-废弃”线性模式，转向与自然代谢系统深度融合的生态文明范式。", "target_word": "代谢", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "森林里的落叶，通过自然代谢变成了肥料。", "target_word": "代谢", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "河水里的物质代谢很快，水才能保持干净。", "target_word": "代谢", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "自然界的物质代谢，让资源可以重复使用。", "target_word": "代谢", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "土地里的微生物能加快有机物的代谢。", "target_word": "代谢", "complexity_tier": "T3", "furigana": "tǔdì lǐ de wēishēngwù néng jiākuài yǒujīwù de dàixiè", "sentence_source": "generated"}, {"text": "木材埋在地里，代谢很慢，要很多年才能完成。", "target_word": "代谢", "complexity_tier": "T3", "furigana": "mùcái mái zài dì lǐ, dàixiè hěn màn, yào hěn duō nián cái néng wánchéng", "sentence_source": "generated"}, {"text": "海洋里的物质代谢，需要阳光和合适的温度。", "target_word": "代谢", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "把落叶放进土里，能加快物质的代谢。", "target_word": "代谢", "complexity_tier": "T3", "furigana": "bǎ luòyè fàng jìn tǔ lǐ, néng jiākuài wùzhì de dàixiè", "sentence_source": "generated"}, {"text": "森林是地球上物质代谢最快的地方之一。", "target_word": "代谢", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "代謝", "label": "繁体"}], "register": "书面", "sense_fingerprint": "自然环境中物质分解并循环再利用", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c708da23-8b74-483b-bea2-78da0da78450') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12546, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "代谢", "is_correct": true, "explanation": "“代谢”指物质被分解并重新利用的过程，与“资源”搭配，符合句意。"}, {"text": "修辞", "is_correct": false, "explanation": "语义：资源不是修辞的过程，前文已用“视觉修辞”，此处不合。"}, {"text": "美学", "is_correct": false, "explanation": "搭配：“资源美学”不成立，“美学”不能用来修饰“资源”作定语。"}, {"text": "标签", "is_correct": false, "explanation": "语义：标签是符号，不是资源被分解的过程，与“过程”搭配不合。"}], "explanations": {"代谢": "“代谢”指物质被分解并重新利用的过程，与“资源”搭配，符合句意。", "修辞": "语义：资源不是修辞的过程，前文已用“视觉修辞”，此处不合。", "美学": "搭配：“资源美学”不成立，“美学”不能用来修饰“资源”作定语。", "标签": "语义：标签是符号，不是资源被分解的过程，与“过程”搭配不合。"}, "sentence_index": 0, "correct_answer": "代谢"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这块铁在水里放了很久，代谢得很快。", "explanation": "这里应该用〈生锈〉。代谢指物质被分解并重新利用的过程，铁被锈蚀不是重新利用，不能用代谢来说。"}, {"text": "这台发电机每天代谢大量的煤。", "explanation": "这里应该用〈消耗〉。煤被烧掉是能源的消耗，不是物质在环境中被分解并重新利用，不能用代谢。"}, {"text": "这家工厂排出的废气让周围的空气代谢了。", "explanation": "这里应该用〈污染〉。废气使空气变脏是有害的改变，不是物质被分解并重新利用，代谢不能用于这种情况。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9887ccc-ea02-4a69-9a01-abd713e7242c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12546, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "代谢", "is_correct": true, "explanation": "“代谢”是过程，可以用“很慢”来描述其快慢，符合句意。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气不会“很慢”，与句中描述的分解过程不合。"}, {"text": "价格", "is_correct": false, "explanation": "搭配：“价格”一般说“高”“低”，不说“很慢”。"}, {"text": "身高", "is_correct": false, "explanation": "语义：身高不存在快慢之分，句子说的是分解过程。"}], "explanations": {"代谢": "“代谢”是过程，可以用“很慢”来描述其快慢，符合句意。", "天气": "语义：天气不会“很慢”，与句中描述的分解过程不合。", "价格": "搭配：“价格”一般说“高”“低”，不说“很慢”。", "身高": "语义：身高不存在快慢之分，句子说的是分解过程。"}, "sentence_index": 6, "correct_answer": "代谢"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个仓库的粮食代谢很充足，所以从不缺货。", "explanation": "这里应该用〈储备〉。代谢指物质被分解并重新利用的过程，不指存放的数量，用它说粮食充足是误用。"}, {"text": "这条马路的代谢很快，每天都要修补。", "explanation": "这里应该用〈磨损〉。代谢指物质被分解并重新利用的过程，马路的损耗需要修补，不能说代谢。"}, {"text": "这块电池的代谢很快，充一次电只能用两小时。", "explanation": "这里应该用〈耗电〉。电池放电是能量的消耗，不是物质被分解并重新利用，不能用代谢。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9887ccc-ea02-4a69-9a01-abd713e7242c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12546, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这是一只自然界的物质代谢。", "corrected_sentence": "这是一种自然界的物质代谢。", "error_description": "错误形式：“一只物质代谢”。正确形式：“一种物质代谢”。原因：“只”多用于动物或成对的物件，抽象过程名词“代谢”应用量词“种”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9887ccc-ea02-4a69-9a01-abd713e7242c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12546, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这片草原的物质代谢的很快，植物长得很茂盛。", "corrected_sentence": "这片草原的物质代谢很快，植物长得很茂盛。", "error_description": "错误形式：「代谢的很快」。正确形式：「代谢很快」。原因：「很快」作谓语直接跟在主语「物质代谢」后，中间不能插入结构助词「的」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9887ccc-ea02-4a69-9a01-abd713e7242c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12547, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "复杂化", "is_correct": true, "explanation": "复杂化指使事物变得复杂，与“简化”意思相反。"}, {"text": "研究", "is_correct": false, "explanation": "研究指深入探讨，与“简化”没有反义关系。"}, {"text": "保存", "is_correct": false, "explanation": "保存指留存不丢失，与“简化”没有反义关系。"}, {"text": "扩大", "is_correct": false, "explanation": "扩大指使范围变大，不是“简化”的反义词。"}], "correct_answer": "复杂化", "explanations": {"复杂化": "复杂化指使事物变得复杂，与“简化”意思相反。", "研究": "研究指深入探讨，与“简化”没有反义关系。", "保存": "保存指留存不丢失，与“简化”没有反义关系。", "扩大": "扩大指使范围变大，不是“简化”的反义词。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70862c4f-9612-4d02-b2b4-d21b6887d210') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12547, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "复杂化", "is_correct": true, "explanation": "复杂化指使事物变得复杂，与“简化”意思相反。"}, {"text": "打开", "is_correct": false, "explanation": "打开指使封闭的东西敞开，与“简化”没有反义关系。"}, {"text": "装饰", "is_correct": false, "explanation": "装饰指美化外表，与“简化”没有反义关系。"}, {"text": "讨论", "is_correct": false, "explanation": "讨论指交流意见，与“简化”没有反义关系。"}], "correct_answer": "复杂化", "explanations": {"复杂化": "复杂化指使事物变得复杂，与“简化”意思相反。", "打开": "打开指使封闭的东西敞开，与“简化”没有反义关系。", "装饰": "装饰指美化外表，与“简化”没有反义关系。", "讨论": "讨论指交流意见，与“简化”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70862c4f-9612-4d02-b2b4-d21b6887d210') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12547, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把复杂的事物变得简单，减少不必要的部分。", "primary_collocate": null, "pronunciation": "jiǎn huà", "ipa": "tɕjɛn˨˩˦ xwa˥˩", "syllable_count": 2, "sentences": [{"text": "学术界亦开始探讨其作为“视觉修辞”的效力：一方面，它成功将复杂的资源代谢过程简化为可被大众认知的符号；另一方面，批评者指出，这种美学化的呈现可能遮蔽回收系统的实际局限，例如某些塑料的低再利用率或全球废料贸易中的不平等结构。", "target_word": "简化", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "我们应该简化这张复杂的地图。", "target_word": "简化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师把难懂的句子简化了。", "target_word": "简化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司简化了复杂的办事手续。", "target_word": "简化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想把这个故事简化一点儿。", "target_word": "简化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "太复杂的图案可以简化成几条线。", "target_word": "简化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你把这份报告简化成一页纸。", "target_word": "简化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个流程太长了，必须简化。", "target_word": "简化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "汉字简化后，写起来更容易。", "target_word": "简化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把复杂的计算简化成了三步。", "target_word": "简化", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "简化了", "label": "体标"}, {"form": "简化过", "label": "体标"}, {"form": "簡化", "label": "繁体"}], "register": "中性", "sense_fingerprint": "把复杂的事物变得简单，去掉多余部分", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ef6af6ef-c707-4f59-9d9e-398da924d540') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12547, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "简化", "is_correct": true, "explanation": "简化指把复杂的事物变简单，此处指把复杂的过程变成符号，符合语境。"}, {"text": "扩大", "is_correct": false, "explanation": "语义：扩大与“简化”意思相反，“扩大为符号”不通。"}, {"text": "删除", "is_correct": false, "explanation": "语义：删除指去掉，去掉之后东西就没有了，不能“删除为符号”。"}, {"text": "增加", "is_correct": false, "explanation": "搭配：“增加”说数量变多，不能用来说过程变成符号。"}], "explanations": {"简化": "简化指把复杂的事物变简单，此处指把复杂的过程变成符号，符合语境。", "扩大": "语义：扩大与“简化”意思相反，“扩大为符号”不通。", "删除": "语义：删除指去掉，去掉之后东西就没有了，不能“删除为符号”。", "增加": "搭配：“增加”说数量变多，不能用来说过程变成符号。"}, "sentence_index": 0, "correct_answer": "简化"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家公司简化了三分之一的员工，效率提高了。", "explanation": "这里应该用〈精简〉。精简指减少人员或机构，用于人员；简化指把复杂的事变简单，不能说“简化员工”。"}, {"text": "这个月我们简化了这块地的面积，现在小了不少。", "explanation": "这里应该用〈缩小〉。缩小指使面积变小，用于面积、范围；简化指把复杂的事变简单，不用来说面积变小。"}, {"text": "他简化了这杯水的温度，现在可以喝了。", "explanation": "这里应该用〈降低〉。降低指使温度、数量变低，用于温度、价格；简化指把复杂的事变简单，不说“简化温度”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70862c4f-9612-4d02-b2b4-d21b6887d210') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12547, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "简化", "is_correct": true, "explanation": "简化指把复杂的报告变短，“成一页纸”是它的结果，符合句意。"}, {"text": "扩充", "is_correct": false, "explanation": "语义：扩充指增加内容使变多，与“简化”意思相反，不能说“扩充成一页纸”。"}, {"text": "装饰", "is_correct": false, "explanation": "语义：装饰指美化外表，与报告变成一页纸无关。"}, {"text": "点燃", "is_correct": false, "explanation": "搭配：“点燃”用于火、灯等，不能用于报告。"}], "explanations": {"简化": "简化指把复杂的报告变短，“成一页纸”是它的结果，符合句意。", "扩充": "语义：扩充指增加内容使变多，与“简化”意思相反，不能说“扩充成一页纸”。", "装饰": "语义：装饰指美化外表，与报告变成一页纸无关。", "点燃": "搭配：“点燃”用于火、灯等，不能用于报告。"}, "sentence_index": 6, "correct_answer": "简化"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个软件简化了文件的大小，传输更快。", "explanation": "这里应该用〈压缩〉。压缩指减小体积，用于文件、空间；简化指把复杂的事变简单，不能用于说文件大小的减小。"}, {"text": "这次改革简化了办手续的时间。", "explanation": "这里应该用〈缩短〉。缩短指使时间变少，用于时间、距离；简化指把复杂的事变简单，不说“简化时间”。"}, {"text": "老师简化了作业里的错误。", "explanation": "这里应该用〈改正〉。改正指把错误改对；简化指把复杂的事变简单，不能用来说处理错误。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70862c4f-9612-4d02-b2b4-d21b6887d210') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12547, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他已经把这套规则简化。", "corrected_sentence": "他已经把这套规则简化了。", "error_description": "“把”字句中动词后面要有“了”或补语等成分，说明动作完成或结果；“简化”后应加“了”，说“简化了”，不能只说“把这套规则简化”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70862c4f-9612-4d02-b2b4-d21b6887d210') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12547, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "请你这些资料简化成一页纸。", "corrected_sentence": "请你把这些资料简化成一页纸。", "error_description": "“简化”是处置类动词，“这些资料”作受处置的宾语要放在动词前，需要用“把”引出，应说“请你把这些资料简化成一页纸”，漏掉“把”就不成立。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70862c4f-9612-4d02-b2b4-d21b6887d210') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
