INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12548, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "批评者指对某人或某事提出负面评价、指出缺点或错误的人。", "primary_collocate": null, "pronunciation": "pī píng zhě", "ipa": "pʰi˥ pʰiŋ˧˥ ʈʂɤ˨˩˦", "syllable_count": 3, "sentences": [{"text": "学术界亦开始探讨其作为“视觉修辞”的效力：一方面，它成功将复杂的资源代谢过程简化为可被大众认知的符号；另一方面，批评者指出，这种美学化的呈现可能遮蔽回收系统的实际局限，例如某些塑料的低再利用率或全球废料贸易中的不平等结构。", "target_word": "批评者", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "批评者说这个计划有很多问题。", "target_word": "批评者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是一位认真的批评者。", "target_word": "批评者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "批评者的话有时很难听。", "target_word": "批评者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位批评者指出了书中的错误。", "target_word": "批评者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "批评者们对新电影不太满意。", "target_word": "批评者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "市长很少听批评者的意见。", "target_word": "批评者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有些批评者只说缺点，不说优点。", "target_word": "批评者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从一个批评者变成了朋友。", "target_word": "批评者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "批评者提出的问题，我们要认真想一想。", "target_word": "批评者", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "批评者们", "label": "复数"}, {"form": "批評者", "label": "繁体"}], "register": "中性", "sense_fingerprint": "对人或事提出负面评价、指出缺点错误的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ef6af6ef-c707-4f59-9d9e-398da924d540') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
